@dataclass
class ThermoData:
    """Thermodynamic data container"""
    name: str
    formula: str
    delta_h_298: float  # Standard enthalpy of formation (kJ/mol)
    s_298: float        # Standard entropy (J/mol/K)
    cp_coeffs: List[float]  # Heat capacity coefficients
    v_298: float        # Molar volume (J/bar)
    alpha: float        # Thermal expansion coefficient
    beta: float         # Compressibility coefficient

@dataclass
class PhaseComponent:
    """Individual phase component"""
    name: str
    mole_fraction: float
    activity_coefficient: float
    activity: float

class ActivityModel:
    """Activity-composition relationships for solid solutions"""
    
    def __init__(self, model_type: str = 'ideal'):
        self.model_type = model_type
        self.interaction_params = {}
    
    def set_interaction_parameters(self, params: Dict):
        """Set interaction parameters for non-ideal models"""
        self.interaction_params = params
    
    def calculate_activity_coefficient(self, composition: Dict[str, float], 
                                     temperature: float, pressure: float) -> Dict[str, float]:
        """Calculate activity coefficients"""
        if self.model_type == 'ideal':
            return {comp: 1.0 for comp in composition.keys()}
        
        elif self.model_type == 'margules':
            return self._margules_model(composition, temperature)
        
        elif self.model_type == 'vanderlaar':
            return self._vanderlaar_model(composition, temperature, pressure)
        
        elif self.model_type == 'uniquac':
            return self._uniquac_model(composition, temperature, pressure)
        
        elif self.model_type == 'nrtl':
            return self._nrtl_model(composition, temperature, pressure)
        
        elif self.model_type == 'wilson':
            return self._wilson_model(composition, temperature, pressure)
        
        else:
            raise ValueError(f"Unknown activity model: {self.model_type}")
    
    def _margules_model(self, composition: Dict[str, float], temperature: float) -> Dict[str, float]:
        """Margules activity model"""
        gamma = {}
        components = list(composition.keys())
        
        for i, comp_i in enumerate(components):
            ln_gamma = 0
            x_i = composition[comp_i]
            
            for j, comp_j in enumerate(components):
                if i != j:
                    x_j = composition[comp_j]
                    w_ij = self.interaction_params.get(f"{comp_i}_{comp_j}", 0)
                    ln_gamma += w_ij * x_j**2
            
            gamma[comp_i] = np.exp(ln_gamma)
        
        return gamma
    
    def _vanderlaar_model(self, composition: Dict[str, float], 
                         temperature: float, pressure: float) -> Dict[str, float]:
        """Van der Laar activity model with temperature dependence"""
        gamma = {}
        components = list(composition.keys())
        
        for i, comp_i in enumerate(components):
            x_i = composition[comp_i]
            ln_gamma = 0
            
            for j, comp_j in enumerate(components):
                if i != j:
                    x_j = composition[comp_j]
                    # Temperature-dependent interaction parameter
                    a_ij = self.interaction_params.get(f"{comp_i}_{comp_j}", 0)
                    b_ij = self.interaction_params.get(f"{comp_i}_{comp_j}_T", 0)
                    w_ij = a_ij + b_ij * temperature
                    
                    if x_j > 0:
                        ln_gamma += w_ij * x_j**2 / (8.314 * temperature)
            
            gamma[comp_i] = np.exp(ln_gamma)
        
        return gamma
    
    def _uniquac_model(self, composition: Dict[str, float], 
                      temperature: float, pressure: float) -> Dict[str, float]:
        """UNIQUAC activity model for liquid solutions"""
        gamma = {}
        components = list(composition.keys())
        n_comp = len(components)
        
        # Get molecular parameters
        r = {comp: self.interaction_params.get(f"{comp}_r", 1.0) for comp in components}
        q = {comp: self.interaction_params.get(f"{comp}_q", 1.0) for comp in components}
        
        # Calculate average segment fraction and area fraction
        sum_xr = sum(composition[comp] * r[comp] for comp in components)
        sum_xq = sum(composition[comp] * q[comp] for comp in components)
        
        phi = {comp: composition[comp] * r[comp] / sum_xr for comp in components}
        theta = {comp: composition[comp] * q[comp] / sum_xq for comp in components}
        
        # Calculate tau parameters
        tau = {}
        for i in components:
            for j in components:
                if i != j:
                    u_ij = self.interaction_params.get(f"{i}_{j}_u", 0)
                    tau[f"{i}_{j}"] = np.exp(-u_ij / (8.314 * temperature))
                else:
                    tau[f"{i}_{j}"] = 1.0
        
        for comp in components:
            x_i = composition[comp]
            phi_i = phi[comp]
            theta_i = theta[comp]
            r_i = r[comp]
            q_i = q[comp]
            
            # Combinatorial contribution
            ln_gamma_c = np.log(phi_i/x_i) + 5*q_i*np.log(theta_i/phi_i) + \
                        (r_i - phi_i/x_i) - 5*q_i*(r_i - phi_i/x_i)
            
            # Residual contribution
            sum_theta_tau = sum(theta[comp_j] * tau[f"{comp_j}_{comp}"]
                               for comp_j in components)
            
            sum_term = 0
            for comp_j in components:
                theta_j = theta[comp_j]
                tau_ji = tau[f"{comp_j}_{comp}"]
                
                sum_theta_tau_k = sum(theta[comp_k] * tau[f"{comp_k}_{comp_j}"]
                                     for comp_k in components)
                
                sum_term += theta_j * tau_ji / sum_theta_tau_k
            
            ln_gamma_r = q_i * (1 - np.log(sum_theta_tau) - sum_term)
            
            gamma[comp] = np.exp(ln_gamma_c + ln_gamma_r)
        
        return gamma
    
    def _nrtl_model(self, composition: Dict[str, float], 
                   temperature: float, pressure: float) -> Dict[str, float]:
        """NRTL (Non-Random Two-Liquid) activity model"""
        gamma = {}
        components = list(composition.keys())
        
        # Calculate tau and G parameters
        tau = {}
        G = {}
        
        for i in components:
            for j in components:
                if i != j:
                    # Binary interaction parameters
                    a_ij = self.interaction_params.get(f"{i}_{j}_a", 0)
                    b_ij = self.interaction_params.get(f"{i}_{j}_b", 0)
                    alpha_ij = self.interaction_params.get(f"{i}_{j}_alpha", 0.3)
                    
                    tau[f"{i}_{j}"] = a_ij + b_ij / temperature
                    G[f"{i}_{j}"] = np.exp(-alpha_ij * tau[f"{i}_{j}"])
                else:
                    tau[f"{i}_{j}"] = 0.0
                    G[f"{i}_{j}"] = 1.0
        
        for comp_i in components:
            x_i = composition[comp_i]
            
            # Calculate denominator terms
            sum_xG_ji = sum(composition[comp_j] * G[f"{comp_j}_{comp_i}"]
                           for comp_j in components)
            
            # Calculate first sum term
            sum1 = sum(composition[comp_j] * tau[f"{comp_j}_{comp_i}"] * 
                      G[f"{comp_j}_{comp_i}"] for comp_j in components) / sum_xG_ji
            
            # Calculate second sum term
            sum2 = 0
            for comp_j in components:
                x_j = composition[comp_j]
                sum_xG_kj = sum(composition[comp_k] * G[f"{comp_k}_{comp_j}"]
                               for comp_k in components)
                
                term = (G[f"{comp_i}_{comp_j}"] / sum_xG_kj) * \
                       (tau[f"{comp_i}_{comp_j}"] - 
                        sum(composition[comp_k] * tau[f"{comp_k}_{comp_j}"] * 
                           G[f"{comp_k}_{comp_j}"] for comp_k in components) / sum_xG_kj)
                
                sum2 += x_j * term
            
            ln_gamma = sum1 + sum2
            gamma[comp_i] = np.exp(ln_gamma)
        
        return gamma
    
    def _wilson_model(self, composition: Dict[str, float], 
                     temperature: float, pressure: float) -> Dict[str, float]:
        """Wilson activity model for liquid solutions"""
        gamma = {}
        components = list(composition.keys())
        
        # Calculate Lambda parameters
        Lambda = {}
        for i in components:
            for j in components:
                if i != j:
                    lambda_ij = self.interaction_params.get(f"{i}_{j}_lambda", 0)
                    v_i = self.interaction_params.get(f"{i}_v", 1.0)
                    v_j = self.interaction_params.get(f"{j}_v", 1.0)
                    
                    Lambda[f"{i}_{j}"] = (v_j / v_i) * np.exp(-lambda_ij / (8.314 * temperature))
                else:
                    Lambda[f"{i}_{j}"] = 1.0
        
        for comp_i in components:
            x_i = composition[comp_i]
            
            # Calculate denominator terms
            sum_xLambda_ji = sum(composition[comp_j] * Lambda[f"{comp_j}_{comp_i}"]
                                for comp_j in components)
            
            # First term
            term1 = -np.log(sum_xLambda_ji)
            
            # Second term
            term2 = 0
            for comp_j in components:
                x_j = composition[comp_j]
                sum_xLambda_kj = sum(composition[comp_k] * Lambda[f"{comp_k}_{comp_j}"]
                                    for comp_k in components)
                
                term2 += x_j * Lambda[f"{comp_i}_{comp_j}"] / sum_xLambda_kj
            
            term2 = 1 - term2
            
            ln_gamma = term1 + term2
            gamma[comp_i] = np.exp(ln_gamma)
        
        return gamma

class EquationOfState:
    """Advanced equation of state models for fluid phases"""
    
    def __init__(self, model_type: str = 'redlich_kwong'):
        self.model_type = model_type
        self.critical_properties = {}
        self.interaction_params = {}
    
    def set_critical_properties(self, component: str, tc: float, pc: float, omega: float):
        """Set critical properties for component"""
        self.critical_properties[component] = {
            'Tc': tc,  # Critical temperature (K)
            'Pc': pc,  # Critical pressure (bar)
            'omega': omega  # Acentric factor
        }
    
    def set_binary_interaction(self, comp1: str, comp2: str, kij: float):
        """Set binary interaction parameter"""
        self.interaction_params[f"{comp1}_{comp2}"] = kij
        self.interaction_params[f"{comp2}_{comp1}"] = kij
    
    def calculate_fugacity_coefficient(self, composition: Dict[str, float], 
                                     temperature: float, pressure: float) -> Dict[str, float]:
        """Calculate fugacity coefficients using specified EOS"""
        
        if self.model_type == 'ideal_gas':
            return {comp: 1.0 for comp in composition.keys()}
        
        elif self.model_type == 'redlich_kwong':
            return self._redlich_kwong_fugacity(composition, temperature, pressure)
        
        elif self.model_type == 'soave_redlich_kwong':
            return self._srk_fugacity(composition, temperature, pressure)
        
        elif self.model_type == 'peng_robinson':
            return self._peng_robinson_fugacity(composition, temperature, pressure)
        
        elif self.model_type == 'benedict_webb_rubin':
            return self._bwr_fugacity(composition, temperature, pressure)
        
        else:
            raise ValueError(f"Unknown EOS model: {self.model_type}")
    
    def _redlich_kwong_fugacity(self, composition: Dict[str, float], 
                               temperature: float, pressure: float) -> Dict[str, float]:
        """Redlich-Kwong equation of state"""
        R = 0.08314  # L⋅bar/(mol⋅K)
        
        # Calculate mixture parameters
        a_mix, b_mix = self._rk_mixing_rules(composition, temperature)
        
        # Calculate compressibility factor
        Z = self._solve_cubic_eos(pressure, temperature, a_mix, b_mix, eos_type='RK')
        
        # Calculate fugacity coefficients
        phi = {}
        for component in composition.keys():
            if component not in self.critical_properties:
                phi[component] = 1.0
                continue
            
            props = self.critical_properties[component]
            Tc, Pc = props['Tc'], props['Pc']
            
            # Pure component parameters
            a_i = 0.42748 * (R * Tc)**2 / Pc * temperature**(-0.5)
            b_i = 0.08664 * R * Tc / Pc
            
            # Mixing rule derivatives
            da_dx = 2 * sum(composition[j] * self._calculate_aij(component, j, temperature) 
                           for j in composition.keys() if j in self.critical_properties)
            
            # Fugacity coefficient calculation
            term1 = (b_i / b_mix) * (Z - 1) - np.log(Z - b_mix * pressure / (R * temperature))
            term2 = -(a_mix / (R * temperature * b_mix)) * \
                   ((da_dx / a_mix) - (b_i / b_mix)) * \
                   np.log(1 + b_mix * pressure / (R * temperature * Z))
            
            ln_phi = term1 + term2
            phi[component] = np.exp(ln_phi)
        
        return phi
    
    def _srk_fugacity(self, composition: Dict[str, float], 
                     temperature: float, pressure: float) -> Dict[str, float]:
        """Soave-Redlich-Kwong equation of state"""
        R = 0.08314
        
        # Calculate mixture parameters with Soave correction
        a_mix, b_mix = self._srk_mixing_rules(composition, temperature)
        
        # Solve cubic equation
        Z = self._solve_cubic_eos(pressure, temperature, a_mix, b_mix, eos_type='SRK')
        
        phi = {}
        for component in composition.keys():
            if component not in self.critical_properties:
                phi[component] = 1.0
                continue
            
            props = self.critical_properties[component]
            Tc, Pc, omega = props['Tc'], props['Pc'], props['omega']
            
            # Soave alpha function
            m = 0.480 + 1.574 * omega - 0.176 * omega**2
            alpha = (1 + m * (1 - np.sqrt(temperature / Tc)))**2
            
            a_i = 0.42748 * (R * Tc)**2 / Pc * alpha
            b_i = 0.08664 * R * Tc / Pc
            
            # Calculate fugacity coefficient (similar to RK but with alpha correction)
            da_dx = 2 * sum(composition[j] * self._calculate_aij_srk(component, j, temperature) 
                           for j in composition.keys() if j in self.critical_properties)
            
            term1 = (b_i / b_mix) * (Z - 1) - np.log(Z - b_mix * pressure / (R * temperature))
            term2 = -(a_mix / (R * temperature * b_mix)) * \
                   ((da_dx / a_mix) - (b_i / b_mix)) * \
                   np.log(1 + b_mix * pressure / (R * temperature * Z))
            
            ln_phi = term1 + term2
            phi[component] = np.exp(ln_phi)
        
        return phi
    
    def _peng_robinson_fugacity(self, composition: Dict[str, float], 
                               temperature: float, pressure: float) -> Dict[str, float]:
        """Peng-Robinson equation of state"""
        R = 0.08314
        
        # Calculate mixture parameters
        a_mix, b_mix = self._pr_mixing_rules(composition, temperature)
        
        # Solve cubic equation
        Z = self._solve_cubic_eos(pressure, temperature, a_mix, b_mix, eos_type='PR')
        
        phi = {}
        for component in composition.keys():
            if component not in self.critical_properties:
                phi[component] = 1.0
                continue
            
            props = self.critical_properties[component]
            Tc, Pc, omega = props['Tc'], props['Pc'], props['omega']
            
            # PR alpha function
            m = 0.37464 + 1.54226 * omega - 0.26992 * omega**2
            alpha = (1 + m * (1 - np.sqrt(temperature / Tc)))**2
            
            a_i = 0.45724 * (R * Tc)**2 / Pc * alpha
            b_i = 0.07780 * R * Tc / Pc
            
            # PR specific fugacity coefficient calculation
            da_dx = 2 * sum(composition[j] * self._calculate_aij_pr(component, j, temperature) 
                           for j in composition.keys() if j in self.critical_properties)
            
            A = a_mix * pressure / (R * temperature)**2
            B = b_mix * pressure / (R * temperature)
            
            term1 = (b_i / b_mix) * (Z - 1) - np.log(Z - B)
            term2 = -(A / (2.828 * B)) * ((da_dx / a_mix) - (b_i / b_mix)) * \
                   np.log((Z + 2.414 * B) / (Z - 0.414 * B))
            
            ln_phi = term1 + term2
            phi[component] = np.exp(ln_phi)
        
        return phi
    
    def _bwr_fugacity(self, composition: Dict[str, float], 
                     temperature: float, pressure: float) -> Dict[str, float]:
        """Advanced Benedict-Webb-Rubin equation of state with full 8-parameter implementation"""
        
        # Initialize BWR parameter database if not exists
        if not hasattr(self, 'bwr_parameters'):
            self._initialize_bwr_database()
        
        phi = {}
        R = 8.314  # J/(mol·K)
        
        # Calculate mixture BWR parameters using mixing rules
        bwr_mix = self._calculate_bwr_mixing_parameters(composition, temperature)
        
        # Solve BWR equation for mixture
        molar_volume = self._solve_bwr_volume(bwr_mix, temperature, pressure)
        rho = 1.0 / molar_volume  # Molar density (mol/L)
        
        if molar_volume <= 0:
            # Fallback to ideal gas if solution fails
            return {comp: 1.0 for comp in composition.keys()}
        
        # Calculate mixture compressibility factor
        Z_mix = pressure * molar_volume / (R * temperature)
        
        for component in composition.keys():
            if component not in self.critical_properties:
                phi[component] = 1.0
                continue
            
            # Get pure component BWR parameters
            if component not in self.bwr_parameters:
                phi[component] = 1.0
                continue
                
            bwr_pure = self.bwr_parameters[component]
            
            # Calculate fugacity coefficient using BWR virial expansion
            ln_phi = self._calculate_bwr_fugacity_coefficient(
                component, composition, bwr_pure, bwr_mix, 
                temperature, pressure, rho, Z_mix)
            
            phi[component] = np.exp(ln_phi)
        
        return phi
    
