    def _analyze_thermodynamic_consistency_critical_properties(self, Tc: float, Pc: float,
                                                             Vc: float, omega: float, component: str) -> Dict:
        """Analyze thermodynamic consistency of critical properties"""
        try:
            consistency_analysis = {
                'critical_compressibility_consistency': {},
                'corresponding_states_consistency': {},
                'virial_coefficient_consistency': {},
                'phase_equilibrium_consistency': {},
                'transport_property_consistency': {}
            }
            
            R = 8.314472  # J/(mol·K)
            
            # Critical compressibility factor analysis
            Zc = Pc * Vc / (R * Tc)
            zc_analysis = self._analyze_critical_compressibility_consistency(Zc, omega, component)
            consistency_analysis['critical_compressibility_consistency'] = zc_analysis
            
            # Corresponding states principle consistency
            corresponding_states = self._analyze_corresponding_states_consistency(
                Tc, Pc, Vc, omega, component
            )
            consistency_analysis['corresponding_states_consistency'] = corresponding_states
            
            # Second virial coefficient consistency
            virial_consistency = self._analyze_virial_coefficient_consistency(
                Tc, Pc, Vc, omega, component
            )
            consistency_analysis['virial_coefficient_consistency'] = virial_consistency
            
            # Phase equilibrium consistency
            phase_equilibrium = self._analyze_phase_equilibrium_consistency(
                Tc, Pc, Vc, omega, component
            )
            consistency_analysis['phase_equilibrium_consistency'] = phase_equilibrium
            
            return consistency_analysis
            
        except Exception as e:
            print(f"Error in thermodynamic consistency analysis: {e}")
            return {'critical_compressibility_consistency': {}}
    
