    def calculate_gibbs_energy(self, phase: str, temperature: float, 
                              pressure: float, composition: Optional[Dict] = None) -> float:
        """Calculate Gibbs free energy of formation"""
        if phase not in self.database:
            raise ValueError(f"Phase {phase} not in database")
        
        data = self.database[phase]
        
        # Standard state Gibbs energy
        delta_g_298 = data.delta_h_298 - 298.15 * data.s_298 / 1000
        
        # Temperature correction
        t_term = self._integrate_heat_capacity(data.cp_coeffs, 298.15, temperature)
        s_term = self._integrate_entropy(data.cp_coeffs, 298.15, temperature)
        
        delta_g_t = delta_g_298 + t_term - temperature * s_term / 1000
        
        # Pressure correction
        delta_v = data.v_298 * (1 - data.alpha * (temperature - 298.15) + 
                               data.beta * (pressure - 1))
        p_term = delta_v * (pressure - 1) / 1000  # Convert to kJ/mol
        
        delta_g_tp = delta_g_t + p_term
        
        # Activity correction for solid solutions
        if composition:
            activity_term = 0
            for component, mole_frac in composition.items():
                if mole_frac > 0:
                    activity_term += mole_frac * np.log(mole_frac)
            
            delta_g_tp += 8.314 * temperature * activity_term / 1000
        
        return delta_g_tp
    
    def _integrate_heat_capacity(self, cp_coeffs: List[float], 
                                t1: float, t2: float) -> float:
        """Integrate heat capacity from T1 to T2"""
        a, b, c, d = cp_coeffs
        
        integral = (a * (t2 - t1) + 
                   b * (t2**2 - t1**2) / 2 + 
                   c * (1/t2 - 1/t1) +
                   d * (t2**3 - t1**3) / 3)
        
        return integral / 1000  # Convert to kJ/mol
    
    def _integrate_entropy(self, cp_coeffs: List[float], 
                          t1: float, t2: float) -> float:
        """Integrate Cp/T from T1 to T2"""
        a, b, c, d = cp_coeffs
        
        integral = (a * np.log(t2/t1) + 
                   b * (t2 - t1) + 
                   c * (1/t2**2 - 1/t1**2) / 2 +
                   d * (t2**2 - t1**2) / 2)
        
        return integral  # J/mol/K
    
    def minimize_gibbs_energy(self, system_composition: Dict[str, float], 
                             temperature: float, pressure: float,
                             phases: List[str]) -> Dict:
        """Advanced Gibbs energy minimization with multiple solution algorithms"""
        
        # Try multiple optimization methods for robustness
        methods = ['SLSQP', 'trust-constr', 'L-BFGS-B']
        best_result = None
        best_energy = float('inf')
        
        for method in methods:
            try:
                result = self._solve_equilibrium_method(
                    system_composition, temperature, pressure, phases, method)
                
                if result['total_gibbs'] < best_energy:
                    best_energy = result['total_gibbs']
                    best_result = result
                    
            except Exception as e:
                warnings.warn(f"Method {method} failed: {e}")
                continue
        
        if best_result is None:
            # Fallback to simple equilibrium
            return self._fallback_equilibrium(system_composition, temperature, pressure, phases)
        
        # Validate solution with activity corrections
        return self._validate_and_correct_equilibrium(best_result, temperature, pressure)
    
    def _solve_equilibrium_method(self, system_composition: Dict[str, float], 
                                 temperature: float, pressure: float,
                                 phases: List[str], method: str) -> Dict:
        """Solve equilibrium using specific optimization method"""
        
        def objective(x):
            """Enhanced objective function with activity corrections"""
            total_g = 0
            idx = 0
            
            for phase in phases:
                if phase in self.database:
                    amount = x[idx]
                    if amount > 1e-12:
                        # Base Gibbs energy
                        g_phase = self.calculate_gibbs_energy(phase, temperature, pressure)
                        
                        # Activity correction for solid solutions
                        if phase in self.activity_models:
                            composition = self._get_phase_composition(phase, amount, x, phases)
                            gamma = self.activity_models[phase].calculate_activity_coefficient(
                                composition, temperature, pressure)
                            
                            # Add mixing entropy and activity terms
                            for comp, mole_frac in composition.items():
                                if mole_frac > 1e-10:
                                    g_phase += 8.314 * temperature * mole_frac * \
                                              (np.log(mole_frac) + np.log(gamma.get(comp, 1.0))) / 1000
                        
                        total_g += amount * g_phase
                    idx += 1
            
            # Add penalty for negative amounts
            penalty = sum(max(0, -xi)**2 * 1e6 for xi in x)
            return total_g + penalty
        
        # Enhanced mass balance constraints
        def mass_balance(x, element):
            """Enhanced mass balance with solid solution handling"""
            total = 0
            idx = 0
            
            for phase in phases:
                if phase in self.database:
                    amount = x[idx]
                    element_count = self._get_element_count(phase, element)
                    
                    # Handle solid solutions
                    if phase in self.activity_models and amount > 1e-12:
                        composition = self._get_phase_composition(phase, amount, x, phases)
                        # Weight by actual composition
                        for comp, mole_frac in composition.items():
                            comp_element_count = self._get_element_count(comp, element)
                            total += amount * mole_frac * comp_element_count
                    else:
                        total += amount * element_count
                    
                    idx += 1
            
            return total - system_composition.get(element, 0)
        
        # Advanced stoichiometric constraints for solid solutions
        def stoichiometry_constraint(x, phase_idx):
            """Comprehensive stoichiometric consistency constraints for solid solutions"""
            if phase_idx >= len(phases) or phases[phase_idx] not in self.solution_models:
                return 0  # No constraint for pure phases
            
            phase_name = phases[phase_idx]
            solution_model = self.solution_models[phase_name]
            amount = x[phase_idx]
            
            if amount < 1e-12:
                return 0  # Phase not present
            
            # Get phase composition from optimization variables
            composition = self._get_phase_composition(phase_name, amount, x, phases)
            
            # Apply different constraint types based on solid solution model
            if phase_name == 'plagioclase':
                return self._plagioclase_stoichiometry_constraint(composition)
            elif phase_name == 'olivine':
                return self._olivine_stoichiometry_constraint(composition)
            elif phase_name == 'garnet':
                return self._garnet_stoichiometry_constraint(composition)
            elif phase_name == 'pyroxene':
                return self._pyroxene_stoichiometry_constraint(composition)
            elif phase_name == 'spinel':
                return self._spinel_stoichiometry_constraint(composition)
            elif phase_name == 'amphibole':
                return self._amphibole_stoichiometry_constraint(composition)
            else:
                return self._generic_solid_solution_constraint(phase_name, composition)
        
        def crystallographic_site_constraint(x, phase_idx, site_name):
            """Crystallographic site occupancy constraints"""
            if phase_idx >= len(phases) or phases[phase_idx] not in self.solution_models:
                return 0
            
            phase_name = phases[phase_idx]
            amount = x[phase_idx]
            
            if amount < 1e-12:
                return 0
            
            composition = self._get_phase_composition(phase_name, amount, x, phases)
            
            # Site-specific constraints based on crystal structure
            if phase_name == 'plagioclase' and site_name == 'T1':
                return self._tetrahedral_site_constraint(composition, 'T1', ['Si', 'Al'])
            elif phase_name == 'garnet' and site_name == 'X':
                return self._dodecahedral_site_constraint(composition, 'X', ['Ca', 'Fe', 'Mg', 'Mn'])
            elif phase_name == 'garnet' and site_name == 'Y':
                return self._octahedral_site_constraint(composition, 'Y', ['Al', 'Fe3', 'Cr'])
            else:
                return 0
        
        def charge_balance_constraint(x, phase_idx):
            """Charge neutrality constraints for solid solutions"""
            if phase_idx >= len(phases) or phases[phase_idx] not in self.solution_models:
                return 0
            
            phase_name = phases[phase_idx]
            amount = x[phase_idx]
            
            if amount < 1e-12:
                return 0
            
            composition = self._get_phase_composition(phase_name, amount, x, phases)
            
            # Calculate total charge from all cations and anions
            total_charge = 0
            
            # Define oxidation states for common elements
            oxidation_states = {
                'Si': 4, 'Al': 3, 'Fe': 2, 'Mg': 2, 'Ca': 2, 'Na': 1, 'K': 1,
                'Ti': 4, 'Cr': 3, 'Mn': 2, 'Ni': 2, 'O': -2, 'OH': -1, 'F': -1
            }
            
            for component, mole_frac in composition.items():
                if component in self.database:
                    formula = self.database[component].formula
                    charge = self._calculate_formula_charge(formula, oxidation_states)
                    total_charge += mole_frac * charge
            
            return total_charge  # Should be zero for charge neutrality
        
        # Setup optimization
        n_phases = len([p for p in phases if p in self.database])
        x0 = self._get_initial_guess(system_composition, phases, temperature, pressure)
        
        # Constraints
        constraints = []
        elements = ['Si', 'Al', 'Fe', 'Mg', 'Ca', 'Na', 'K', 'O']
        
        for element in elements:
            if element in system_composition and system_composition[element] > 0:
                constraints.append({
                    'type': 'eq',
                    'fun': lambda x, elem=element: mass_balance(x, elem)
                })
        
        # Add stoichiometry constraints for solid solutions
        for i, phase in enumerate(phases):
            if phase in self.database and phase in self.activity_models:
                constraints.append({
                    'type': 'eq',
                    'fun': lambda x, idx=i: stoichiometry_constraint(x, idx)
                })
        
        # Bounds
        bounds = [(1e-15, None) for _ in range(n_phases)]
        
        # Solve with specified method
        if method == 'trust-constr':
            from scipy.optimize import NonlinearConstraint
            nl_constraints = [NonlinearConstraint(
                lambda x, elem=elem: mass_balance(x, elem), 
                -1e-10, 1e-10) for elem in elements 
                if elem in system_composition and system_composition[elem] > 0]
            
            result = minimize(objective, x0, method=method, 
                            bounds=bounds, constraints=nl_constraints)
        else:
            result = minimize(objective, x0, method=method, 
                            bounds=bounds, constraints=constraints)
        
        if not result.success:
            raise RuntimeError(f"Optimization failed with {method}: {result.message}")
        
        return self._format_equilibrium_result(result.x, phases, temperature, pressure)
    
    def _get_initial_guess(self, system_composition: Dict[str, float], 
                          phases: List[str], temperature: float, pressure: float) -> np.ndarray:
        """Generate intelligent initial guess based on system composition"""
        n_phases = len([p for p in phases if p in self.database])
        
        # Start with equal distribution
        x0 = np.ones(n_phases) * 0.1
        
        # Adjust based on thermodynamic favorability
        idx = 0
        for phase in phases:
            if phase in self.database:
                # Calculate relative stability
                g_phase = self.calculate_gibbs_energy(phase, temperature, pressure)
                
                # Lower Gibbs energy = higher initial guess
                stability_factor = np.exp(-g_phase / (8.314 * temperature / 1000))
                x0[idx] *= stability_factor
                
                idx += 1
        
        # Normalize to conserve mass approximately
        total_mass = sum(system_composition.values())
        x0 = x0 * total_mass / sum(x0) if sum(x0) > 0 else x0
        
        return x0
    
    def _get_phase_composition(self, phase: str, amount: float, 
                             all_amounts: np.ndarray, phases: List[str]) -> Dict[str, float]:
        """Advanced solid solution composition calculation with crystallographic site modeling"""
        
        # Initialize advanced solid solution database if not exists
        if not hasattr(self, 'solid_solution_database'):
            self._initialize_solid_solution_database()
        
        if phase not in self.activity_models:
            return {phase: 1.0}
        
        if amount < 1e-12:
            return {}
        
        # Get current thermodynamic conditions
        temperature = getattr(self, '_current_temperature', 1273.15)  # Default 1000°C
        pressure = getattr(self, '_current_pressure', 1e5)  # Default 1 bar
        
        # Calculate advanced solid solution compositions based on crystal structure
        if phase == 'plagioclase':
            return self._calculate_plagioclase_composition(amount, all_amounts, phases, temperature, pressure)
        elif phase == 'olivine':
            return self._calculate_olivine_composition(amount, all_amounts, phases, temperature, pressure)
        elif phase == 'garnet':
            return self._calculate_garnet_composition(amount, all_amounts, phases, temperature, pressure)
        elif phase == 'pyroxene':
            return self._calculate_pyroxene_composition(amount, all_amounts, phases, temperature, pressure)
        elif phase == 'spinel':
            return self._calculate_spinel_composition(amount, all_amounts, phases, temperature, pressure)
        elif phase == 'amphibole':
            return self._calculate_amphibole_composition(amount, all_amounts, phases, temperature, pressure)
        elif phase == 'biotite':
            return self._calculate_biotite_composition(amount, all_amounts, phases, temperature, pressure)
        else:
            # Advanced multicomponent solid solution calculation
            return self._calculate_general_solid_solution_composition(
                phase, amount, all_amounts, phases, temperature, pressure)
    
