    def _calculate_plagioclase_composition(self, amount: float, all_amounts: np.ndarray, 
                                         phases: List[str], temperature: float, pressure: float) -> Dict[str, float]:
        """Calculate plagioclase solid solution composition with Al-Si ordering"""
        
        # Get bulk composition indices
        elements = ['SiO2', 'Al2O3', 'CaO', 'Na2O', 'K2O']
        bulk_composition = self._get_bulk_element_composition(all_amounts, phases, elements)
        
        # Calculate feldspar normative composition
        total_alkali = bulk_composition.get('Na2O', 0) + bulk_composition.get('K2O', 0)
        total_feldspar_components = total_alkali + bulk_composition.get('CaO', 0)
        
        if total_feldspar_components < 1e-12:
            return {'albite': 1.0}
        
        # Calculate endmember fractions based on thermodynamic equilibrium
        X_ab = bulk_composition.get('Na2O', 0) / total_feldspar_components
        X_an = bulk_composition.get('CaO', 0) / total_feldspar_components
        X_or = bulk_composition.get('K2O', 0) / total_feldspar_components
        
        # Apply activity coefficient corrections for non-ideal mixing
        gamma_ab = self._calculate_plagioclase_activity_coefficient('albite', X_ab, X_an, X_or, temperature, pressure)
        gamma_an = self._calculate_plagioclase_activity_coefficient('anorthite', X_ab, X_an, X_or, temperature, pressure)
        gamma_or = self._calculate_plagioclase_activity_coefficient('orthoclase', X_ab, X_an, X_or, temperature, pressure)
        
        # Apply Al-Si ordering corrections
        ordering_factor = self._calculate_al_si_ordering_factor(X_an, temperature)
        
        # Normalize to ensure mass balance
        total = X_ab * gamma_ab + X_an * gamma_an * ordering_factor + X_or * gamma_or
        if total > 1e-12:
            X_ab_corrected = (X_ab * gamma_ab) / total
            X_an_corrected = (X_an * gamma_an * ordering_factor) / total
            X_or_corrected = (X_or * gamma_or) / total
        else:
            X_ab_corrected, X_an_corrected, X_or_corrected = 1.0, 0.0, 0.0
        
        composition = {}
        if X_ab_corrected > 1e-6:
            composition['albite'] = X_ab_corrected
        if X_an_corrected > 1e-6:
            composition['anorthite'] = X_an_corrected
        if X_or_corrected > 1e-6:
            composition['orthoclase'] = X_or_corrected
            
        return composition if composition else {'albite': 1.0}
    
    def _calculate_olivine_composition(self, amount: float, all_amounts: np.ndarray, 
                                     phases: List[str], temperature: float, pressure: float) -> Dict[str, float]:
        """Calculate olivine solid solution composition with site ordering"""
        
        # Get relevant bulk composition
        elements = ['MgO', 'FeO', 'MnO', 'NiO']
        bulk_composition = self._get_bulk_element_composition(all_amounts, phases, elements)
        
        total_olivine_components = (bulk_composition.get('MgO', 0) + 
                                  bulk_composition.get('FeO', 0) + 
                                  bulk_composition.get('MnO', 0) + 
                                  bulk_composition.get('NiO', 0))
        
        if total_olivine_components < 1e-12:
            return {'forsterite': 1.0}
        
        # Calculate cation fractions
        X_Mg = bulk_composition.get('MgO', 0) / total_olivine_components
        X_Fe = bulk_composition.get('FeO', 0) / total_olivine_components
        X_Mn = bulk_composition.get('MnO', 0) / total_olivine_components
        X_Ni = bulk_composition.get('NiO', 0) / total_olivine_components
        
        # Apply site ordering for M1 and M2 sites
        site_distribution = self._calculate_olivine_site_distribution(X_Mg, X_Fe, X_Mn, X_Ni, temperature, pressure)
        
        # Calculate activity coefficients for non-ideal mixing
        gamma_fo = self._calculate_olivine_activity_coefficient('forsterite', X_Mg, X_Fe, X_Mn, temperature)
        gamma_fa = self._calculate_olivine_activity_coefficient('fayalite', X_Mg, X_Fe, X_Mn, temperature)
        gamma_teph = self._calculate_olivine_activity_coefficient('tephroite', X_Mg, X_Fe, X_Mn, temperature)
        
        # Apply corrections
        total = X_Mg * gamma_fo + X_Fe * gamma_fa + X_Mn * gamma_teph
        if total > 1e-12:
            X_fo = (X_Mg * gamma_fo) / total
            X_fa = (X_Fe * gamma_fa) / total
            X_teph = (X_Mn * gamma_teph) / total
        else:
            X_fo, X_fa, X_teph = 1.0, 0.0, 0.0
        
        composition = {}
        if X_fo > 1e-6:
            composition['forsterite'] = X_fo
        if X_fa > 1e-6:
            composition['fayalite'] = X_fa
        if X_teph > 1e-6:
            composition['tephroite'] = X_teph
            
        return composition if composition else {'forsterite': 1.0}
    
    def _calculate_garnet_composition(self, amount: float, all_amounts: np.ndarray, 
                                    phases: List[str], temperature: float, pressure: float) -> Dict[str, float]:
        """Calculate garnet solid solution composition with multisite mixing"""
        
        elements = ['CaO', 'MgO', 'FeO', 'MnO', 'Al2O3', 'SiO2']
        bulk_composition = self._get_bulk_element_composition(all_amounts, phases, elements)
        
        # Calculate X-site cation fractions
        total_X_site = (bulk_composition.get('CaO', 0) + bulk_composition.get('MgO', 0) + 
                       bulk_composition.get('FeO', 0) + bulk_composition.get('MnO', 0))
        
        if total_X_site < 1e-12:
            return {'pyrope': 1.0}
        
        X_Ca = bulk_composition.get('CaO', 0) / total_X_site
        X_Mg = bulk_composition.get('MgO', 0) / total_X_site
        X_Fe = bulk_composition.get('FeO', 0) / total_X_site
        X_Mn = bulk_composition.get('MnO', 0) / total_X_site
        
        # Apply multicomponent interaction parameters
        activity_coeffs = self._calculate_garnet_activity_coefficients(X_Ca, X_Mg, X_Fe, X_Mn, temperature, pressure)
        
        # Normalize with activity coefficients
        total = sum(X * gamma for X, gamma in zip([X_Ca, X_Mg, X_Fe, X_Mn], activity_coeffs.values()))
        
        composition = {}
        if total > 1e-12:
            if X_Ca * activity_coeffs['grossular'] / total > 1e-6:
                composition['grossular'] = X_Ca * activity_coeffs['grossular'] / total
            if X_Mg * activity_coeffs['pyrope'] / total > 1e-6:
                composition['pyrope'] = X_Mg * activity_coeffs['pyrope'] / total
            if X_Fe * activity_coeffs['almandine'] / total > 1e-6:
                composition['almandine'] = X_Fe * activity_coeffs['almandine'] / total
            if X_Mn * activity_coeffs['spessartine'] / total > 1e-6:
                composition['spessartine'] = X_Mn * activity_coeffs['spessartine'] / total
        
        return composition if composition else {'pyrope': 1.0}
    
    def _calculate_pyroxene_composition(self, amount: float, all_amounts: np.ndarray, 
                                      phases: List[str], temperature: float, pressure: float) -> Dict[str, float]:
        """Advanced pyroxene solid solution with comprehensive crystallographic site modeling"""
        
        # Initialize pyroxene crystallographic database if needed
        if not hasattr(self, 'pyroxene_site_database'):
            self._initialize_pyroxene_crystallographic_database()
        
        # Extended element list for complete pyroxene chemistry
        elements = ['CaO', 'MgO', 'FeO', 'Al2O3', 'SiO2', 'Na2O', 'Cr2O3', 'TiO2', 'MnO']
        bulk_composition = self._get_bulk_element_composition(all_amounts, phases, elements)
        
        # Advanced pyroxene quadrilateral with crystallographic constraints
        M_site_cations = self._calculate_pyroxene_M_site_totals(bulk_composition)
        T_site_cations = self._calculate_pyroxene_T_site_totals(bulk_composition)
        
        if M_site_cations['total'] < 1e-12:
            return {'enstatite': 1.0}
        
        # Calculate detailed site occupancies for M1 and M2 sites
        site_occupancies = self._calculate_pyroxene_site_occupancies(
            bulk_composition, temperature, pressure)
        
        # Determine pyroxene structural types based on crystallography
        structural_analysis = self._analyze_pyroxene_crystal_structure(
            site_occupancies, temperature, pressure)
        
        # Calculate clinopyroxene vs orthopyroxene stability
        cpx_opx_equilibrium = self._calculate_cpx_opx_equilibrium(
            site_occupancies, temperature, pressure)
        
        # Apply advanced miscibility modeling with thermodynamic constraints
        miscibility_relations = self._calculate_advanced_pyroxene_miscibility(
            site_occupancies, structural_analysis, temperature, pressure)
        
        # Calculate component activities with site-specific interactions
        component_activities = self._calculate_pyroxene_component_activities(
            site_occupancies, miscibility_relations, temperature, pressure)
        
        # Apply Ca-Tschermak substitution corrections
        tschermak_corrections = self._calculate_ca_tschermak_substitution(
            site_occupancies, temperature, pressure)
        
        # Determine final pyroxene composition with all corrections
        final_composition = self._assemble_pyroxene_composition(
            component_activities, tschermak_corrections, cpx_opx_equilibrium,
            structural_analysis, temperature, pressure)
        
        return final_composition if final_composition else {'enstatite': 1.0}
    
