    def _calculate_pyroxene_M_site_totals(self, bulk_composition: Dict[str, float]) -> Dict[str, float]:
        """Advanced pyroxene M-site cation calculation with comprehensive crystal chemistry and site preference modeling"""
        
        try:
            # Initialize comprehensive analysis framework
            M_site_analysis = {
                'cation_contents': {},
                'site_preferences': {},
                'coordination_analysis': {},
                'crystal_field_effects': {},
                'temperature_pressure_dependencies': {},
                'ordering_parameters': {},
                'structural_distortions': {},
                'thermodynamic_properties': {}
            }
            
            # Advanced oxide to cation conversion with precision molecular weights
            precise_molecular_weights = {
                'CaO': 56.0774, 'MgO': 40.3044, 'FeO': 71.8444, 'Fe2O3': 159.6882,
                'Al2O3': 101.9613, 'Na2O': 61.9789, 'K2O': 94.1960, 'MnO': 70.9374,
                'TiO2': 79.8658, 'Cr2O3': 151.9904, 'NiO': 74.6928, 'CoO': 74.9326,
                'ZnO': 81.4094, 'V2O3': 149.8812, 'SiO2': 60.0843
            }
            
            # Account for iron oxidation state distribution
            iron_speciation = self._determine_iron_oxidation_states(bulk_composition)
            
            # Calculate raw cation contents with full speciation
            raw_cations = {}
            
            # Major cations
            raw_cations['Ca'] = bulk_composition.get('CaO', 0) / precise_molecular_weights['CaO']
            raw_cations['Mg'] = bulk_composition.get('MgO', 0) / precise_molecular_weights['MgO']
            raw_cations['Fe2+'] = iron_speciation['Fe2+_mol']
            raw_cations['Fe3+'] = iron_speciation['Fe3+_mol']
            raw_cations['Al'] = bulk_composition.get('Al2O3', 0) / precise_molecular_weights['Al2O3'] * 2
            raw_cations['Na'] = bulk_composition.get('Na2O', 0) / precise_molecular_weights['Na2O'] * 2
            raw_cations['K'] = bulk_composition.get('K2O', 0) / precise_molecular_weights['K2O'] * 2
            raw_cations['Mn'] = bulk_composition.get('MnO', 0) / precise_molecular_weights['MnO']
            raw_cations['Ti'] = bulk_composition.get('TiO2', 0) / precise_molecular_weights['TiO2']
            raw_cations['Cr'] = bulk_composition.get('Cr2O3', 0) / precise_molecular_weights['Cr2O3'] * 2
            
            # Minor and trace cations
            raw_cations['Ni'] = bulk_composition.get('NiO', 0) / precise_molecular_weights['NiO']
            raw_cations['Co'] = bulk_composition.get('CoO', 0) / precise_molecular_weights['CoO']
            raw_cations['Zn'] = bulk_composition.get('ZnO', 0) / precise_molecular_weights['ZnO']
            raw_cations['V'] = bulk_composition.get('V2O3', 0) / precise_molecular_weights['V2O3'] * 2
            
            # Advanced site preference modeling using crystal field theory
            site_preferences = self._calculate_advanced_site_preferences(raw_cations)
            M_site_analysis['site_preferences'] = site_preferences
            
            # M1 and M2 site distribution based on ionic radii and crystal field stabilization
            M1_M2_distribution = self._distribute_cations_M1_M2_sites(raw_cations, site_preferences)
            
            # Calculate actual M-site occupancies with ordering effects
            M_site_cations = self._calculate_M_site_occupancies_with_ordering(
                raw_cations, M1_M2_distribution, bulk_composition
            )
            
            M_site_analysis['cation_contents'] = M_site_cations
            
            # Crystal field effects and Jahn-Teller distortions
            crystal_field_analysis = self._analyze_crystal_field_effects(M_site_cations)
            M_site_analysis['crystal_field_effects'] = crystal_field_analysis
            
            # Coordination environment analysis
            coordination_analysis = self._analyze_M_site_coordination(M_site_cations, bulk_composition)
            M_site_analysis['coordination_analysis'] = coordination_analysis
            
            # Structural distortion parameters
            distortion_analysis = self._calculate_structural_distortions(M_site_cations)
            M_site_analysis['structural_distortions'] = distortion_analysis
            
            # Temperature and pressure dependencies
            TP_dependencies = self._calculate_M_site_TP_dependencies(M_site_cations, bulk_composition)
            M_site_analysis['temperature_pressure_dependencies'] = TP_dependencies
            
            # Cation ordering parameters
            ordering_parameters = self._calculate_cation_ordering_parameters(M_site_cations)
            M_site_analysis['ordering_parameters'] = ordering_parameters
            
            # Thermodynamic properties of M-site configuration
            thermodynamic_props = self._calculate_M_site_thermodynamics(M_site_cations, crystal_field_analysis)
            M_site_analysis['thermodynamic_properties'] = thermodynamic_props
            
            # Return simplified interface for compatibility while storing full analysis
            self._pyroxene_M_site_detailed_analysis = M_site_analysis
            
            return M_site_cations
            
        except Exception as e:
            # Robust fallback to basic calculation
            return self._calculate_M_site_basic_fallback(bulk_composition)
    
    def _calculate_pyroxene_T_site_totals(self, bulk_composition: Dict[str, float]) -> Dict[str, float]:
        """Advanced pyroxene T-site cation calculation with tetrahedral site modeling and Al-Si ordering"""
        
        try:
            # Initialize comprehensive T-site analysis
            T_site_analysis = {
                'cation_contents': {},
                'tetrahedral_geometry': {},
                'Al_Si_ordering': {},
                'tetrahedral_tilting': {},
                'bond_length_variations': {},
                'charge_balance_effects': {},
                'framework_topology': {},
                'substitution_mechanisms': {}
            }
            
            # Precise molecular weights
            precise_molecular_weights = {
                'SiO2': 60.0843, 'Al2O3': 101.9613, 'TiO2': 79.8658, 
                'Fe2O3': 159.6882, 'Cr2O3': 151.9904, 'P2O5': 141.9445
            }
            
            # Calculate total tetrahedral cations available
            total_Si = bulk_composition.get('SiO2', 0) / precise_molecular_weights['SiO2']
            total_Al = bulk_composition.get('Al2O3', 0) / precise_molecular_weights['Al2O3'] * 2
            total_Ti = bulk_composition.get('TiO2', 0) / precise_molecular_weights['TiO2']
            total_Fe3 = bulk_composition.get('Fe2O3', 0) / precise_molecular_weights['Fe2O3'] * 2
            total_Cr = bulk_composition.get('Cr2O3', 0) / precise_molecular_weights['Cr2O3'] * 2
            total_P = bulk_composition.get('P2O5', 0) / precise_molecular_weights['P2O5'] * 2
            
            # Advanced tetrahedral site preference modeling
            tetrahedral_preferences = self._calculate_tetrahedral_site_preferences(
                total_Si, total_Al, total_Ti, total_Fe3, total_Cr, total_P
            )
            
            # Al-Si ordering based on Al/Si ratio and temperature effects
            Al_Si_ordering = self._model_Al_Si_tetrahedral_ordering(
                total_Si, total_Al, bulk_composition
            )
            T_site_analysis['Al_Si_ordering'] = Al_Si_ordering
            
            # T-site occupancy calculation with charge balance constraints
            T_site_occupancy = self._calculate_T_site_occupancy_constrained(
                total_Si, total_Al, total_Ti, total_Fe3, total_Cr, total_P,
                tetrahedral_preferences, bulk_composition
            )
            
            # Account for tetrahedral coordination constraints
            coordinated_T_sites = self._apply_tetrahedral_coordination_constraints(
                T_site_occupancy, bulk_composition
            )
            
            T_site_analysis['cation_contents'] = coordinated_T_sites
            
            # Tetrahedral geometry analysis
            geometry_analysis = self._analyze_tetrahedral_geometry(coordinated_T_sites)
            T_site_analysis['tetrahedral_geometry'] = geometry_analysis
            
            # Framework topology effects
            topology_analysis = self._analyze_framework_topology(coordinated_T_sites, bulk_composition)
            T_site_analysis['framework_topology'] = topology_analysis
            
            # Tetrahedral tilting and distortion
            tilting_analysis = self._calculate_tetrahedral_tilting(coordinated_T_sites)
            T_site_analysis['tetrahedral_tilting'] = tilting_analysis
            
            # Bond length variation analysis
            bond_analysis = self._analyze_T_site_bond_lengths(coordinated_T_sites)
            T_site_analysis['bond_length_variations'] = bond_analysis
            
            # Charge balance effects on T-site
            charge_balance = self._analyze_T_site_charge_balance(coordinated_T_sites, bulk_composition)
            T_site_analysis['charge_balance_effects'] = charge_balance
            
            # Substitution mechanism analysis
            substitution_analysis = self._analyze_T_site_substitutions(coordinated_T_sites)
            T_site_analysis['substitution_mechanisms'] = substitution_analysis
            
            # Store detailed analysis
            self._pyroxene_T_site_detailed_analysis = T_site_analysis
            
            return coordinated_T_sites
            
        except Exception as e:
            # Robust fallback
            return self._calculate_T_site_basic_fallback(bulk_composition)
    
    def _determine_iron_oxidation_states(self, bulk_composition: Dict[str, float]) -> Dict[str, float]:
        """Determine Fe2+/Fe3+ distribution using thermodynamic constraints"""
        try:
            total_Fe_as_FeO = bulk_composition.get('FeO', 0)
            total_Fe_as_Fe2O3 = bulk_composition.get('Fe2O3', 0)
            
            # Convert to molar basis
            Fe2_mol = total_Fe_as_FeO / 71.8444  # FeO molecular weight
            Fe3_mol = total_Fe_as_Fe2O3 / 159.6882 * 2  # Fe2O3 -> 2 Fe3+
            
            # Apply oxygen fugacity constraints for realistic Fe2+/Fe3+ ratios
            total_Fe_mol = Fe2_mol + Fe3_mol
            
            if total_Fe_mol > 0:
                # Estimate reasonable Fe3+/(Fe2++Fe3+) ratio for pyroxene
                # Typically 0.05-0.15 in most natural pyroxenes
                estimated_Fe3_fraction = min(0.15, Fe3_mol / total_Fe_mol)
                
                # Redistribute if needed
                redistributed_Fe3 = total_Fe_mol * estimated_Fe3_fraction
                redistributed_Fe2 = total_Fe_mol - redistributed_Fe3
                
                return {
                    'Fe2+_mol': redistributed_Fe2,
                    'Fe3+_mol': redistributed_Fe3,
                    'total_Fe_mol': total_Fe_mol,
                    'Fe3_fraction': estimated_Fe3_fraction
                }
            else:
                return {'Fe2+_mol': 0.0, 'Fe3+_mol': 0.0, 'total_Fe_mol': 0.0, 'Fe3_fraction': 0.0}
                
        except:
            return {'Fe2+_mol': 0.0, 'Fe3+_mol': 0.0, 'total_Fe_mol': 0.0, 'Fe3_fraction': 0.0}
    
    def _calculate_advanced_site_preferences(self, raw_cations: Dict[str, float]) -> Dict[str, Dict[str, float]]:
        """Calculate advanced site preferences using crystal field theory and ionic radii"""
        try:
            # Crystal field stabilization energies (CFSE) in pyroxene M-sites
            # Values in kJ/mol for octahedral coordination
            CFSE_M1 = {  # M1 site (more regular octahedron)
                'Mg': 0.0, 'Ca': 0.0, 'Fe2+': -35.1, 'Fe3+': 0.0, 'Al': 0.0,
                'Mn': -35.1, 'Ti': -154.8, 'Cr': -125.5, 'Ni': -70.3, 'Co': -35.1,
                'V': -125.5, 'Zn': 0.0
            }
            
            CFSE_M2 = {  # M2 site (more distorted, can be 6-8 coordinated)
                'Ca': 0.0, 'Na': 0.0, 'K': 0.0, 'Mg': 0.0, 'Fe2+': -20.1, 
                'Fe3+': 0.0, 'Al': 0.0, 'Mn': -20.1, 'Ti': -80.2, 'Cr': -60.2
            }
            
            # Ionic radii preferences (Shannon radii in Angstroms)
            ionic_radii = {
                'Ca': 1.00, 'Mg': 0.72, 'Fe2+': 0.78, 'Fe3+': 0.645, 'Al': 0.535,
                'Na': 1.02, 'K': 1.38, 'Mn': 0.83, 'Ti': 0.605, 'Cr': 0.615,
                'Ni': 0.69, 'Co': 0.745, 'V': 0.640, 'Zn': 0.74
            }
            
            site_preferences = {}
            
            for cation, amount in raw_cations.items():
                if amount > 0 and cation in ionic_radii:
                    # Calculate site preference based on size, CFSE, and coordination preferences
                    M1_preference = 0.5  # Base preference
                    M2_preference = 0.5
                    
                    # Size preferences
                    optimal_M1_radius = 0.70  # Angstroms
                    optimal_M2_radius = 0.95
                    
                    M1_size_penalty = abs(ionic_radii[cation] - optimal_M1_radius) * 10
                    M2_size_penalty = abs(ionic_radii[cation] - optimal_M2_radius) * 10
                    
                    # CFSE contributions
                    M1_CFSE = CFSE_M1.get(cation, 0.0) / 50.0  # Normalize
                    M2_CFSE = CFSE_M2.get(cation, 0.0) / 50.0
                    
                    # Calculate total preferences
                    M1_score = M1_preference - M1_size_penalty + M1_CFSE
                    M2_score = M2_preference - M2_size_penalty + M2_CFSE
                    
                    # Normalize to probabilities
                    total_score = M1_score + M2_score + 1e-10
                    M1_prob = max(0.0, M1_score / total_score)
                    M2_prob = max(0.0, M2_score / total_score)
                    
                    # Special cases for specific cations
                    if cation == 'Ca':
                        M2_prob = 0.95  # Ca strongly prefers M2
                        M1_prob = 0.05
                    elif cation == 'Na':
                        M2_prob = 0.98  # Na almost exclusively in M2
                        M1_prob = 0.02
                    elif cation in ['Mg', 'Fe2+', 'Mn']:
                        # These prefer M1 but can go in M2
                        M1_prob = max(0.7, M1_prob)
                        M2_prob = 1.0 - M1_prob
                    
                    site_preferences[cation] = {
                        'M1_preference': M1_prob,
                        'M2_preference': M2_prob,
                        'M1_CFSE': M1_CFSE,
                        'M2_CFSE': M2_CFSE,
                        'ionic_radius': ionic_radii[cation]
                    }
            
            return site_preferences
            
        except Exception as e:
            # Return default equal preferences
            return {cation: {'M1_preference': 0.5, 'M2_preference': 0.5} 
                   for cation in raw_cations.keys() if raw_cations[cation] > 0}
    
    def _distribute_cations_M1_M2_sites(self, raw_cations: Dict[str, float], 
                                       site_preferences: Dict[str, Dict[str, float]]) -> Dict[str, Dict[str, float]]:
        """Distribute cations between M1 and M2 sites using advanced algorithms"""
        try:
            # Pyroxene stoichiometry: ideal is 2 cations per formula unit
            # M1 + M2 = 2.0 (in ideal case)
            
            total_cations = sum(raw_cations.values())
            target_total = 2.0  # Target stoichiometry
            
            # Scale cations to stoichiometric proportions
            if total_cations > 0:
                scale_factor = target_total / total_cations
            else:
                scale_factor = 1.0
            
            # Initialize site distributions
            M1_distribution = {}
            M2_distribution = {}
            
            # First pass: distribute based on preferences
            for cation, amount in raw_cations.items():
                if amount > 0 and cation in site_preferences:
                    scaled_amount = amount * scale_factor
                    
                    M1_pref = site_preferences[cation]['M1_preference']
                    M2_pref = site_preferences[cation]['M2_preference']
                    
                    M1_distribution[cation] = scaled_amount * M1_pref
                    M2_distribution[cation] = scaled_amount * M2_pref
            
            # Check site totals and apply stoichiometric constraints
            M1_total = sum(M1_distribution.values())
            M2_total = sum(M2_distribution.values())
            
            # Ideal pyroxene has M1 = M2 = 1.0
            # Adjust if totals deviate significantly
            target_M1 = 1.0
            target_M2 = 1.0
            
            # Redistribution if needed
            if abs(M1_total - target_M1) > 0.1 or abs(M2_total - target_M2) > 0.1:
                M1_distribution, M2_distribution = self._rebalance_M_site_distribution(
                    M1_distribution, M2_distribution, target_M1, target_M2, site_preferences
                )
            
            return {
                'M1_site': M1_distribution,
                'M2_site': M2_distribution,
                'M1_total': sum(M1_distribution.values()),
                'M2_total': sum(M2_distribution.values()),
                'total_M_sites': sum(M1_distribution.values()) + sum(M2_distribution.values())
            }
            
        except Exception as e:
            # Fallback equal distribution
            equal_dist = {cation: amount / 2.0 for cation, amount in raw_cations.items()}
            return {'M1_site': equal_dist, 'M2_site': equal_dist, 'M1_total': 1.0, 'M2_total': 1.0}
    
    def _calculate_M_site_occupancies_with_ordering(self, raw_cations: Dict[str, float],
                                                   M1_M2_distribution: Dict[str, Dict[str, float]],
                                                   bulk_composition: Dict[str, float]) -> Dict[str, float]:
        """Calculate final M-site occupancies with cation ordering effects"""
        try:
            # Extract distributions
            M1_dist = M1_M2_distribution['M1_site']
            M2_dist = M1_M2_distribution['M2_site']
            
            # Apply temperature-dependent ordering
            ordered_distribution = self._apply_cation_ordering_temperature_effects(
                M1_dist, M2_dist, bulk_composition
            )
            
            # Combine M1 and M2 for total M-site content
            total_M_site = {}
            
            all_cations = set(list(M1_dist.keys()) + list(M2_dist.keys()))
            
            for cation in all_cations:
                M1_amount = ordered_distribution['M1_ordered'].get(cation, 0.0)
                M2_amount = ordered_distribution['M2_ordered'].get(cation, 0.0)
                total_M_site[cation] = M1_amount + M2_amount
            
            # Add detailed site information
            total_M_site['M1_total'] = sum(ordered_distribution['M1_ordered'].values())
            total_M_site['M2_total'] = sum(ordered_distribution['M2_ordered'].values())
            total_M_site['total'] = sum(total_M_site[k] for k in total_M_site.keys() 
                                      if k not in ['M1_total', 'M2_total', 'total'])
            
            # Store detailed distribution for later use
            total_M_site['_detailed_distribution'] = ordered_distribution
            
            return total_M_site
            
        except Exception as e:
            # Simple fallback
            return {cation: amount for cation, amount in raw_cations.items()}
    
    def _calculate_tetrahedral_site_preferences(self, Si: float, Al: float, Ti: float, 
                                              Fe3: float, Cr: float, P: float) -> Dict[str, float]:
        """Calculate tetrahedral site preferences for T-site cations"""
        try:
            # Tetrahedral site preferences based on size and electronegativity
            preferences = {
                'Si': 1.0,    # Perfect tetrahedral cation
                'Al': 0.8,    # Good tetrahedral cation
                'Ti': 0.3,    # Prefers octahedral but can be tetrahedral
                'Fe3+': 0.4,  # Can substitute in tetrahedral sites
                'Cr': 0.2,    # Rarely tetrahedral
                'P': 0.9      # Good tetrahedral cation
            }
            
            # Apply size constraints - ideal tetrahedral radius ~0.4 Å
            tetrahedral_radii = {
                'Si': 0.26, 'Al': 0.39, 'Ti': 0.42, 'Fe3+': 0.49, 'Cr': 0.55, 'P': 0.17
            }
            
            optimal_radius = 0.35
            
            for cation, radius in tetrahedral_radii.items():
                size_factor = 1.0 - abs(radius - optimal_radius) / optimal_radius
                preferences[cation] *= max(0.1, size_factor)
            
            return preferences
            
        except:
            return {'Si': 1.0, 'Al': 0.8, 'Ti': 0.3, 'Fe3+': 0.4, 'Cr': 0.2, 'P': 0.9}
    
    def _model_Al_Si_tetrahedral_ordering(self, Si: float, Al: float, 
                                        bulk_composition: Dict[str, float]) -> Dict[str, float]:
        """Model Al-Si ordering in tetrahedral sites"""
        try:
            if Si + Al == 0:
                return {'Al_avoidance': 0.0, 'ordering_parameter': 0.0, 'Si_Al_ratio': 0.0}
            
            Si_Al_ratio = Si / (Si + Al) if (Si + Al) > 0 else 0.0
            
            # Al-avoidance principle: Al prefers not to be adjacent to other Al
            Al_fraction = Al / (Si + Al) if (Si + Al) > 0 else 0.0
            
            # Loewenstein's rule: Al-O-Al bonds are avoided
            if Al_fraction > 0.5:
                # High Al content leads to some Al-O-Al bonds
                Al_avoidance = 1.0 - 2.0 * (Al_fraction - 0.5)
            else:
                # Low Al content, perfect avoidance possible
                Al_avoidance = 1.0
            
            # Ordering parameter
            if Si_Al_ratio > 1.0:
                ordering_parameter = min(1.0, Si_Al_ratio / 3.0)  # Well-ordered
            else:
                ordering_parameter = Si_Al_ratio  # Partially disordered
            
            return {
                'Al_avoidance': Al_avoidance,
                'ordering_parameter': ordering_parameter,
                'Si_Al_ratio': Si_Al_ratio,
                'Al_fraction': Al_fraction
            }
            
        except:
            return {'Al_avoidance': 1.0, 'ordering_parameter': 1.0, 'Si_Al_ratio': 2.0}
    
    def _calculate_T_site_occupancy_constrained(self, Si: float, Al: float, Ti: float,
                                              Fe3: float, Cr: float, P: float,
                                              preferences: Dict[str, float],
                                              bulk_composition: Dict[str, float]) -> Dict[str, float]:
        """Calculate T-site occupancy with charge balance and stoichiometric constraints"""
        try:
            # Target: 2 tetrahedral sites per formula unit
            target_T_total = 2.0
            
            # Calculate weighted preferences
            total_cations = Si + Al + Ti + Fe3 + Cr + P
            
            if total_cations == 0:
                return {'Si': 0.0, 'Al': 0.0, 'Ti': 0.0, 'Fe3+': 0.0, 'Cr': 0.0, 'P': 0.0, 'total': 0.0}
            
            # Apply preferences and normalize to target total
            scale_factor = target_T_total / total_cations
            
            T_site_occupancy = {
                'Si': Si * scale_factor * preferences['Si'],
                'Al': Al * scale_factor * preferences['Al'],
                'Ti': Ti * scale_factor * preferences['Ti'],
                'Fe3+': Fe3 * scale_factor * preferences['Fe3+'],
                'Cr': Cr * scale_factor * preferences['Cr'],
                'P': P * scale_factor * preferences['P']
            }
            
            # Ensure Si dominance (Si should be ≥ 1.5 in most pyroxenes)
            T_total = sum(T_site_occupancy.values())
            if T_site_occupancy['Si'] < 1.5 and T_total > 0:
                # Boost Si content
                Si_deficit = 1.5 - T_site_occupancy['Si']
                available_Si = Si * scale_factor - T_site_occupancy['Si']
                
                if available_Si > 0:
                    Si_boost = min(Si_deficit, available_Si)
                    T_site_occupancy['Si'] += Si_boost
                    
                    # Reduce other cations proportionally
                    reduction_factor = Si_boost / sum(T_site_occupancy[k] for k in T_site_occupancy.keys() if k != 'Si')
                    for cation in ['Al', 'Ti', 'Fe3+', 'Cr', 'P']:
                        T_site_occupancy[cation] *= (1.0 - reduction_factor)
            
            T_site_occupancy['total'] = sum(T_site_occupancy.values())
            
            return T_site_occupancy
            
        except Exception as e:
            # Fallback
            return {'Si': 2.0, 'Al': 0.0, 'Ti': 0.0, 'Fe3+': 0.0, 'Cr': 0.0, 'P': 0.0, 'total': 2.0}
    
    # Helper methods for fallback calculations
    def _calculate_M_site_basic_fallback(self, bulk_composition: Dict[str, float]) -> Dict[str, float]:
        """Basic fallback M-site calculation"""
        try:
            M_site_cations = {
                'Ca': bulk_composition.get('CaO', 0) / 56.08,
                'Mg': bulk_composition.get('MgO', 0) / 40.30,
                'Fe': (bulk_composition.get('FeO', 0) / 71.84 + 
                      bulk_composition.get('Fe2O3', 0) / 159.69 * 2),
                'Al': bulk_composition.get('Al2O3', 0) / 101.96 * 2,
                'Na': bulk_composition.get('Na2O', 0) / 61.98 * 2,
                'Mn': bulk_composition.get('MnO', 0) / 70.94,
                'Ti': bulk_composition.get('TiO2', 0) / 79.87,
                'Cr': bulk_composition.get('Cr2O3', 0) / 152.0 * 2
            }
            M_site_cations['total'] = sum(M_site_cations.values())
            return M_site_cations
        except:
            return {'total': 0.0}
    
    def _calculate_T_site_basic_fallback(self, bulk_composition: Dict[str, float]) -> Dict[str, float]:
        """Basic fallback T-site calculation"""
        try:
            T_site_cations = {
                'Si': bulk_composition.get('SiO2', 0) / 60.08,
                'Al': bulk_composition.get('Al2O3', 0) / 101.96 * 2 * 0.2,  # Some Al in T-site
                'Ti': bulk_composition.get('TiO2', 0) / 79.87 * 0.1
            }
            T_site_cations['total'] = sum(T_site_cations.values())
            return T_site_cations
        except:
            return {'Si': 2.0, 'total': 2.0}
    
