    def _get_advanced_phase_stoichiometry(self, phase: str, temperature: float, pressure: float) -> Dict[str, float]:
        """Get advanced phase stoichiometry with solid solution and P-T effects"""
        
        if phase not in self.advanced_stoichiometry_database:
            # Fallback to simple stoichiometry for unknown phases
            return self._get_simple_phase_stoichiometry(phase)
        
        phase_data = self.advanced_stoichiometry_database[phase]
        
        # Start with endmember composition
        composition = phase_data['endmember_stoichiometry'].copy()
        
        # Apply solid solution effects if present
        if 'solid_solution_components' in phase_data and phase_data['solid_solution_components']:
            composition = self._calculate_solid_solution_composition(phase, phase_data, temperature, pressure)
        
        # Apply pressure-temperature stability corrections
        composition = self._apply_stability_corrections(phase, composition, temperature, pressure)
        
        # Apply crystallographic ordering effects
        if 'ordering_parameters' in phase_data:
            composition = self._apply_ordering_corrections(phase, composition, temperature, pressure)
        
        return composition
    
    def _calculate_solid_solution_composition(self, phase: str, phase_data: dict, temperature: float, pressure: float) -> Dict[str, float]:
        """Calculate composition accounting for solid solution"""
        
        endmember_comp = phase_data['endmember_stoichiometry'].copy()
        ss_components = phase_data['solid_solution_components']
        
        # Calculate mole fractions based on thermodynamic equilibrium
        mole_fractions = self._calculate_endmember_fractions(phase, temperature, pressure)
        
        # Weight compositions by mole fractions
        final_composition = {}
        
        # Start with endmember
        X_endmember = mole_fractions.get('endmember', 0.8)  # Default dominance
        for element, amount in endmember_comp.items():
            final_composition[element] = X_endmember * amount
        
        # Add contributions from solid solution components
        for component, comp_data in ss_components.items():
            X_component = mole_fractions.get(component, 0.0)
            if X_component > 1e-6:
                for element, amount in comp_data.items():
                    if element in final_composition:
                        final_composition[element] += X_component * amount
                    else:
                        final_composition[element] = X_component * amount
        
        return final_composition
    
    def _calculate_endmember_fractions(self, phase: str, temperature: float, pressure: float) -> Dict[str, float]:
        """Calculate endmember mole fractions based on thermodynamic equilibrium"""
        
        R = 8.314  # J/(mol·K)
        
        # Phase-specific solid solution models
        if phase in ['albite', 'anorthite', 'orthoclase']:  # Feldspar solid solution
            return self._calculate_feldspar_endmember_fractions(temperature, pressure)
        elif phase in ['forsterite', 'fayalite']:  # Olivine solid solution
            return self._calculate_olivine_endmember_fractions(temperature, pressure)
        elif phase in ['enstatite', 'diopside']:  # Pyroxene solid solution
            return self._calculate_pyroxene_endmember_fractions(temperature, pressure)
        elif phase in ['grossular', 'pyrope']:  # Garnet solid solution
            return self._calculate_garnet_endmember_fractions(temperature, pressure)
        else:
            # Default behavior - endmember dominated
            return {'endmember': 1.0}
    
    def _calculate_feldspar_endmember_fractions(self, temperature: float, pressure: float) -> Dict[str, float]:
        """Advanced feldspar ternary solid solution with comprehensive solvus modeling"""
        
        # Initialize advanced feldspar thermodynamic database if needed
        if not hasattr(self, 'feldspar_thermodynamic_database'):
            self._initialize_feldspar_thermodynamic_database()
        
        R = 8.314  # J/(mol·K)
        
        # Get current bulk composition for feldspar system constraints
        bulk_alkali_ratio = self._get_bulk_alkali_ratio()
        bulk_Al_Si_ratio = self._get_bulk_Al_Si_ratio()
        
        # Calculate ternary feldspar equilibrium using advanced solvus modeling
        feldspar_fractions = self._solve_feldspar_ternary_equilibrium(temperature, pressure, bulk_alkali_ratio, bulk_Al_Si_ratio)
        
        # Apply Al-Si ordering corrections
        ordered_fractions = self._apply_feldspar_al_si_ordering(feldspar_fractions, temperature, pressure)
        
        # Apply strain energy corrections for coherent solvus
        strain_corrected_fractions = self._apply_feldspar_strain_corrections(ordered_fractions, temperature, pressure)
        
        # Calculate activity coefficients for non-ideal mixing
        activity_corrected_fractions = self._apply_feldspar_activity_corrections(strain_corrected_fractions, temperature, pressure)
        
        return activity_corrected_fractions
    
    def _calculate_olivine_endmember_fractions(self, temperature: float, pressure: float) -> Dict[str, float]:
        """Advanced olivine solid solution with comprehensive Fe-Mg ordering and site modeling"""
        
        # Initialize advanced olivine thermodynamic database if needed
        if not hasattr(self, 'olivine_thermodynamic_database'):
            self._initialize_olivine_thermodynamic_database()
        
        R = 8.314  # J/(mol·K)
        
        # Get bulk Fe/(Fe+Mg) ratio from system composition
        bulk_fe_mg_ratio = self._get_bulk_fe_mg_ratio()
        bulk_mn_content = self._get_bulk_mn_content()
        bulk_ni_content = self._get_bulk_ni_content()
        
        # Calculate olivine equilibrium using advanced site-occupancy modeling
        olivine_fractions = self._solve_olivine_equilibrium(temperature, pressure, bulk_fe_mg_ratio, bulk_mn_content, bulk_ni_content)
        
        # Apply M1-M2 site ordering corrections
        site_ordered_fractions = self._apply_olivine_site_ordering(olivine_fractions, temperature, pressure)
        
        # Apply pressure-induced phase transitions
        pressure_corrected_fractions = self._apply_olivine_pressure_corrections(site_ordered_fractions, temperature, pressure)
        
        # Calculate activity coefficients for non-ideal mixing
        activity_corrected_fractions = self._apply_olivine_activity_corrections(pressure_corrected_fractions, temperature, pressure)
        
        return activity_corrected_fractions
    
    def _calculate_pyroxene_endmember_fractions(self, temperature: float, pressure: float) -> Dict[str, float]:
        """Calculate pyroxene solid solution fractions"""
        
        # Pyroxene quadrilateral relationships
        if temperature > 1473:
            X_en = 0.6  # Enstatite
            X_wo = 0.25  # Wollastonite component
            X_fs = 0.15  # Ferrosilite
        else:
            X_en = 0.7
            X_wo = 0.2
            X_fs = 0.1
        
        return {
            'endmember': X_en,
            'wollastonite': X_wo,
            'ferrosilite': X_fs
        }
    
    def _calculate_garnet_endmember_fractions(self, temperature: float, pressure: float) -> Dict[str, float]:
        """Calculate garnet solid solution fractions"""
        
        # Pressure strongly affects garnet composition
        if pressure > 3e9:  # High pressure favors pyrope
            X_pyr = 0.6
            X_grs = 0.25
            X_alm = 0.15
        elif pressure > 1e9:
            X_pyr = 0.5
            X_grs = 0.3
            X_alm = 0.2
        else:
            X_pyr = 0.4
            X_grs = 0.4
            X_alm = 0.2
        
        return {
            'endmember': X_pyr,
            'grossular': X_grs,
            'almandine': X_alm
        }
    
