    def _get_bulk_alkali_ratio(self) -> float:
        na_content = getattr(self, '_current_na_content', 0.6)
        k_content = getattr(self, '_current_k_content', 0.2)
        total_alkali = na_content + k_content
        return na_content / total_alkali if total_alkali > 1e-10 else 0.75
    
    def _get_bulk_Al_Si_ratio(self) -> float:
        al_content = getattr(self, '_current_al_content', 0.15)
        si_content = getattr(self, '_current_si_content', 0.65)
        total_tetrahedral = al_content + si_content
        return al_content / total_tetrahedral if total_tetrahedral > 1e-10 else 0.19
    
    def _solve_feldspar_ternary_equilibrium(self, temperature: float, pressure: float, 
                                          bulk_alkali_ratio: float, bulk_Al_Si_ratio: float) -> Dict[str, float]:
        if temperature > 1273:
            X_ab_initial = 0.5 + bulk_alkali_ratio * 0.3
            X_an_initial = 0.2 + bulk_Al_Si_ratio * 0.3
        elif temperature > 973:
            X_ab_initial = 0.6 + bulk_alkali_ratio * 0.2
            X_an_initial = 0.15 + bulk_Al_Si_ratio * 0.25
        else:
            X_ab_initial = 0.8 + bulk_alkali_ratio * 0.1
            X_an_initial = 0.1 + bulk_Al_Si_ratio * 0.15
        
        X_or_initial = 1.0 - X_ab_initial - X_an_initial
        X_ab_initial = max(0.05, min(0.9, X_ab_initial))
        X_an_initial = max(0.02, min(0.7, X_an_initial))
        X_or_initial = max(0.02, min(0.8, X_or_initial))
        
        total = X_ab_initial + X_an_initial + X_or_initial
        return {'endmember': X_ab_initial / total, 'anorthite': X_an_initial / total, 'orthoclase': X_or_initial / total}
    
    def _calculate_endmember_chemical_potential(self, endmember: str, temperature: float, pressure: float) -> float:
        endmember_data = self.feldspar_thermodynamic_database['endmembers'][endmember]
        H_T = self._calculate_enthalpy_T(endmember_data, temperature)
        S_T = self._calculate_entropy_T(endmember_data, temperature)
        V_TP = self._calculate_molar_volume_TP(endmember_data, temperature, pressure)
        return H_T - temperature * S_T + pressure * V_TP * 1e-5
    
    def _apply_feldspar_al_si_ordering(self, feldspar_fractions: Dict[str, float], temperature: float, pressure: float) -> Dict[str, float]:
        return feldspar_fractions
    
    def _apply_feldspar_strain_corrections(self, feldspar_fractions: Dict[str, float], temperature: float, pressure: float) -> Dict[str, float]:
        return feldspar_fractions
    
    def _apply_feldspar_activity_corrections(self, feldspar_fractions: Dict[str, float], temperature: float, pressure: float) -> Dict[str, float]:
        return feldspar_fractions
    
    def _initialize_olivine_thermodynamic_database(self):
        """Initialize comprehensive olivine thermodynamic database"""
        
        self.olivine_thermodynamic_database = {
            'endmembers': {
                'forsterite': {
                    'H_f': -2174000, 'S_298': 95.1, 'Cp_coeffs': [233.18, 0.0018, -603800, -0.85],
                    'V_298': 43.79, 'K_298': 129.0, 'K_prime': 4.2, 'alpha_coeffs': [2.78e-5, 0.8e-8]
                },
                'fayalite': {
                    'H_f': -1479400, 'S_298': 150.9, 'Cp_coeffs': [201.18, 0.0138, 426800, -0.73],
                    'V_298': 46.39, 'K_298': 134.0, 'K_prime': 4.9, 'alpha_coeffs': [3.24e-5, 1.2e-8]
                },
                'tephroite': {
                    'H_f': -1732100, 'S_298': 155.9, 'Cp_coeffs': [219.89, 0.0085, -523400, -0.79],
                    'V_298': 47.58, 'K_298': 108.0, 'K_prime': 4.1, 'alpha_coeffs': [3.15e-5, 1.1e-8]
                }
            },
            'binary_interactions': {
                'forsterite_fayalite': {'W_G_symmetric': 8500, 'W_G_asymmetric': 1100},
                'forsterite_tephroite': {'W_G_symmetric': 12800, 'W_G_asymmetric': 2100}
            },
            'site_parameters': {
                'M1_site': {
                    'coordination': 6, 'distortion_index': 0.02,
                    'preferred_cations': {
                        'Mg2+': {'ionic_radius': 0.72, 'site_preference': 0.8},
                        'Fe2+': {'ionic_radius': 0.78, 'site_preference': 0.9},
                        'Mn2+': {'ionic_radius': 0.83, 'site_preference': 0.85}
                    }
                }
            }
        }
    
    def _get_bulk_fe_mg_ratio(self) -> float:
        fe_content = getattr(self, '_current_fe_content', 0.15)
        mg_content = getattr(self, '_current_mg_content', 0.85)
        total_fm = fe_content + mg_content
        return fe_content / total_fm if total_fm > 1e-10 else 0.12
    
    def _get_bulk_mn_content(self) -> float:
        return getattr(self, '_current_mn_content', 0.003)
    
    def _get_bulk_ni_content(self) -> float:
        return getattr(self, '_current_ni_content', 0.002)
    
    def _solve_olivine_equilibrium(self, temperature: float, pressure: float, 
                                 bulk_fe_mg_ratio: float, bulk_mn_content: float, bulk_ni_content: float) -> Dict[str, float]:
        if temperature > 1673:
            X_fo = (1 - bulk_fe_mg_ratio) * 0.8
            X_fa = bulk_fe_mg_ratio * 1.2
        elif temperature > 1273:
            X_fo = (1 - bulk_fe_mg_ratio) * 0.9
            X_fa = bulk_fe_mg_ratio * 1.1
        else:
            X_fo = (1 - bulk_fe_mg_ratio) * 1.1
            X_fa = bulk_fe_mg_ratio * 0.9
        
        X_teph = bulk_mn_content
        total = X_fo + X_fa + X_teph
        
        return {
            'endmember': X_fo / total,
            'fayalite': X_fa / total,
            'tephroite': X_teph / total if X_teph > 1e-6 else 0
        }
    
    def _apply_olivine_site_ordering(self, olivine_fractions: Dict[str, float], temperature: float, pressure: float) -> Dict[str, float]:
        site_ordered_fractions = olivine_fractions.copy()
        
        if temperature < 1273 and 'fayalite' in site_ordered_fractions:
            ordering_factor = 1.0 + (1273 - temperature) / 1273 * 0.1
            site_ordered_fractions['fayalite'] *= ordering_factor
        
        total = sum(site_ordered_fractions.values())
        if total > 0:
            for key in site_ordered_fractions:
                site_ordered_fractions[key] /= total
        
        return site_ordered_fractions
    
    def _apply_olivine_pressure_corrections(self, olivine_fractions: Dict[str, float], temperature: float, pressure: float) -> Dict[str, float]:
        pressure_corrected_fractions = olivine_fractions.copy()
        
        if pressure > 14e9:
            transformation_factor = min((pressure - 14e9) / 4e9, 0.8)
            for component in pressure_corrected_fractions:
                pressure_corrected_fractions[component] *= (1 - transformation_factor)
        
        return pressure_corrected_fractions
    
    def _apply_olivine_activity_corrections(self, olivine_fractions: Dict[str, float], temperature: float, pressure: float) -> Dict[str, float]:
        R = 8.314
        activity_corrected_fractions = olivine_fractions.copy()
        
        X_fo = olivine_fractions.get('endmember', 0)
        X_fa = olivine_fractions.get('fayalite', 0)
        
        if X_fo > 0 and X_fa > 0:
            W_FeMg = 8500
            ln_gamma_fo = W_FeMg * X_fa**2 / (R * temperature)
            ln_gamma_fa = W_FeMg * X_fo**2 / (R * temperature)
            
            gamma_fo = np.exp(ln_gamma_fo)
            gamma_fa = np.exp(ln_gamma_fa)
            
            activity_corrected_fractions['endmember'] *= gamma_fo
            activity_corrected_fractions['fayalite'] *= gamma_fa
        
        total = sum(activity_corrected_fractions.values())
        if total > 0:
            for key in activity_corrected_fractions:
                activity_corrected_fractions[key] /= total
        
        return activity_corrected_fractions
    
    def _apply_stability_corrections(self, phase: str, composition: Dict[str, float], temperature: float, pressure: float) -> Dict[str, float]:
        """Apply pressure-temperature stability corrections"""
        
        if phase not in self.advanced_stoichiometry_database:
            return composition
        
        stability_field = self.advanced_stoichiometry_database[phase]['stability_field']
        
        # Check if outside stability field
        if (temperature < stability_field['T_min'] or temperature > stability_field['T_max'] or
            pressure < stability_field['P_min'] or pressure > stability_field['P_max']):
            
            # Apply metastability corrections
            stability_factor = self._calculate_stability_factor(phase, temperature, pressure)
            
            # Reduce all components proportionally
            corrected_composition = {}
            for element, amount in composition.items():
                corrected_composition[element] = amount * stability_factor
            
            return corrected_composition
        
        return composition
    
    def _calculate_stability_factor(self, phase: str, temperature: float, pressure: float) -> float:
        """Calculate stability factor for metastable conditions"""
        
        stability_field = self.advanced_stoichiometry_database[phase]['stability_field']
        
        # Calculate how far outside stability field
        T_deviation = max(0, temperature - stability_field['T_max'], stability_field['T_min'] - temperature)
        P_deviation = max(0, pressure - stability_field['P_max'], stability_field['P_min'] - pressure)
        
        # Exponential decay of stability
        T_factor = np.exp(-T_deviation / 200)  # 200K characteristic temperature
        P_factor = np.exp(-P_deviation / 1e8)  # 100 MPa characteristic pressure
        
        return min(T_factor * P_factor, 1.0)
    
    def _apply_ordering_corrections(self, phase: str, composition: Dict[str, float], temperature: float, pressure: float) -> Dict[str, float]:
        """Apply crystallographic ordering corrections"""
        
        phase_data = self.advanced_stoichiometry_database[phase]
        
        if 'ordering_parameters' not in phase_data:
            return composition
        
        ordering_params = phase_data['ordering_parameters']
        corrected_composition = composition.copy()
        
        # Al-Si ordering (feldspar, pyroxene)
        if 'Al_Si_ordering' in ordering_params:
            order_param = ordering_params['Al_Si_ordering']
            T_c = order_param['T_c']
            Q = order_param['Q']  # Ordering energy
            
            # Calculate order parameter
            if temperature < T_c:
                S = np.tanh(Q / (8.314 * temperature))  # Simplified order parameter
                
                # Adjust Al2O3 and SiO2 based on ordering
                if 'Al2O3' in corrected_composition and 'SiO2' in corrected_composition:
                    Al_excess = corrected_composition['Al2O3'] * S * 0.1
                    corrected_composition['Al2O3'] += Al_excess
                    corrected_composition['SiO2'] -= Al_excess * 0.5  # Stoichiometric constraint
        
        # Ca-Na ordering (feldspar)
        if 'Na_Ca_ordering' in ordering_params:
            order_param = ordering_params['Na_Ca_ordering']
            
            if order_param.get('miscibility_gap', False):
                T_c_solvus = order_param['T_c_solvus']
                
                if temperature < T_c_solvus:
                    # Enhance phase separation
                    if 'Na2O' in corrected_composition and 'CaO' in corrected_composition:
                        separation_factor = (T_c_solvus - temperature) / T_c_solvus * 0.2
                        Na_enhancement = corrected_composition['Na2O'] * separation_factor
                        Ca_reduction = corrected_composition['CaO'] * separation_factor
                        
                        corrected_composition['Na2O'] += Na_enhancement
                        corrected_composition['CaO'] -= Ca_reduction
        
        return corrected_composition
    
    def _apply_thermodynamic_corrections(self, phase: str, composition: Dict[str, float], temperature: float, pressure: float) -> Dict[str, float]:
        """Apply thermodynamic activity and fugacity corrections"""
        
        corrected_composition = composition.copy()
        
        # Apply activity coefficient corrections
        if hasattr(self, 'activity_models') and phase in self.activity_models:
            for element in corrected_composition:
                if element in self.activity_models[phase]:
                    activity_coeff = self._calculate_element_activity_coefficient(phase, element, temperature, pressure)
                    corrected_composition[element] *= activity_coeff
        
        # Apply volatile corrections (H2O, CO2)
        if 'H2O' in corrected_composition:
            # Water fugacity effects
            f_H2O = self._calculate_water_fugacity(temperature, pressure)
            water_correction = f_H2O / 1e5  # Normalize to 1 bar
            corrected_composition['H2O'] *= water_correction
        
        if 'CO2' in corrected_composition:
            # CO2 fugacity effects
            f_CO2 = self._calculate_co2_fugacity(temperature, pressure)
            co2_correction = f_CO2 / 1e5
            corrected_composition['CO2'] *= co2_correction
        
        return corrected_composition
    
    def _calculate_element_activity_coefficient(self, phase: str, element: str, temperature: float, pressure: float) -> float:
        """Calculate element-specific activity coefficient using advanced UNIQUAC model"""
        
        R = 8.314  # J/(mol·K)
        
        # Get molecular interaction parameters for this element
        params = self._get_uniquac_parameters(phase, element, temperature)
        
        # UNIQUAC model implementation
        # Combinatorial contribution
        gamma_comb = self._uniquac_combinatorial_term(phase, element, temperature, params)
        
        # Residual contribution
        gamma_res = self._uniquac_residual_term(phase, element, temperature, params)
        
        # Pressure correction using Poynting factor
        gamma_pressure = self._pressure_correction_factor(phase, element, temperature, pressure)
        
        # Total activity coefficient
        gamma_total = gamma_comb * gamma_res * gamma_pressure
        
        return max(gamma_total, 0.01)  # Prevent negative values
    
    def _get_uniquac_parameters(self, phase: str, element: str, temperature: float) -> Dict[str, float]:
        """Get UNIQUAC molecular interaction parameters"""
        
        # Default parameters database - in practice would be loaded from external database
        default_params = {
            'r': 1.0,  # Van der Waals volume parameter
            'q': 1.0,  # Van der Waals surface area parameter
            'tau_12': 1.0,  # Binary interaction parameter
            'tau_21': 1.0,  # Binary interaction parameter
            'alpha_12': 0.3,  # Non-randomness parameter
            'coordination_number': 10.0
        }
        
        # Element-specific parameters
        element_params = {
            'Si': {'r': 0.92, 'q': 0.84, 'tau_12': 0.89, 'tau_21': 1.13},
            'Al': {'r': 0.71, 'q': 0.64, 'tau_12': 0.95, 'tau_21': 1.05},
            'Fe': {'r': 0.54, 'q': 0.48, 'tau_12': 1.15, 'tau_21': 0.87},
            'Mg': {'r': 0.65, 'q': 0.58, 'tau_12': 0.92, 'tau_21': 1.09},
            'Ca': {'r': 0.82, 'q': 0.74, 'tau_12': 0.88, 'tau_21': 1.14},
            'Na': {'r': 0.77, 'q': 0.69, 'tau_12': 0.91, 'tau_21': 1.10},
            'K': {'r': 1.25, 'q': 1.12, 'tau_12': 0.85, 'tau_21': 1.18}
        }
        
        params = default_params.copy()
        if element in element_params:
            params.update(element_params[element])
        
        # Temperature dependence of interaction parameters
        params['tau_12'] *= np.exp(-1000 / (R * temperature))
        params['tau_21'] *= np.exp(-800 / (R * temperature))
        
        return params
    
    def _uniquac_combinatorial_term(self, phase: str, element: str, temperature: float, params: Dict[str, float]) -> float:
        """Calculate UNIQUAC combinatorial contribution"""
        
        r_i = params['r']
        q_i = params['q']
        z = params['coordination_number']
        
        # For simplicity, assume binary system with solvent
        x_i = 0.1  # Mole fraction of element (would be calculated from composition)
        x_j = 0.9  # Mole fraction of solvent
        r_j = 1.0  # Solvent r parameter
        q_j = 1.0  # Solvent q parameter
        
        # Volume and surface fractions
        phi_i = (x_i * r_i) / (x_i * r_i + x_j * r_j)
        theta_i = (x_i * q_i) / (x_i * q_i + x_j * q_j)
        
        # Combinatorial term
        ln_gamma_comb = np.log(phi_i / x_i) + (z/2) * q_i * np.log(theta_i / phi_i) + \
                        (z/2) * q_i * (1 - theta_i / phi_i)
        
        return np.exp(ln_gamma_comb)
    
    def _uniquac_residual_term(self, phase: str, element: str, temperature: float, params: Dict[str, float]) -> float:
        """Calculate UNIQUAC residual contribution"""
        
        q_i = params['q']
        tau_12 = params['tau_12']
        tau_21 = params['tau_21']
        
        # For binary system
        x_i = 0.1
        x_j = 0.9
        q_j = 1.0
        
        theta_i = (x_i * q_i) / (x_i * q_i + x_j * q_j)
        theta_j = 1.0 - theta_i
        
        # Residual term
        ln_gamma_res = q_i * (1 - np.log(theta_i + theta_j * tau_21) - \
                             (theta_i * tau_12) / (theta_i * tau_12 + theta_j) - \
                             (theta_j * tau_21) / (theta_i + theta_j * tau_21))
        
        return np.exp(ln_gamma_res)
    
    def _pressure_correction_factor(self, phase: str, element: str, temperature: float, pressure: float) -> float:
        """Calculate pressure correction using Poynting factor"""
        
        P_ref = 1e5  # Reference pressure (1 bar)
        R = 8.314
        
        # Partial molar volume (approximate)
        element_volumes = {
            'Si': 12.0e-6,  # m³/mol
            'Al': 10.0e-6,
            'Fe': 7.1e-6,
            'Mg': 14.0e-6,
            'Ca': 16.6e-6,
            'Na': 23.7e-6,
            'K': 45.4e-6
        }
        
        V_partial = element_volumes.get(element, 15.0e-6)
        
        # Poynting correction
        ln_gamma_P = V_partial * (pressure - P_ref) / (R * temperature)
        
        return np.exp(ln_gamma_P)
    
    def _calculate_water_fugacity(self, temperature: float, pressure: float) -> float:
        """Calculate water fugacity using Peng-Robinson equation of state"""
        
        if pressure < 1e4:  # Very low pressure - ideal gas
            return pressure
        
        # Water critical properties
        Tc = 647.096  # Critical temperature (K)
        Pc = 2.2064e7  # Critical pressure (Pa)
        omega = 0.3449  # Acentric factor
        R = 8.314472  # Gas constant
        
        # Reduced properties
        Tr = temperature / Tc
        
        # Peng-Robinson parameters
        kappa = 0.37464 + 1.54226 * omega - 0.26992 * omega**2
        alpha = (1 + kappa * (1 - np.sqrt(Tr)))**2
        
        a = 0.45724 * (R * Tc)**2 / Pc * alpha
        b = 0.07780 * R * Tc / Pc
        
        # Solve cubic equation for compressibility factor
        A = a * pressure / (R * temperature)**2
        B = b * pressure / (R * temperature)
        
        # Cubic equation coefficients: Z³ - (1-B)Z² + (A-3B²-2B)Z - (AB-B²-B³) = 0
        coeffs = [
            1,
            -(1 - B),
            A - 3*B**2 - 2*B,
            -(A*B - B**2 - B**3)
        ]
        
        # Find real roots
        roots = np.roots(coeffs)
        real_roots = []
        for root in roots:
            if np.isreal(root) and np.real(root) > 0:
                real_roots.append(np.real(root))
        
        if not real_roots:
            Z = 1.0  # Fallback to ideal gas
        else:
            # Choose appropriate root (vapor phase for gas)
            Z = max(real_roots) if len(real_roots) > 1 else real_roots[0]
        
        # Calculate fugacity coefficient
        if Z > B:  # Valid solution
            ln_phi = Z - 1 - np.log(Z - B) - (A / (2*np.sqrt(2)*B)) * \
                     np.log((Z + (1 + np.sqrt(2))*B) / (Z + (1 - np.sqrt(2))*B))
            phi = np.exp(ln_phi)
        else:
            phi = 1.0  # Fallback
        
        fugacity = pressure * phi
        
        # Additional corrections for extreme conditions
        if temperature > 1273:  # High temperature corrections
            correction = 1 + 0.01 * (temperature - 1273) / 1273
            fugacity *= correction
        
        if pressure > 1e8:  # Very high pressure - apply virial corrections
            virial_correction = self._calculate_virial_correction_h2o(temperature, pressure)
            fugacity *= virial_correction
        
        return max(fugacity, pressure * 0.1)  # Ensure reasonable bounds
    
    def _calculate_co2_fugacity(self, temperature: float, pressure: float) -> float:
        """Calculate CO2 fugacity using Redlich-Kwong-Soave equation of state"""
        
        if pressure < 1e4:  # Very low pressure - ideal gas
            return pressure
        
        # CO2 critical properties
        Tc = 304.1282  # Critical temperature (K)
        Pc = 7.3773e6  # Critical pressure (Pa)
        omega = 0.2236  # Acentric factor
        R = 8.314472
        
        # Reduced temperature
        Tr = temperature / Tc
        
        # RKS parameters with temperature dependence
        m = 0.480 + 1.574 * omega - 0.176 * omega**2
        alpha = (1 + m * (1 - np.sqrt(Tr)))**2
        
        # Temperature-dependent parameters
        a_T = 0.42748 * (R * Tc)**2 / Pc * alpha
        b = 0.08664 * R * Tc / Pc
        
        # Dimensionless parameters
        A = a_T * pressure / (R * temperature)**2
        B = b * pressure / (R * temperature)
        
        # Solve RKS cubic equation: Z³ - Z² + (A - B - B²)Z - AB = 0
        coeffs = [1, -1, A - B - B**2, -A*B]
        roots = np.roots(coeffs)
        
        # Select physical root
        real_roots = []
        for root in roots:
            if np.isreal(root) and np.real(root) > 0:
                real_roots.append(np.real(root))
        
        if not real_roots:
            Z = 1.0
        else:
            # For vapor phase, choose largest root
            Z = max(real_roots)
        
        # Calculate fugacity coefficient for RKS
        if Z > B and A > 0:
            ln_phi = Z - 1 - np.log(Z - B) - (A/B) * np.log(1 + B/Z)
            phi = np.exp(ln_phi)
        else:
            phi = 1.0
        
        fugacity = pressure * phi
        
        # Enhanced corrections for geological conditions
        if temperature > 773:  # High temperature
            temp_correction = 1 + 0.005 * (temperature - 773) / 773
            fugacity *= temp_correction
        
        if pressure > 5e7:  # Very high pressure
            pressure_correction = 1 + 0.02 * np.log(pressure / 5e7)
            fugacity *= pressure_correction
        
        # Molecular association effects at moderate conditions
        if 273 < temperature < 373 and pressure > 1e6:
            association_factor = 0.98 + 0.02 * np.exp(-pressure / 1e7)
            fugacity *= association_factor
        
        return max(fugacity, pressure * 0.05)  # Ensure reasonable bounds
    
    def _calculate_virial_correction_h2o(self, temperature: float, pressure: float) -> float:
        """Calculate virial equation corrections for water at very high pressures"""
        
        R = 8.314472
        
        # Second virial coefficient for water (empirical correlation)
        Tc = 647.096
        Tr = temperature / Tc
        
        # Lee-Kesler correlation for second virial coefficient
        B0 = 0.083 - 0.422 / Tr**1.6
        B1 = 0.139 - 0.172 / Tr**4.2
        omega = 0.3449
        
        B = R * Tc / 2.2064e7 * (B0 + omega * B1)  # m³/mol
        
        # Third virial coefficient (simplified)
        C = B**2 * (0.01 + 0.05 * omega)
        
        # Virial equation: Z = 1 + B*P/(RT) + C*P²/(RT)²
        Z_virial = 1 + B * pressure / (R * temperature) + \
                   C * pressure**2 / (R * temperature)**2
        
        return Z_virial
    
    def _get_molecular_interaction_database(self) -> Dict[str, Dict[str, float]]:
        """Advanced molecular interaction parameters database"""
        
        return {
            'binary_interactions': {
                'Si-Al': {'epsilon_ij': -125.0, 'sigma_ij': 3.85, 'kappa_ij': 0.02},
                'Fe-Mg': {'epsilon_ij': -89.5, 'sigma_ij': 3.42, 'kappa_ij': 0.015},
                'Ca-Na': {'epsilon_ij': -156.3, 'sigma_ij': 4.12, 'kappa_ij': 0.025},
                'Al-Fe': {'epsilon_ij': -102.7, 'sigma_ij': 3.28, 'kappa_ij': 0.018},
                'Si-Mg': {'epsilon_ij': -134.2, 'sigma_ij': 3.67, 'kappa_ij': 0.022}
            },
            'ternary_interactions': {
                'Si-Al-Fe': {'tau_123': 0.95, 'alpha_123': 0.28},
                'Ca-Na-K': {'tau_123': 1.08, 'alpha_123': 0.32},
                'Fe-Mg-Si': {'tau_123': 0.87, 'alpha_123': 0.25}
            },
            'temperature_dependence': {
                'linear_coeff': -0.5,
                'quadratic_coeff': 0.001,
                'reference_temp': 1273.0
            }
        }
    
    def _apply_element_partitioning(self, phase: str, composition: Dict[str, float], all_amounts: np.ndarray, phases: List[str], temperature: float, pressure: float) -> Dict[str, float]:
        """Apply element partitioning between phases"""
        
        if not hasattr(self, 'element_partitioning_database'):
            return composition
        
        partitioned_composition = composition.copy()
        
        # Apply trace element partitioning
        if 'trace_elements' in self.element_partitioning_database:
            partitioned_composition = self._apply_trace_element_partitioning(phase, partitioned_composition, temperature, pressure)
        
        # Apply major element exchange
        if 'exchange_coefficients' in self.element_partitioning_database:
            partitioned_composition = self._apply_major_element_exchange(phase, partitioned_composition, all_amounts, phases, temperature, pressure)
        
        return partitioned_composition
    
    def _apply_trace_element_partitioning(self, phase: str, composition: Dict[str, float], temperature: float, pressure: float) -> Dict[str, float]:
        """Apply trace element partitioning coefficients"""
        
        trace_db = self.element_partitioning_database['trace_elements']
        partitioned_comp = composition.copy()
        
        for element, partitioning_data in trace_db.items():
            phase_key = f"{phase}/melt"
            
            if phase_key in partitioning_data:
                partition_data = partitioning_data[phase_key]
                
                # Calculate temperature-dependent partition coefficient
                D0 = partition_data['D0']
                dT = partition_data['dT']
                dP = partition_data['dP']
                
                D = D0 + dT * (temperature - 1273) + dP * (pressure - 1e5)
                
                # Apply composition dependence if specified
                if partition_data.get('composition_dependence', False):
                    comp_factor = self._calculate_composition_factor(phase, element, composition)
                    D *= comp_factor
                
                # Modify element abundance
                if element in partitioned_comp:
                    partitioned_comp[element] *= D
        
        return partitioned_comp
    
    def _calculate_composition_factor(self, phase: str, element: str, composition: Dict[str, float]) -> float:
        """Calculate composition-dependent partitioning factor"""
        
        # Element-specific composition effects
        if element == 'Sr' and phase == 'plagioclase':
            # Sr partitioning depends on An content
            an_content = composition.get('CaO', 0.0) / (composition.get('CaO', 0.0) + composition.get('Na2O', 1.0))
            return 1.0 + 2.0 * an_content  # Enhanced partitioning with An content
        
        elif element == 'Rb' and 'biotite' in phase:
            # Rb partitioning enhanced by K content
            k_content = composition.get('K2O', 0.0)
            return 1.0 + 0.5 * k_content
        
        return 1.0  # Default no composition effect
    
    def _apply_major_element_exchange(self, phase: str, composition: Dict[str, float], all_amounts: np.ndarray, phases: List[str], temperature: float, pressure: float) -> Dict[str, float]:
        """Apply major element exchange equilibria"""
        
        exchange_db = self.element_partitioning_database['exchange_coefficients']
        exchanged_comp = composition.copy()
        
        # Fe-Mg exchange
        if 'Fe_Mg' in exchange_db and phase in ['olivine', 'clinopyroxene', 'orthopyroxene', 'garnet']:
            exchange_key = f"{phase}_melt"
            
            if exchange_key in exchange_db['Fe_Mg']:
                kd_data = exchange_db['Fe_Mg'][exchange_key]
                
                KD0 = kd_data['KD0']
                dT = kd_data['dT']
                dP = kd_data['dP']
                
                KD = KD0 + dT * (temperature - 1273) + dP * (pressure - 1e5)
                
                # Apply Fe-Mg redistribution
                if 'FeO' in exchanged_comp and 'MgO' in exchanged_comp:
                    Fe_total = exchanged_comp['FeO']
                    Mg_total = exchanged_comp['MgO']
                    
                    # Solve for equilibrium distribution
                    X_Fe_new = Fe_total / (Fe_total + Mg_total * KD)
                    X_Mg_new = 1.0 - X_Fe_new
                    
                    total_FM = Fe_total + Mg_total
                    exchanged_comp['FeO'] = X_Fe_new * total_FM
                    exchanged_comp['MgO'] = X_Mg_new * total_FM
        
        # Ca-Na exchange (feldspar)
        if 'Ca_Na' in exchange_db and phase == 'plagioclase':
            kd_data = exchange_db['Ca_Na']['plagioclase_melt']
            
            KD0 = kd_data['KD0']
            dT = kd_data['dT']
            dP = kd_data['dP']
            
            KD = KD0 + dT * (temperature - 1273) + dP * (pressure - 1e5)
            
            if 'CaO' in exchanged_comp and 'Na2O' in exchanged_comp:
                Ca_total = exchanged_comp['CaO']
                Na_total = exchanged_comp['Na2O']
                
                X_Ca_new = Ca_total / (Ca_total + Na_total / KD)
                X_Na_new = 1.0 - X_Ca_new
                
                total_CaNa = Ca_total + Na_total
                exchanged_comp['CaO'] = X_Ca_new * total_CaNa
                exchanged_comp['Na2O'] = X_Na_new * total_CaNa
        
        return exchanged_comp
    
    def _apply_mass_balance_constraints(self, bulk_comp: Dict[str, float], phase_contributions: Dict[str, Dict[str, float]], all_amounts: np.ndarray, phases: List[str]) -> Dict[str, float]:
        """Apply mass balance constraints to ensure stoichiometric consistency"""
        
        constrained_comp = bulk_comp.copy()
        
        # Check charge balance for major elements
        constrained_comp = self._enforce_charge_balance(constrained_comp)
        
        # Apply stoichiometric constraints
        constrained_comp = self._enforce_stoichiometric_constraints(constrained_comp)
        
        # Normalize to ensure mass conservation
        total_mass = sum(constrained_comp.values())
        if total_mass > 0:
            for element in constrained_comp:
                constrained_comp[element] /= total_mass
        
        return constrained_comp
    
    def _enforce_charge_balance(self, composition: Dict[str, float]) -> Dict[str, float]:
        """Enforce charge balance for ionic species"""
        
        balanced_comp = composition.copy()
        
        # Define oxidation states
        oxidation_states = {
            'SiO2': 0, 'Al2O3': 0, 'FeO': 0, 'MgO': 0, 'CaO': 0,
            'Na2O': 0, 'K2O': 0, 'TiO2': 0, 'MnO': 0, 'Cr2O3': 0
        }
        
        # Calculate total positive and negative charges
        positive_charge = 0
        negative_charge = 0
        
        for oxide, amount in balanced_comp.items():
            if oxide in oxidation_states:
                if oxide in ['SiO2', 'Al2O3', 'TiO2', 'Cr2O3']:
                    positive_charge += amount * 2  # Simplified charge contribution
                else:
                    negative_charge += amount * 2
        
        # Adjust composition to maintain charge balance
        charge_imbalance = positive_charge - negative_charge
        
        if abs(charge_imbalance) > 0.01:  # Significant imbalance
            correction_factor = 1.0 - charge_imbalance / (positive_charge + negative_charge)
            
            for oxide in balanced_comp:
                balanced_comp[oxide] *= correction_factor
        
        return balanced_comp
    
    def _enforce_stoichiometric_constraints(self, composition: Dict[str, float]) -> Dict[str, float]:
        """Enforce stoichiometric constraints for mineral formulae"""
        
        constrained_comp = composition.copy()
        
        # Enforce Si:O ratios
        if 'SiO2' in constrained_comp:
            si_content = constrained_comp['SiO2']
            # Ensure minimum silica for silicate minerals
            min_silica = 0.4  # 40% minimum
            if si_content < min_silica:
                # Redistribute excess to other components
                excess = min_silica - si_content
                constrained_comp['SiO2'] = min_silica
                
                # Reduce other components proportionally
                other_total = sum(v for k, v in constrained_comp.items() if k != 'SiO2')
                if other_total > 0:
                    scale_factor = (1.0 - min_silica) / other_total
                    for oxide in constrained_comp:
                        if oxide != 'SiO2':
                            constrained_comp[oxide] *= scale_factor
        
        # Enforce Al:Si ratios for aluminosilicates
        if 'Al2O3' in constrained_comp and 'SiO2' in constrained_comp:
            al_content = constrained_comp['Al2O3']
            si_content = constrained_comp['SiO2']
            
            # Maximum Al/Si ratio for common minerals
            max_al_si_ratio = 0.5  # Al2O3:SiO2 = 1:2
            current_ratio = al_content / (si_content + 1e-10)
            
            if current_ratio > max_al_si_ratio:
                # Adjust Al content
                constrained_comp['Al2O3'] = si_content * max_al_si_ratio
        
        return constrained_comp
    
    def _calculate_element_redistribution(self, bulk_comp: Dict[str, float], temperature: float, pressure: float) -> Dict[str, float]:
        """Calculate element redistribution due to diffusion and kinetic effects"""
        
        redistributed_comp = bulk_comp.copy()
        
        # Calculate diffusion coefficients
        diffusion_coeffs = self._calculate_diffusion_coefficients(temperature, pressure)
        
        # Apply kinetic redistribution for fast-diffusing elements
        for element, D in diffusion_coeffs.items():
            if element in redistributed_comp and D > 1e-12:  # Fast diffusion
                # Enhanced mobility leads to homogenization
                mobility_factor = min(1.0 + np.log10(D / 1e-15), 2.0)
                redistributed_comp[element] *= mobility_factor
        
        # Renormalize to maintain mass balance
        total = sum(redistributed_comp.values())
        if total > 0:
            for element in redistributed_comp:
                redistributed_comp[element] /= total
        
        return redistributed_comp
    
    def _calculate_diffusion_coefficients(self, temperature: float, pressure: float, composition: Dict[str, float] = None) -> Dict[str, any]:
        """Calculate advanced multicomponent diffusion coefficients with structural mechanisms"""
        
        R = 8.314472  # J/(mol·K)
        
        if composition is None:
            composition = {'SiO2': 0.6, 'Al2O3': 0.15, 'FeO': 0.1, 'MgO': 0.08, 'CaO': 0.04, 'Na2O': 0.02, 'K2O': 0.01}
        
        # Advanced diffusion database with multiple mechanisms
        diffusion_database = self._get_advanced_diffusion_database()
        
        # Calculate multicomponent diffusion matrix
        diffusion_matrix = self._calculate_multicomponent_diffusion_matrix(
            temperature, pressure, composition, diffusion_database
        )
        
        # Calculate self-diffusion coefficients
        self_diffusion = self._calculate_self_diffusion_coefficients(
            temperature, pressure, composition, diffusion_database
        )
        
        # Calculate tracer diffusion coefficients
        tracer_diffusion = self._calculate_tracer_diffusion_coefficients(
            temperature, pressure, composition, diffusion_database
        )
        
        # Calculate chemical diffusion coefficients
        chemical_diffusion = self._calculate_chemical_diffusion_coefficients(
            diffusion_matrix, composition, temperature
        )
        
        # Calculate anisotropic diffusion tensors for crystalline phases
        anisotropic_tensors = self._calculate_anisotropic_diffusion_tensors(
            temperature, pressure, composition
        )
        
        return {
            'multicomponent_matrix': diffusion_matrix,
            'self_diffusion': self_diffusion,
            'tracer_diffusion': tracer_diffusion,
            'chemical_diffusion': chemical_diffusion,
            'anisotropic_tensors': anisotropic_tensors,
            'effective_diffusion': self._calculate_effective_diffusion_coefficients(
                self_diffusion, composition, temperature, pressure
            )
        }
    
