    def _calculate_multicomponent_diffusion_matrix(self, temperature: float, pressure: float, 
                                                 composition: Dict[str, float], 
                                                 database: Dict[str, Dict[str, any]]) -> np.ndarray:
        """Calculate multicomponent diffusion matrix using Onsager reciprocal relations"""
        
        R = 8.314472
        components = list(composition.keys())
        n_comp = len(components)
        
        # Initialize diffusion matrix
        D_matrix = np.zeros((n_comp, n_comp))
        
        for i, comp_i in enumerate(components):
            for j, comp_j in enumerate(components):
                if i == j:
                    # Diagonal terms - self-diffusion with thermodynamic factor
                    D_ii = self._calculate_diagonal_diffusion_term(
                        comp_i, temperature, pressure, composition, database
                    )
                    
                    # Thermodynamic factor correction
                    thermodynamic_factor = self._calculate_thermodynamic_factor(
                        comp_i, composition, temperature
                    )
                    
                    D_matrix[i, j] = D_ii * thermodynamic_factor
                    
                else:
                    # Off-diagonal terms - cross-diffusion coefficients
                    D_ij = self._calculate_cross_diffusion_term(
                        comp_i, comp_j, temperature, pressure, composition, database
                    )
                    
                    D_matrix[i, j] = D_ij
        
        # Ensure Onsager reciprocal relations
        D_matrix = 0.5 * (D_matrix + D_matrix.T)
        
        return D_matrix
    
    def _calculate_diagonal_diffusion_term(self, component: str, temperature: float, 
                                         pressure: float, composition: Dict[str, float],
                                         database: Dict[str, Dict[str, any]]) -> float:
        """Calculate diagonal diffusion matrix term with multiple mechanisms"""
        
        R = 8.314472
        
        if component not in database:
            return 1e-20  # Default very small value
        
        mechanisms = database[component]
        total_diffusivity = 0.0
        
        for mechanism_name, params in mechanisms.items():
            if mechanism_name in ['vacancy_mechanism', 'interstitial_mechanism', 'collective_mechanism']:
                D0 = params['D0']
                Ea = params['Ea']
                Va = params['Va']
                f_corr = params.get('correlation_factor', 1.0)
                
                # Basic Arrhenius with pressure correction
                D_mech = D0 * np.exp(-Ea / (R * temperature)) * \
                        np.exp(-Va * pressure / (R * temperature)) * f_corr
                
                # Mechanism-specific modifications
                if mechanism_name == 'vacancy_mechanism':
                    # Vacancy concentration dependence
                    vacancy_conc = self._calculate_vacancy_concentration(temperature, pressure)
                    D_mech *= vacancy_conc
                    
                elif mechanism_name == 'interstitial_mechanism':
                    # Interstitial site availability
                    site_availability = self._calculate_interstitial_sites(composition)
                    D_mech *= site_availability
                    
                elif mechanism_name == 'collective_mechanism':
                    # Cooperative motion enhancement
                    coop_factor = self._calculate_cooperative_factor(composition, temperature)
                    D_mech *= coop_factor
                
                total_diffusivity += D_mech
        
        return max(total_diffusivity, 1e-25)  # Prevent numerical issues
    
    def _calculate_cross_diffusion_term(self, comp_i: str, comp_j: str, temperature: float,
                                      pressure: float, composition: Dict[str, float],
                                      database: Dict[str, Dict[str, any]]) -> float:
        """Calculate cross-diffusion coefficients using mixing rules"""
        
        # Geometric mean approximation with interaction parameters
        D_ii = self._calculate_diagonal_diffusion_term(comp_i, temperature, pressure, composition, database)
        D_jj = self._calculate_diagonal_diffusion_term(comp_j, temperature, pressure, composition, database)
        
        # Interaction parameter based on ionic radius and charge differences
        interaction_param = self._calculate_interaction_parameter(comp_i, comp_j, temperature)
        
        # Cross-diffusion coefficient
        D_ij = -np.sqrt(D_ii * D_jj) * interaction_param * composition.get(comp_i, 0) * composition.get(comp_j, 0)
        
        return D_ij
    
    def _calculate_thermodynamic_factor(self, component: str, composition: Dict[str, float], temperature: float) -> float:
        """Calculate thermodynamic factor for chemical diffusion"""
        
        x_i = composition.get(component, 0)
        if x_i <= 0:
            return 1.0
        
        # Activity coefficient derivative (simplified UNIQUAC-based)
        gamma_params = self._get_uniquac_parameters('melt', component, temperature)
        
        # Thermodynamic factor approximation
        ln_gamma_deriv = 1 + gamma_params.get('tau_12', 1.0) * (1 - 2 * x_i)
        thermodynamic_factor = 1 + x_i * ln_gamma_deriv
        
        return max(thermodynamic_factor, 0.1)
    
    def _calculate_vacancy_concentration(self, temperature: float, pressure: float) -> float:
        """Calculate equilibrium vacancy concentration"""
        
        R = 8.314472
        
        # Vacancy formation energy and volume
        Ef_vac = 180000  # J/mol
        Vf_vac = 8.5e-6  # m³/mol
        
        # Boltzmann factor
        C_vac = np.exp(-(Ef_vac + pressure * Vf_vac) / (R * temperature))
        
        return min(C_vac, 0.1)  # Cap at reasonable maximum
    
    def _calculate_interstitial_sites(self, composition: Dict[str, float]) -> float:
        """Calculate available interstitial sites based on structure"""
        
        # Network modifier concentration affects site availability
        modifier_content = composition.get('Na2O', 0) + composition.get('K2O', 0) + composition.get('CaO', 0)
        
        # More modifiers create more interstitial pathways
        site_factor = 0.1 + 0.9 * modifier_content / (0.2 + modifier_content)
        
        return site_factor
    
    def _calculate_cooperative_factor(self, composition: Dict[str, float], temperature: float) -> float:
        """Calculate cooperative motion enhancement factor"""
        
        # Higher temperatures and network connectivity enhance cooperative motion
        network_connectivity = composition.get('SiO2', 0) + composition.get('Al2O3', 0)
        
        coop_factor = 1 + 0.5 * network_connectivity * np.exp(-5000 / (8.314 * temperature))
        
        return coop_factor
    
    def _calculate_interaction_parameter(self, comp_i: str, comp_j: str, temperature: float) -> float:
        """Calculate binary interaction parameter for cross-diffusion"""
        
        # Interaction parameters based on ionic properties
        interaction_matrix = {
            ('SiO2', 'Al2O3'): 0.15,
            ('Na2O', 'K2O'): 0.25,
            ('FeO', 'MgO'): 0.18,
            ('CaO', 'MgO'): 0.12,
            ('SiO2', 'Na2O'): 0.08,
            ('Al2O3', 'CaO'): 0.22
        }
        
        key = (comp_i, comp_j) if (comp_i, comp_j) in interaction_matrix else (comp_j, comp_i)
        base_param = interaction_matrix.get(key, 0.05)  # Default small interaction
        
        # Temperature dependence
        temp_factor = 1 + 0.001 * (temperature - 1273)
        
        return base_param * temp_factor
    
    def _calculate_self_diffusion_coefficients(self, temperature: float, pressure: float,
                                             composition: Dict[str, float],
                                             database: Dict[str, Dict[str, any]]) -> Dict[str, float]:
        """Calculate self-diffusion coefficients"""
        
        self_diffusion = {}
        
        for component in composition.keys():
            # Self-diffusion is diagonal term without thermodynamic factor
            D_self = self._calculate_diagonal_diffusion_term(
                component, temperature, pressure, composition, database
            )
            self_diffusion[component] = D_self
        
        return self_diffusion
    
    def _calculate_tracer_diffusion_coefficients(self, temperature: float, pressure: float,
                                                composition: Dict[str, float],
                                                database: Dict[str, Dict[str, any]]) -> Dict[str, float]:
        """Calculate tracer diffusion coefficients with isotope effects"""
        
        tracer_diffusion = {}
        
        # Isotope mass effects
        isotope_masses = {
            'SiO2': (28.0855, 29.0738),  # 28Si, 29Si
            'Al2O3': (26.9815, 26.9815),  # 27Al (monoisotopic)
            'FeO': (55.845, 56.935),     # 56Fe, 57Fe
            'MgO': (24.305, 25.983),     # 24Mg, 26Mg
            'CaO': (40.078, 42.959),     # 40Ca, 43Ca
            'Na2O': (22.990, 22.990),    # 23Na (monoisotopic)
            'K2O': (39.098, 40.962)      # 39K, 41K
        }
        
        for component in composition.keys():
            D_self = self._calculate_diagonal_diffusion_term(
                component, temperature, pressure, composition, database
            )
            
            if component in isotope_masses:
                m1, m2 = isotope_masses[component]
                # Kinetic isotope effect
                isotope_factor = np.sqrt(m1 / m2) if m1 != m2 else 1.0
                D_tracer = D_self * isotope_factor
            else:
                D_tracer = D_self
            
            tracer_diffusion[component] = D_tracer
        
        return tracer_diffusion
    
    def _calculate_chemical_diffusion_coefficients(self, diffusion_matrix: np.ndarray,
                                                  composition: Dict[str, float],
                                                  temperature: float) -> Dict[str, float]:
        """Calculate chemical diffusion coefficients from diffusion matrix"""
        
        # Chemical diffusion involves matrix operations with composition gradients
        components = list(composition.keys())
        chemical_diffusion = {}
        
        # For simplicity, use eigenvalues of diffusion matrix
        eigenvals = np.linalg.eigvals(diffusion_matrix)
        eigenvals = eigenvals[eigenvals > 0]  # Keep positive eigenvalues
        
        for i, component in enumerate(components):
            if i < len(eigenvals):
                chemical_diffusion[component] = float(eigenvals[i])
            else:
                chemical_diffusion[component] = 1e-20
        
        return chemical_diffusion
    
    def _calculate_anisotropic_diffusion_tensors(self, temperature: float, pressure: float,
                                               composition: Dict[str, float]) -> Dict[str, np.ndarray]:
        """Calculate anisotropic diffusion tensors for crystalline phases"""
        
        anisotropic_tensors = {}
        
        # Crystal structure-dependent anisotropy
        crystal_anisotropy = {
            'olivine': {'a_axis': 1.0, 'b_axis': 0.3, 'c_axis': 0.1},
            'pyroxene': {'a_axis': 1.0, 'b_axis': 0.8, 'c_axis': 0.4},
            'feldspar': {'a_axis': 1.0, 'b_axis': 0.9, 'c_axis': 0.7},
            'quartz': {'a_axis': 1.0, 'b_axis': 1.0, 'c_axis': 0.2}
        }
        
        for phase, aniso in crystal_anisotropy.items():
            # 3x3 diffusion tensor
            tensor = np.zeros((3, 3))
            
            # Base diffusivity (average of component diffusivities)
            base_D = sum(self._calculate_diagonal_diffusion_term(
                comp, temperature, pressure, composition, self._get_advanced_diffusion_database()
            ) for comp in composition.keys()) / len(composition)
            
            # Diagonal terms with crystallographic anisotropy
            tensor[0, 0] = base_D * aniso['a_axis']  # a-axis
            tensor[1, 1] = base_D * aniso['b_axis']  # b-axis
            tensor[2, 2] = base_D * aniso['c_axis']  # c-axis
            
            # Small off-diagonal terms for crystal imperfections
            tensor[0, 1] = tensor[1, 0] = base_D * 0.05
            tensor[0, 2] = tensor[2, 0] = base_D * 0.02
            tensor[1, 2] = tensor[2, 1] = base_D * 0.03
            
            anisotropic_tensors[phase] = tensor
        
        return anisotropic_tensors
    
    def _calculate_effective_diffusion_coefficients(self, self_diffusion: Dict[str, float],
                                                  composition: Dict[str, float],
                                                  temperature: float, pressure: float) -> Dict[str, float]:
        """Calculate effective diffusion coefficients for transport modeling"""
        
        effective_diffusion = {}
        
        for component, D_self in self_diffusion.items():
            x_i = composition.get(component, 0)
            
            # Effective diffusivity accounts for concentration and tortuosity
            tortuosity_factor = 0.5 + 0.5 * x_i  # Higher concentration = less tortuous path
            
            # Connectivity factor based on network structure
            if component in ['SiO2', 'Al2O3']:
                connectivity = 0.8  # Network formers - high connectivity
            elif component in ['Na2O', 'K2O']:
                connectivity = 0.3  # Network modifiers - low connectivity
            else:
                connectivity = 0.6  # Intermediate
            
            D_eff = D_self * tortuosity_factor * connectivity
            
            # Microstructural effects (grain size, porosity)
            microstructure_factor = self._calculate_microstructure_factor(temperature, pressure)
            D_eff *= microstructure_factor
            
            effective_diffusion[component] = D_eff
        
        return effective_diffusion
    
    def _calculate_microstructure_factor(self, temperature: float, pressure: float) -> float:
        """Calculate microstructural influence on diffusion"""
        
        # Temperature-dependent grain growth
        grain_growth_factor = 1 + 0.1 * np.log(temperature / 1273) if temperature > 1273 else 1.0
        
        # Pressure-dependent porosity reduction
        porosity_factor = 1 - 0.05 * np.log(pressure / 1e5) if pressure > 1e5 else 1.0
        
        return grain_growth_factor * max(porosity_factor, 0.1)
    
    def _get_simple_phase_stoichiometry(self, phase: str) -> Dict[str, float]:
        """Fallback simple stoichiometry for unknown phases"""
        
        # Simplified stoichiometry database for backward compatibility
        simple_stoichiometry_db = {
            'quartz': {'SiO2': 1.0},
            'albite': {'SiO2': 6.0, 'Al2O3': 1.0, 'Na2O': 1.0},
            'anorthite': {'SiO2': 2.0, 'Al2O3': 1.0, 'CaO': 1.0},
            'orthoclase': {'SiO2': 6.0, 'Al2O3': 1.0, 'K2O': 1.0},
            'forsterite': {'SiO2': 1.0, 'MgO': 2.0},
            'fayalite': {'SiO2': 1.0, 'FeO': 2.0},
            'enstatite': {'SiO2': 2.0, 'MgO': 1.0},
            'diopside': {'SiO2': 2.0, 'CaO': 1.0, 'MgO': 1.0},
            'grossular': {'SiO2': 3.0, 'Al2O3': 1.0, 'CaO': 3.0},
            'pyrope': {'SiO2': 3.0, 'Al2O3': 1.0, 'MgO': 3.0},
            'muscovite': {'SiO2': 3.0, 'Al2O3': 3.0, 'K2O': 1.0, 'H2O': 1.0},
            'biotite': {'SiO2': 3.0, 'Al2O3': 1.5, 'FeO': 3.0, 'K2O': 1.0, 'H2O': 1.0},
            'hornblende': {'SiO2': 7.0, 'Al2O3': 1.0, 'CaO': 2.0, 'MgO': 3.0, 'FeO': 2.0, 'H2O': 1.0},
            'magnetite': {'FeO': 1.0, 'Fe2O3': 1.0},
            'ilmenite': {'FeO': 1.0, 'TiO2': 1.0},
            'apatite': {'CaO': 5.0, 'P2O5': 3.0, 'F': 1.0},
            'zircon': {'ZrO2': 1.0, 'SiO2': 1.0}
        }
        
        return simple_stoichiometry_db.get(phase, {})
    
    def _calculate_plagioclase_activity_coefficient(self, component: str, X_ab: float, 
                                                  X_an: float, X_or: float, temperature: float, pressure: float) -> float:
        """Calculate activity coefficient for plagioclase components"""
        
        R = 8.314  # J/(mol·K)
        
        # Get interaction parameters
        W_ab_an = self.solid_solution_database['plagioclase']['interaction_parameters']['W_ab_an']
        W_ab_or = self.solid_solution_database['plagioclase']['interaction_parameters']['W_ab_or']
        W_an_or = self.solid_solution_database['plagioclase']['interaction_parameters']['W_an_or']
        
        if component == 'albite':
            # Margules expansion for albite
            ln_gamma = (W_ab_an[0] * X_an**2 + W_ab_or[0] * X_or**2 + 
                       0.5 * (W_ab_an[0] + W_ab_or[0] - W_an_or[0]) * X_an * X_or) / (R * temperature)
        elif component == 'anorthite':
            # Margules expansion for anorthite
            ln_gamma = (W_ab_an[0] * X_ab**2 + W_an_or[0] * X_or**2 + 
                       0.5 * (W_ab_an[0] + W_an_or[0] - W_ab_or[0]) * X_ab * X_or) / (R * temperature)
        else:  # orthoclase
            # Margules expansion for orthoclase
            ln_gamma = (W_ab_or[0] * X_ab**2 + W_an_or[0] * X_an**2 + 
                       0.5 * (W_ab_or[0] + W_an_or[0] - W_ab_an[0]) * X_ab * X_an) / (R * temperature)
        
        return np.exp(ln_gamma)
    
    def _calculate_al_si_ordering_factor(self, X_an: float, temperature: float) -> float:
        """Calculate Al-Si ordering factor for plagioclase"""
        
        # Al-Si ordering becomes more pronounced at lower temperatures and higher An content
        ordering_params = self.solid_solution_database['plagioclase']['ordering_parameters']['Al_Si_T1']
        Tc = ordering_params['Tc']
        Q = ordering_params['Q']
        
        R = 8.314
        
        if temperature > Tc:
            # Disordered state
            ordering_factor = 1.0
        else:
            # Ordered state - stronger ordering with higher An content
            ordering_strength = np.exp(-Q * X_an / (R * temperature))
            ordering_factor = 1.0 + 0.2 * X_an * ordering_strength
        
        return ordering_factor
    
    def _calculate_olivine_site_distribution(self, X_Mg: float, X_Fe: float, X_Mn: float, 
                                           X_Ni: float, temperature: float, pressure: float) -> Dict[str, Dict[str, float]]:
        """Calculate cation distribution between M1 and M2 sites in olivine"""
        
        # Get site preference parameters
        K_D_Mn = 0.8  # Mn prefers M2 slightly
        
        # Calculate site distributions using simple equilibrium
        total_cations = X_Mg + X_Fe + X_Mn + X_Ni
        
        if total_cations < 1e-12:
            return {'M1': {'Mg': 0.5, 'Fe': 0.5}, 'M2': {'Mg': 0.5, 'Fe': 0.5}}
        
        # Mg and Fe distribute randomly
        M1_Mg = X_Mg / 2
        M1_Fe = X_Fe / 2
        M2_Mg = X_Mg / 2
        M2_Fe = X_Fe / 2
        
        # Mn prefers M2 site
        M1_Mn = X_Mn / (1 + K_D_Mn)
        M2_Mn = X_Mn - M1_Mn
        
        return {
            'M1': {'Mg': M1_Mg, 'Fe': M1_Fe, 'Mn': M1_Mn},
            'M2': {'Mg': M2_Mg, 'Fe': M2_Fe, 'Mn': M2_Mn}
        }
    
    def _calculate_olivine_activity_coefficient(self, component: str, X_Mg: float, 
                                              X_Fe: float, X_Mn: float, temperature: float) -> float:
        """Calculate activity coefficient for olivine components"""
        
        R = 8.314
        
        # Regular solution parameters
        W_fo_fa = 8000.0  # J/mol
        W_fo_teph = 12000.0  # J/mol
        W_fa_teph = 6000.0  # J/mol
        
        if component == 'forsterite':
            ln_gamma = (W_fo_fa * X_Fe**2 + W_fo_teph * X_Mn**2) / (R * temperature)
        elif component == 'fayalite':
            ln_gamma = (W_fo_fa * X_Mg**2 + W_fa_teph * X_Mn**2) / (R * temperature)
        else:  # tephroite
            ln_gamma = (W_fo_teph * X_Mg**2 + W_fa_teph * X_Fe**2) / (R * temperature)
        
        return np.exp(ln_gamma)
    
    def _calculate_garnet_activity_coefficients(self, X_Ca: float, X_Mg: float, X_Fe: float, 
                                              X_Mn: float, temperature: float, pressure: float) -> Dict[str, float]:
        """Calculate activity coefficients for garnet components"""
        
        R = 8.314
        
        # Interaction parameters
        W_pyr_alm = 2500.0
        W_pyr_gross = 12000.0
        W_alm_gross = 15000.0
        W_pyr_spess = 8000.0
        
        activity_coeffs = {}
        
        # Pyrope
        ln_gamma_pyr = (W_pyr_alm * X_Fe**2 + W_pyr_gross * X_Ca**2 + W_pyr_spess * X_Mn**2) / (R * temperature)
        activity_coeffs['pyrope'] = np.exp(ln_gamma_pyr)
        
        # Almandine
        ln_gamma_alm = (W_pyr_alm * X_Mg**2 + W_alm_gross * X_Ca**2) / (R * temperature)
        activity_coeffs['almandine'] = np.exp(ln_gamma_alm)
        
        # Grossular
        ln_gamma_gross = (W_pyr_gross * X_Mg**2 + W_alm_gross * X_Fe**2) / (R * temperature)
        activity_coeffs['grossular'] = np.exp(ln_gamma_gross)
        
        # Spessartine
        ln_gamma_spess = (W_pyr_spess * X_Mg**2) / (R * temperature)
        activity_coeffs['spessartine'] = np.exp(ln_gamma_spess)
        
        return activity_coeffs
    
    def _calculate_pyroxene_miscibility(self, X_Ca: float, temperature: float, pressure: float = 101325, X_Mg: float = None, X_Fe: float = None) -> Dict[str, any]:
        """Advanced pyroxene miscibility gap modeling using asymmetric regular solution theory with strain energy contributions"""
        import numpy as np
        from typing import Dict, Tuple
        
        R = 8.314472  # J/(mol·K)
        
        # Advanced pyroxene miscibility parameters from experimental calibrations
        miscibility_params = self._get_advanced_pyroxene_miscibility_parameters()
        
        # Ensure composition closure
        if X_Mg is None or X_Fe is None:
            X_Mg = max(0, 1 - X_Ca - 0.1)  # Estimate assuming some Fe
            X_Fe = max(0, 1 - X_Ca - X_Mg)
        
        # Normalize to ensure closure
        total = X_Ca + X_Mg + X_Fe
        if total > 0:
            X_Ca, X_Mg, X_Fe = X_Ca/total, X_Mg/total, X_Fe/total
        
        # 1. Asymmetric regular solution model for clinopyroxene-orthopyroxene
        W_cpx_opx = self._calculate_asymmetric_interaction_parameters(temperature, pressure)
        
        # 2. Calculate critical temperatures for different composition ranges
        critical_temperatures = self._calculate_pyroxene_critical_temperatures(X_Ca, X_Mg, X_Fe, pressure)
        
        # 3. Strain energy contribution from lattice mismatch
        strain_energy = self._calculate_pyroxene_strain_energy(X_Ca, X_Mg, X_Fe, temperature, pressure)
        
        # 4. Order-disorder contribution (C2/c to P21/c transition)
        order_disorder_energy = self._calculate_pyroxene_order_disorder(X_Ca, X_Mg, X_Fe, temperature)
        
        # 5. Site occupancy effects (M1 and M2 sites)
        site_occupancy_factors = self._calculate_pyroxene_site_occupancies(X_Ca, X_Mg, X_Fe, temperature)
        
        # 6. Calculate miscibility gap boundaries
        miscibility_boundaries = self._calculate_miscibility_gap_boundaries(
            X_Ca, X_Mg, X_Fe, temperature, pressure, W_cpx_opx, strain_energy
        )
        
        # 7. Thermodynamic stability analysis
        stability_analysis = self._analyze_pyroxene_phase_stability(
            X_Ca, X_Mg, X_Fe, temperature, pressure, critical_temperatures
        )
        
        # 8. Calculate effective miscibility factor with advanced corrections
        base_miscibility = self._calculate_base_miscibility_factor(
            X_Ca, temperature, critical_temperatures['T_c_bulk']
        )
        
        # Apply corrections
        strain_correction = np.exp(-strain_energy / (R * temperature))
        order_correction = np.exp(-order_disorder_energy / (R * temperature))
        site_correction = np.prod(list(site_occupancy_factors.values()))
        
        effective_miscibility = base_miscibility * strain_correction * order_correction * site_correction
        effective_miscibility = max(0.001, min(1.0, effective_miscibility))
        
        return {
            'miscibility_factor': effective_miscibility,
            'critical_temperatures': critical_temperatures,
            'strain_energy': strain_energy,  # J/mol
            'order_disorder_energy': order_disorder_energy,  # J/mol
            'site_occupancies': site_occupancy_factors,
            'miscibility_boundaries': miscibility_boundaries,
            'stability_analysis': stability_analysis,
            'interaction_parameters': W_cpx_opx,
            'phase_separation_tendency': 1 - effective_miscibility,
            'recommended_phases': self._recommend_pyroxene_phases(effective_miscibility, X_Ca, temperature)
        }
    
    def _get_advanced_pyroxene_miscibility_parameters(self) -> Dict[str, any]:
        """Get advanced pyroxene miscibility parameters from experimental and computational studies"""
        return {
            'W_CaMgSi2O6_Mg2Si2O6': {'W_0': 26400, 'W_1': -8.2, 'W_2': 0.0012},  # J/mol, fitted to experimental data
            'W_CaFeSi2O6_Fe2Si2O6': {'W_0': 29200, 'W_1': -9.1, 'W_2': 0.0015},
            'W_MgSi2O6_FeSi2O6': {'W_0': 4200, 'W_1': -2.1, 'W_2': 0.0003},
            'strain_parameters': {
                'bulk_modulus_cpx': 113e9,  # Pa
                'bulk_modulus_opx': 108e9,  # Pa
                'shear_modulus_cpx': 67e9,  # Pa
                'shear_modulus_opx': 76e9,  # Pa
                'lattice_mismatch_a': 0.023,  # Fractional difference
                'lattice_mismatch_b': 0.018,
                'lattice_mismatch_c': 0.031
            },
            'order_disorder': {
                'S_config_max': 11.53,  # J/(mol·K) maximum configurational entropy
                'H_order_CaMg': 12500,  # J/mol ordering enthalpy
                'H_order_CaFe': 15800,  # J/mol
                'T_c_order': 1023  # K, critical temperature for order-disorder
            }
        }
    
    def _calculate_asymmetric_interaction_parameters(self, temperature: float, pressure: float) -> Dict[str, float]:
        """Calculate temperature and pressure dependent asymmetric interaction parameters"""
        params = self._get_advanced_pyroxene_miscibility_parameters()
        
        W_interactions = {}
        for interaction, coeffs in params.items():
            if isinstance(coeffs, dict) and 'W_0' in coeffs:
                # W(T,P) = W_0 + W_1*T + W_2*T^2 + W_P*P
                W_P = 1e-6  # Pressure coefficient (J/mol/Pa)
                W_T = coeffs['W_0'] + coeffs['W_1'] * temperature + coeffs['W_2'] * temperature**2
                W_interactions[interaction] = W_T + W_P * pressure
        
        return W_interactions
    
    def _calculate_pyroxene_critical_temperatures(self, X_Ca: float, X_Mg: float, X_Fe: float, pressure: float) -> Dict[str, float]:
        """Calculate composition-dependent critical temperatures for miscibility gaps"""
        R = 8.314472
        
        # Base critical temperatures from experimental studies
        T_c_CaMg = 1273 + 0.15 * (pressure - 101325) / 1e6  # Pressure correction
        T_c_CaFe = 1198 + 0.12 * (pressure - 101325) / 1e6
        T_c_MgFe = 873 + 0.08 * (pressure - 101325) / 1e6
        
        # Composition-weighted critical temperature
        T_c_bulk = (X_Ca * X_Mg * T_c_CaMg + 
                   X_Ca * X_Fe * T_c_CaFe + 
                   X_Mg * X_Fe * T_c_MgFe) / max(0.001, X_Ca + X_Mg + X_Fe - X_Ca*X_Mg - X_Ca*X_Fe - X_Mg*X_Fe)
        
        return {
            'T_c_CaMg': T_c_CaMg,
            'T_c_CaFe': T_c_CaFe,
            'T_c_MgFe': T_c_MgFe,
            'T_c_bulk': T_c_bulk,
            'T_c_effective': min(T_c_bulk, max(T_c_CaMg, T_c_CaFe, T_c_MgFe))
        }
    
    def _calculate_pyroxene_strain_energy(self, X_Ca: float, X_Mg: float, X_Fe: float, temperature: float, pressure: float) -> float:
        """Calculate elastic strain energy from lattice mismatch between coexisting pyroxenes"""
        params = self._get_advanced_pyroxene_miscibility_parameters()['strain_parameters']
        
        # Estimate composition-dependent lattice parameters
        a_cpx = 9.746 + 0.143 * X_Ca - 0.021 * X_Fe  # Å, empirical relations
        b_cpx = 8.899 + 0.089 * X_Ca + 0.034 * X_Fe
        c_cpx = 5.251 + 0.067 * X_Ca - 0.012 * X_Fe
        
        a_opx = 18.227 - 0.156 * X_Ca + 0.178 * X_Fe
        b_opx = 8.815 - 0.023 * X_Ca + 0.089 * X_Fe
        c_opx = 5.179 - 0.034 * X_Ca + 0.045 * X_Fe
        
        # Lattice mismatch strains
        epsilon_a = abs(a_cpx - a_opx/2) / (a_cpx + a_opx/2)  # Factor of 2 for unit cell doubling
        epsilon_b = abs(b_cpx - b_opx) / (b_cpx + b_opx)
        epsilon_c = abs(c_cpx - c_opx) / (c_cpx + c_opx)
        
        # Elastic moduli (pressure-dependent)
        K_eff = (params['bulk_modulus_cpx'] + params['bulk_modulus_opx']) / 2
        G_eff = (params['shear_modulus_cpx'] + params['shear_modulus_opx']) / 2
        
        K_p = K_eff * (1 + 4.5 * pressure / K_eff)  # Pressure dependence
        G_p = G_eff * (1 + 1.8 * pressure / G_eff)
        
        # Strain energy density (J/m³)
        strain_energy_density = (K_p * (epsilon_a + epsilon_b + epsilon_c)**2 / 9 + 
                               G_p * (epsilon_a**2 + epsilon_b**2 + epsilon_c**2) / 3)
        
        # Convert to molar strain energy (J/mol)
        V_molar = 66.4e-6  # m³/mol, average molar volume
        strain_energy_molar = strain_energy_density * V_molar * 1000  # Convert to J/mol
        
        return strain_energy_molar
    
    def _calculate_pyroxene_order_disorder(self, X_Ca: float, X_Mg: float, X_Fe: float, temperature: float) -> float:
        """Calculate order-disorder contribution to miscibility (C2/c to P21/c transition)"""
        params = self._get_advanced_pyroxene_miscibility_parameters()['order_disorder']
        R = 8.314472
        
        # Order parameter based on Ca content and temperature
        T_c_order = params['T_c_order']
        
        if temperature > T_c_order:
            # Disordered state
            order_parameter = 0
        else:
            # Ordered state with temperature dependence
            order_parameter = np.sqrt(1 - temperature / T_c_order) * X_Ca
        
        # Configurational entropy
        if order_parameter > 1e-6:
            S_config = -R * (order_parameter * np.log(order_parameter) + 
                           (1 - order_parameter) * np.log(1 - order_parameter))
        else:
            S_config = 0
        
        # Ordering enthalpy
        H_order = (params['H_order_CaMg'] * X_Ca * X_Mg + 
                  params['H_order_CaFe'] * X_Ca * X_Fe) * order_parameter**2
        
        # Free energy of ordering
        G_order = H_order - temperature * S_config
        
        return G_order
    
    def _calculate_pyroxene_site_occupancies(self, X_Ca: float, X_Mg: float, X_Fe: float, temperature: float) -> Dict[str, float]:
        """Calculate M1 and M2 site occupancy factors affecting miscibility"""
        R = 8.314472
        
        # Site preference energies (J/mol) from crystal field theory
        delta_H_Ca_M2_M1 = -8400  # Ca strongly prefers M2 site
        delta_H_Mg_M2_M1 = 2100   # Mg slightly prefers M1 site
        delta_H_Fe_M2_M1 = 1800   # Fe slightly prefers M1 site
        
        # Boltzmann factors for site occupancy
        exp_Ca = np.exp(-delta_H_Ca_M2_M1 / (R * temperature))
        exp_Mg = np.exp(-delta_H_Mg_M2_M1 / (R * temperature))
        exp_Fe = np.exp(-delta_H_Fe_M2_M1 / (R * temperature))
        
        # Site occupancy probabilities (M2 site preference)
        P_Ca_M2 = exp_Ca / (1 + exp_Ca)
        P_Mg_M2 = 1 / (1 + exp_Mg)  # Inverse because Mg prefers M1
        P_Fe_M2 = 1 / (1 + exp_Fe)  # Inverse because Fe prefers M1
        
        # Site occupancy factors affecting miscibility
        site_factor_Ca = 1 - 0.3 * abs(P_Ca_M2 - 0.95)  # Ca should be mostly in M2
        site_factor_Mg = 1 - 0.2 * abs(P_Mg_M2 - 0.3)   # Mg should be mostly in M1
        site_factor_Fe = 1 - 0.25 * abs(P_Fe_M2 - 0.25)  # Fe should be mostly in M1
        
        return {
            'Ca_M2_occupancy': P_Ca_M2,
            'Mg_M2_occupancy': P_Mg_M2,
            'Fe_M2_occupancy': P_Fe_M2,
            'site_factor_Ca': site_factor_Ca,
            'site_factor_Mg': site_factor_Mg,
            'site_factor_Fe': site_factor_Fe
        }
    
    def _validate_and_correct_equilibrium(self, result: Dict, 
                                        temperature: float, pressure: float) -> Dict:
        """Advanced equilibrium validation and thermodynamic consistency correction using rigorous methods"""
        import numpy as np
        from typing import Dict, List, Tuple
        from scipy.optimize import minimize, least_squares
        
        validated_result = result.copy()
        R = 8.314472  # J/(mol·K)
        
        # 1. Comprehensive thermodynamic validation
        validation_results = self._check_mass_balance(result)  # Now returns comprehensive validation
        validated_result['validation_results'] = validation_results
        
        # 2. Advanced equilibrium correction algorithms
        if not validation_results.get('is_valid', False):
            corrected_result = self._apply_advanced_equilibrium_corrections(
                result, temperature, pressure, validation_results
            )
            validated_result.update(corrected_result)
        
        # 3. Phase stability analysis with convex hull reconstruction
        stability_analysis = self._perform_comprehensive_stability_analysis(
            validated_result, temperature, pressure
        )
        validated_result['stability_analysis'] = stability_analysis
        
        # 4. Chemical potential equilibrium enforcement
        chemical_potential_corrections = self._enforce_chemical_potential_equilibrium(
            validated_result, temperature, pressure
        )
        validated_result['chemical_potential_corrections'] = chemical_potential_corrections
        
        # 5. Metastability and kinetic barrier analysis
        metastability_analysis = self._analyze_metastable_equilibria(
            validated_result, temperature, pressure
        )
        validated_result['metastability_analysis'] = metastability_analysis
        
        # 6. Solution quality assessment with advanced metrics
        solution_quality = self._calculate_advanced_solution_quality(
            validated_result, validation_results, stability_analysis
        )
        validated_result['solution_quality'] = solution_quality
        
        # 7. Uncertainty propagation and confidence intervals
        uncertainty_analysis = self._calculate_equilibrium_uncertainties(
            validated_result, temperature, pressure
        )
        validated_result['uncertainty_analysis'] = uncertainty_analysis
        
        # 8. Thermodynamic path analysis
        path_analysis = self._analyze_thermodynamic_path_consistency(
            validated_result, temperature, pressure
        )
        validated_result['path_analysis'] = path_analysis
        
        return validated_result
    
    def _apply_advanced_equilibrium_corrections(self, result: Dict, temperature: float, pressure: float, validation_results: Dict) -> Dict:
        """Apply advanced equilibrium corrections using constrained optimization"""
        from scipy.optimize import minimize
        
        corrected_result = result.copy()
        
        # Extract phase amounts and compositions
        phase_names = list(result['phases'].keys())
        
        # 1. Mass balance correction using Lagrange multipliers
        if validation_results['mass_balance']:
            mass_corrected = self._correct_mass_balance_lagrange(result, temperature, pressure)
            corrected_result['phases'].update(mass_corrected)
        
        # 2. Chemical potential equilibrium correction
        if validation_results['chemical_potential']:
            chemical_corrected = self._correct_chemical_potentials(corrected_result, temperature, pressure)
            corrected_result['phases'].update(chemical_corrected)
        
        # 3. Gibbs energy minimization refinement
        gibbs_corrected = self._refine_gibbs_energy_minimum(corrected_result, temperature, pressure)
        corrected_result.update(gibbs_corrected)
        
        return corrected_result
    
    def _correct_mass_balance_lagrange(self, result: Dict, temperature: float, pressure: float) -> Dict:
        """Correct mass balance using Lagrange multiplier method"""
        from scipy.optimize import minimize
        import numpy as np
        
        def objective_function(x, *args):
            phase_amounts, system_composition, temperature, pressure = args
            
            # Update phase amounts
            for i, phase_name in enumerate(result['phases'].keys()):
                result['phases'][phase_name]['amount'] = max(0, x[i])
            
            # Calculate mass balance error
            mass_errors = self._validate_mass_conservation(result)
            total_error = sum(error**2 for error in mass_errors.values())
            
            # Add penalty for negative amounts
            penalty = sum(max(0, -xi)**2 * 1e6 for xi in x)
            
            return total_error + penalty
        
        # Initial guess from current phase amounts
        x0 = [result['phases'][phase]['amount'] for phase in result['phases']]
        system_comp = result.get('system_composition', {})
        
        # Constraints: total amount should be conserved
        total_amount = sum(x0)
        constraints = {'type': 'eq', 'fun': lambda x: sum(x) - total_amount}
        
        # Optimize
        opt_result = minimize(
            objective_function, x0, 
            args=(x0, system_comp, temperature, pressure),
            method='SLSQP',
            constraints=constraints,
            bounds=[(0, None) for _ in x0]
        )
        
        # Update phase amounts
        corrected_phases = {}
        for i, phase_name in enumerate(result['phases'].keys()):
            corrected_phases[phase_name] = result['phases'][phase_name].copy()
            corrected_phases[phase_name]['amount'] = max(1e-12, opt_result.x[i])
        
        return corrected_phases
    
    def _perform_comprehensive_stability_analysis(self, result: Dict, temperature: float, pressure: float) -> Dict:
        """Perform comprehensive phase stability analysis with convex hull reconstruction"""
        stability_results = {}
        
        # 1. Individual phase stability
        for phase_name, phase_data in result['phases'].items():
            stability_results[phase_name] = self._analyze_individual_phase_stability(
                phase_name, phase_data, temperature, pressure
            )
        
        # 2. Phase assemblage stability
        assemblage_stability = self._analyze_phase_assemblage_stability(result, temperature, pressure)
        stability_results['assemblage'] = assemblage_stability
        
        # 3. Alternative assemblage analysis
        alternative_assemblages = self._identify_alternative_assemblages(result, temperature, pressure)
        stability_results['alternatives'] = alternative_assemblages
        
        # 4. Convex hull analysis
        convex_hull_analysis = self._perform_convex_hull_analysis(result, temperature, pressure)
        stability_results['convex_hull'] = convex_hull_analysis
        
        return stability_results
    
    def _analyze_metastable_equilibria(self, result: Dict, temperature: float, pressure: float) -> Dict:
        """Analyze metastable equilibria and kinetic barriers"""
        metastability_analysis = {}
        
        # 1. Local vs global minimum analysis
        local_global_analysis = self._analyze_local_vs_global_minimum(result, temperature, pressure)
        metastability_analysis['local_global'] = local_global_analysis
        
        # 2. Kinetic barrier estimation
        kinetic_barriers = self._estimate_kinetic_barriers(result, temperature, pressure)
        metastability_analysis['kinetic_barriers'] = kinetic_barriers
        
        # 3. Nucleation barrier analysis
        nucleation_barriers = self._calculate_nucleation_barriers(result, temperature, pressure)
        metastability_analysis['nucleation_barriers'] = nucleation_barriers
        
        # 4. Reaction pathway analysis
        reaction_pathways = self._analyze_reaction_pathways(result, temperature, pressure)
        metastability_analysis['reaction_pathways'] = reaction_pathways
        
        return metastability_analysis
    
    def _calculate_advanced_solution_quality(self, result: Dict, validation_results: Dict, stability_analysis: Dict) -> Dict:
        """Calculate advanced solution quality metrics"""
        quality_metrics = {}
        
        # 1. Thermodynamic consistency score
        consistency_score = self._calculate_consistency_score(validation_results)
        quality_metrics['consistency_score'] = consistency_score
        
        # 2. Stability confidence
        stability_confidence = self._calculate_stability_confidence(stability_analysis)
        quality_metrics['stability_confidence'] = stability_confidence
        
        # 3. Convergence quality
        convergence_quality = self._assess_convergence_quality(result)
        quality_metrics['convergence_quality'] = convergence_quality
        
        # 4. Overall solution score
        overall_score = (consistency_score * 0.4 + 
                        stability_confidence * 0.4 + 
                        convergence_quality * 0.2)
        quality_metrics['overall_score'] = overall_score
        quality_metrics['quality_grade'] = self._assign_quality_grade(overall_score)
        
        return quality_metrics
    
    def _check_mass_balance(self, result: Dict) -> Dict[str, float]:
        """Advanced thermodynamic consistency validation with mass balance, charge balance, and chemical potential equilibrium"""
        import numpy as np
        from typing import Dict, List, Tuple
        
        validation_results = {}
        R = 8.314472  # J/(mol·K)
        T = result.get('temperature', 1273.15)
        P = result.get('pressure', 101325)
        
        # 1. Rigorous mass balance validation with system composition tracking
        mass_balance_errors = self._validate_mass_conservation(result)
        validation_results['mass_balance'] = mass_balance_errors
        
        # 2. Charge balance validation for ionic phases
        charge_balance_errors = self._validate_charge_neutrality(result)
        validation_results['charge_balance'] = charge_balance_errors
        
        # 3. Chemical potential equilibrium validation
        chemical_potential_errors = self._validate_chemical_potential_equilibrium(result, T, P)
        validation_results['chemical_potential'] = chemical_potential_errors
        
        # 4. Gibbs-Duhem relation validation
        gibbs_duhem_errors = self._validate_gibbs_duhem_consistency(result, T, P)
        validation_results['gibbs_duhem'] = gibbs_duhem_errors
        
        # 5. Phase rule compliance check (Gibbs phase rule: F = C - P + 2)
        phase_rule_validation = self._validate_phase_rule_compliance(result)
        validation_results['phase_rule'] = phase_rule_validation
        
        # 6. Thermodynamic stability validation
        stability_validation = self._validate_thermodynamic_stability(result, T, P)
        validation_results['stability'] = stability_validation
        
        # 7. Calculate overall validation metric
        total_error = self._calculate_overall_validation_metric(validation_results)
        validation_results['total_error'] = total_error
        validation_results['is_valid'] = total_error < 1e-6
        
        return validation_results
    
    def _validate_mass_conservation(self, result: Dict) -> Dict[str, float]:
        """Validate mass conservation using advanced stoichiometric matrix analysis"""
        errors = {}
        
        # Get system composition from result metadata
        system_composition = result.get('system_composition', {})
        if not system_composition:
            # Reconstruct from phases if not available
            system_composition = self._reconstruct_system_composition(result)
        
        # Calculate phase-specific element totals with molecular formulas
        phase_totals = {}
        for phase_name, phase_data in result['phases'].items():
            amount = phase_data['amount']  # moles of phase
            composition = phase_data.get('composition', {})
            
            # Get accurate molecular formula for this phase
            molecular_formula = self._get_phase_molecular_formula(phase_name, composition)
            
            for element, stoichiometry in molecular_formula.items():
                if element not in phase_totals:
                    phase_totals[element] = 0
                phase_totals[element] += amount * stoichiometry
        
        # Compare with system composition using relative error
        for element in system_composition.keys():
            system_total = system_composition[element]
            phase_total = phase_totals.get(element, 0)
            
            if system_total > 1e-12:  # Avoid division by zero
                relative_error = abs(phase_total - system_total) / system_total
            else:
                relative_error = abs(phase_total - system_total)
            
            errors[element] = relative_error
        
        return errors
    
    def _validate_charge_neutrality(self, result: Dict) -> Dict[str, float]:
        """Validate charge neutrality for ionic phases using advanced electrostatic balance"""
        charge_errors = {}
        
        for phase_name, phase_data in result['phases'].items():
            # Skip non-ionic phases
            if not self._is_ionic_phase(phase_name):
                continue
            
            amount = phase_data['amount']
            composition = phase_data.get('composition', {})
            
            # Calculate net charge using oxidation states and site occupancies
            net_charge = 0
            for species, mole_fraction in composition.items():
                oxidation_state = self._get_oxidation_state(species, phase_name)
                site_multiplicity = self._get_site_multiplicity(species, phase_name)
                net_charge += mole_fraction * oxidation_state * site_multiplicity
            
            # Charge balance error (should be zero for electroneutral phases)
            charge_errors[phase_name] = abs(net_charge * amount)
        
        return charge_errors
    
    def _validate_chemical_potential_equilibrium(self, result: Dict, temperature: float, pressure: float) -> Dict[str, float]:
        """Validate chemical potential equilibrium using rigorous thermodynamic analysis"""
        import numpy as np
        
        chemical_potential_errors = {}
        R = 8.314472
        
        # Get all unique components across phases
        all_components = set()
        for phase_data in result['phases'].values():
            all_components.update(phase_data.get('composition', {}).keys())
        
        for component in all_components:
            chemical_potentials = []
            phase_names = []
            
            # Calculate chemical potential in each phase containing this component
            for phase_name, phase_data in result['phases'].items():
                composition = phase_data.get('composition', {})
                if component in composition:
                    # Chemical potential = standard chemical potential + RT ln(activity)
                    activity = self._calculate_component_activity(component, phase_name, composition, temperature, pressure)
                    standard_potential = self._get_standard_chemical_potential(component, phase_name, temperature, pressure)
                    
                    if activity > 1e-12:  # Avoid log(0)
                        chemical_potential = standard_potential + R * temperature * np.log(activity)
                    else:
                        chemical_potential = standard_potential - R * temperature * 50  # Very negative for trace amounts
                    
                    chemical_potentials.append(chemical_potential)
                    phase_names.append(phase_name)
            
            # Check equilibrium: all chemical potentials should be equal
            if len(chemical_potentials) > 1:
                mu_avg = np.mean(chemical_potentials)
                max_deviation = max(abs(mu - mu_avg) for mu in chemical_potentials)
                chemical_potential_errors[component] = max_deviation / (R * temperature)  # Dimensionless error
        
        return chemical_potential_errors
    
    def _validate_gibbs_duhem_consistency(self, result: Dict, temperature: float, pressure: float) -> Dict[str, float]:
        """Validate Gibbs-Duhem relation for phase composition consistency"""
        gibbs_duhem_errors = {}
        
        for phase_name, phase_data in result['phases'].items():
            composition = phase_data.get('composition', {})
            
            # Gibbs-Duhem relation: Σ x_i d(ln γ_i) = 0 at constant T, P
            # Approximate using finite differences
            gibbs_duhem_sum = 0
            total_mole_fraction = sum(composition.values())
            
            if total_mole_fraction > 0:
                for component, x_i in composition.items():
                    if x_i > 1e-6:  # Skip trace components
                        # Calculate activity coefficient and its derivative
                        gamma_i = self._calculate_activity_coefficient(component, phase_name, composition, temperature, pressure)
                        
                        # Approximate derivative using small perturbation
                        dx = 0.001
                        perturbed_composition = composition.copy()
                        perturbed_composition[component] = min(x_i + dx, 1.0)
                        
                        # Renormalize
                        total_perturbed = sum(perturbed_composition.values())
                        for comp in perturbed_composition:
                            perturbed_composition[comp] /= total_perturbed
                        
                        gamma_i_perturbed = self._calculate_activity_coefficient(component, phase_name, perturbed_composition, temperature, pressure)
                        
                        if gamma_i > 1e-12 and gamma_i_perturbed > 1e-12:
                            d_ln_gamma = np.log(gamma_i_perturbed) - np.log(gamma_i)
                            gibbs_duhem_sum += (x_i / total_mole_fraction) * d_ln_gamma / dx
                
                gibbs_duhem_errors[phase_name] = abs(gibbs_duhem_sum)
        
        return gibbs_duhem_errors
    
    def _validate_phase_rule_compliance(self, result: Dict) -> Dict[str, any]:
        """Validate Gibbs phase rule compliance: F = C - P + 2"""
        C = len(set().union(*[phase_data.get('composition', {}).keys() for phase_data in result['phases'].values()]))  # Components
        P = len([phase for phase, data in result['phases'].items() if data.get('amount', 0) > 1e-12])  # Phases with significant amounts
        
        # Degrees of freedom
        F_theoretical = C - P + 2  # +2 for temperature and pressure
        
        # In equilibrium calculation, T and P are specified, so effective F = C - P
        F_effective = C - P
        
        return {
            'components': C,
            'phases': P,
            'degrees_of_freedom_theoretical': F_theoretical,
            'degrees_of_freedom_effective': F_effective,
            'is_compliant': F_effective >= 0,
            'violation_magnitude': max(0, -F_effective)
        }
    
    def _validate_thermodynamic_stability(self, result: Dict, temperature: float, pressure: float) -> Dict[str, float]:
        """Validate thermodynamic stability using convex hull analysis"""
        stability_errors = {}
        
        for phase_name, phase_data in result['phases'].items():
            amount = phase_data.get('amount', 0)
            if amount < 1e-12:  # Skip trace phases
                continue
            
            # Calculate Gibbs free energy of formation
            composition = phase_data.get('composition', {})
            G_formation = self._calculate_gibbs_formation_energy(phase_name, composition, temperature, pressure)
            
            # Check against convex hull of stable phases
            is_stable, driving_force = self._check_convex_hull_stability(phase_name, composition, temperature, pressure)
            
            if not is_stable:
                stability_errors[phase_name] = abs(driving_force)  # J/mol below convex hull
            else:
                stability_errors[phase_name] = 0
        
        return stability_errors
    
    def _calculate_overall_validation_metric(self, validation_results: Dict) -> float:
        """Calculate weighted overall validation metric"""
        weights = {
            'mass_balance': 1000,  # Very important
            'charge_balance': 100,
            'chemical_potential': 10,
            'gibbs_duhem': 1,
            'stability': 0.1
        }
        
        total_weighted_error = 0
        total_weight = 0
        
        for category, results in validation_results.items():
            if category in weights and isinstance(results, dict):
                weight = weights[category]
                category_error = sum(abs(error) for error in results.values() if isinstance(error, (int, float)))
                total_weighted_error += weight * category_error
                total_weight += weight
        
        return total_weighted_error / max(total_weight, 1)
    
    def _fallback_equilibrium(self, system_composition: Dict[str, float], 
                            temperature: float, pressure: float,
                            phases: List[str]) -> Dict:
        """Fallback equilibrium calculation using simplified approach"""
        result = {
            'temperature': temperature,
            'pressure': pressure,
            'phases': {},
            'total_gibbs': 0,
            'fallback_used': True,
            'method': 'simplified_equilibrium'
        }
        
        # Distribute phases based on thermodynamic stability
        stable_phases = []
        for phase in phases:
            if phase in self.database:
                g_phase = self.calculate_gibbs_energy(phase, temperature, pressure)
                stable_phases.append((phase, g_phase))
        
        # Sort by stability (lowest Gibbs energy first)
        stable_phases.sort(key=lambda x: x[1])
        
        # Simple distribution (this is very simplified)
        total_amount = sum(system_composition.values())
        n_stable = min(3, len(stable_phases))  # Limit to 3 most stable phases
        
        for i, (phase, g_energy) in enumerate(stable_phases[:n_stable]):
            amount = total_amount / n_stable
            result['phases'][phase] = {
                'amount': amount,
                'gibbs_energy': g_energy
            }
            result['total_gibbs'] += amount * g_energy
        
        return result
    
    def _plagioclase_stoichiometry_constraint(self, composition: Dict[str, float]) -> float:
        """Plagioclase feldspar stoichiometric constraints"""
        # Plagioclase: (Ca,Na)(Al,Si)4O8 solid solution
        # Constraint: Ca + Na = 1 (M site), Al + Si = 4 (T sites), Al = Ca + Na (charge balance)
        
        # Get end-member fractions
        X_ab = composition.get('albite', 0)    # NaAlSi3O8
        X_an = composition.get('anorthite', 0)  # CaAl2Si2O8
        
        # Stoichiometric constraints
        # 1. Site occupancy constraint: X_ab + X_an = 1
        site_constraint = X_ab + X_an - 1.0
        
        # 2. Al/Si ordering constraint for T sites
        # Albite: 1 Al in T1, 3 Si in T2
        # Anorthite: 2 Al in T1, 2 Si in T2
        # Average Al content should match Ca + Na content
        avg_Al = X_ab * 1.0 + X_an * 2.0
        avg_Ca_Na = X_ab * 1.0 + X_an * 1.0
        al_constraint = avg_Al - avg_Ca_Na
        
        # Return combined constraint (squared for penalty method)
        return site_constraint**2 + al_constraint**2
    
    def _olivine_stoichiometry_constraint(self, composition: Dict[str, float]) -> float:
        """Olivine stoichiometric constraints"""
        # Olivine: (Mg,Fe)2SiO4 solid solution
        # Constraint: Mg + Fe = 2, Si = 1
        
        X_fo = composition.get('forsterite', 0)  # Mg2SiO4
        X_fa = composition.get('fayalite', 0)    # Fe2SiO4
        
        # Site occupancy constraint: X_fo + X_fa = 1
        site_constraint = X_fo + X_fa - 1.0
        
        # M1/M2 site ordering (can be extended for ordered olivine)
        # For now, assume random distribution
        ordering_constraint = 0.0
        
        return site_constraint**2 + ordering_constraint**2
    
    def _garnet_stoichiometry_constraint(self, composition: Dict[str, float]) -> float:
        """Garnet stoichiometric constraints"""
        # Garnet: X3Y2Si3O12 where X = Ca,Fe,Mg,Mn and Y = Al,Fe3+,Cr
        # Constraints: X site = 3, Y site = 2, Si = 3
        
        X_alm = composition.get('almandine', 0)  # Fe3Al2Si3O12
        X_pyr = composition.get('pyrope', 0)     # Mg3Al2Si3O12
        X_grs = composition.get('grossular', 0)  # Ca3Al2Si3O12
        X_sps = composition.get('spessartine', 0) if 'spessartine' in composition else 0  # Mn3Al2Si3O12
        
        # X site constraint (dodecahedral)
        X_site_total = X_alm * 3 + X_pyr * 3 + X_grs * 3 + X_sps * 3
        X_site_constraint = X_site_total / 3.0 - 1.0  # Normalize to 1
        
        # Y site constraint (octahedral) - assuming all Al for simplicity
        Y_site_total = X_alm * 2 + X_pyr * 2 + X_grs * 2 + X_sps * 2
        Y_site_constraint = Y_site_total / 2.0 - 1.0  # Normalize to 1
        
        # Composition constraint
        comp_constraint = X_alm + X_pyr + X_grs + X_sps - 1.0
        
        return X_site_constraint**2 + Y_site_constraint**2 + comp_constraint**2
    
    def _pyroxene_stoichiometry_constraint(self, composition: Dict[str, float]) -> float:
        """Pyroxene stoichiometric constraints"""
        # Pyroxene: (Ca,Mg,Fe)SiO3 solid solution
        # M1 and M2 sites with different cation preferences
        
        X_di = composition.get('diopside', 0)   # CaMgSi2O6
        X_en = composition.get('enstatite', 0)  # MgSiO3
        X_fs = composition.get('ferrosilite', 0) if 'ferrosilite' in composition else 0  # FeSiO3
        
        # Site occupancy constraints
        # M1 site: prefers smaller cations (Mg, Fe)
        # M2 site: prefers larger cations (Ca)
        
        M1_occupancy = X_di * 1.0 + X_en * 1.0 + X_fs * 1.0  # Mg, Fe
        M2_occupancy = X_di * 1.0  # Ca
        
        # Total site constraint
        total_M_sites = M1_occupancy + M2_occupancy
        site_constraint = total_M_sites - 1.0
        
        # Composition constraint
        comp_constraint = X_di + X_en + X_fs - 1.0
        
        return site_constraint**2 + comp_constraint**2
    
    def _spinel_stoichiometry_constraint(self, composition: Dict[str, float]) -> float:
        """Spinel group stoichiometric constraints"""
        # Spinel: AB2O4 where A = tetrahedral site, B = octahedral site
        # Complex ordering between normal and inverse spinel structures
        
        # For magnetite-spinel solid solution
        # Normal spinel: A2+B2³+O4
        # Inverse spinel: B3+(A2+B3+)O4
        
        total_tetrahedryl = 0
        total_octahedral = 0
        
        for component, mole_frac in composition.items():
            if 'spinel' in component.lower() or 'magnetite' in component.lower():
                # Simplified constraint for spinel structure
                total_tetrahedryl += mole_frac * 1.0  # A site
                total_octahedral += mole_frac * 2.0   # B site
        
        # Site occupancy constraints
        A_site_constraint = total_tetrahedryl - 1.0
        B_site_constraint = total_octahedral / 2.0 - 1.0
        
        return A_site_constraint**2 + B_site_constraint**2
    
    def _amphibole_stoichiometry_constraint(self, composition: Dict[str, float]) -> Dict[str, any]:
        """Advanced amphibole stoichiometric constraints with rigorous crystallographic site analysis"""
        import numpy as np
        from typing import Dict, List, Tuple
        
        # Amphibole general formula: A(0-1)B2C5T8O22(OH,F,Cl)2
        # where A = Na, K, Ca, Pb, Li
        #       B = Na, Li, Ca, Mn, Fe2+, Mg, Zn
        #       C = Mg, Fe2+, Mn, Al, Fe3+, Ti, Zn, Cr3+, V3+
        #       T = Si, Al, Fe3+, Ti
        
        # Get advanced site occupancy parameters
        site_parameters = self._get_amphibole_site_parameters()
        
        # Parse composition into element components
        element_composition = self._parse_amphibole_composition(composition)
        
        # 1. Site-specific constraint calculations
        T_site_constraints = self._calculate_T_site_constraints(element_composition, site_parameters)
        C_site_constraints = self._calculate_C_site_constraints(element_composition, site_parameters)
        B_site_constraints = self._calculate_B_site_constraints(element_composition, site_parameters)
        A_site_constraints = self._calculate_A_site_constraints(element_composition, site_parameters)
        
        # 2. Charge balance constraint with anion site flexibility
        charge_balance_constraint = self._calculate_amphibole_charge_balance(
            element_composition, T_site_constraints, C_site_constraints, 
            B_site_constraints, A_site_constraints
        )
        
        # 3. Crystal chemical constraints based on ionic radii and coordination
        crystal_chemical_constraints = self._calculate_amphibole_crystal_chemical_constraints(
            element_composition, site_parameters
        )
        
        # 4. Order-disorder constraints for Al-Si in T sites
        order_disorder_constraints = self._calculate_amphibole_order_disorder_constraints(
            element_composition, site_parameters
        )
        
        # 5. Compositional limits from experimental studies
        compositional_limits = self._apply_amphibole_compositional_limits(element_composition)
        
        # 6. Calculate total constraint violation
        total_violation = self._calculate_total_amphibole_constraint_violation(
            T_site_constraints, C_site_constraints, B_site_constraints, A_site_constraints,
            charge_balance_constraint, crystal_chemical_constraints, order_disorder_constraints,
            compositional_limits
        )
        
        return {
            'total_violation': total_violation,
            'T_site_constraints': T_site_constraints,
            'C_site_constraints': C_site_constraints,
            'B_site_constraints': B_site_constraints,
            'A_site_constraints': A_site_constraints,
            'charge_balance': charge_balance_constraint,
            'crystal_chemical': crystal_chemical_constraints,
            'order_disorder': order_disorder_constraints,
            'compositional_limits': compositional_limits,
            'site_occupancies': self._calculate_optimized_site_occupancies(element_composition, site_parameters),
            'structural_formula': self._generate_structural_formula(element_composition),
            'amphibole_classification': self._classify_amphibole_type(element_composition)
        }
    
