    def _is_solid_solution_phase(self, phase: str) -> bool:
        """Check if phase is a solid solution with variable composition"""
        solid_solution_phases = {
            'olivine', 'pyroxene', 'clinopyroxene', 'orthopyroxene',
            'plagioclase', 'alkali_feldspar', 'garnet', 'amphibole',
            'biotite', 'muscovite', 'chlorite', 'spinel'
        }
        
        mineral_database = self._get_comprehensive_mineral_database()
        
        # Check if phase has solid solution designation
        if phase in mineral_database:
            return mineral_database[phase].get('solid_solution') is not None
        
        # Check if phase name contains solid solution indicators
        for ss_type in solid_solution_phases:
            if ss_type in phase.lower():
                return True
        
        return False
    
    def _calculate_solid_solution_element_count(self, phase: str, element: str, composition: Dict[str, float], mineral_database: Dict) -> float:
        """Calculate element count for solid solution phases with variable composition"""
        
        # Get end-member compositions
        end_members = self._get_solid_solution_end_members(phase, mineral_database)
        
        if not end_members:
            return self._get_fallback_element_count(phase, element)
        
        # Calculate weighted average element count
        total_element_count = 0.0
        total_weight = 0.0
        
        for end_member, weight in composition.items():
            if end_member in end_members and weight > 1e-12:
                em_element_count = end_members[end_member].get('elements', {}).get(element, 0.0)
                total_element_count += weight * em_element_count
                total_weight += weight
        
        if total_weight > 1e-12:
            return total_element_count / total_weight
        else:
            # Fallback to first end-member
            first_em = list(end_members.values())[0]
            return first_em.get('elements', {}).get(element, 0.0)
    
    def _calculate_structural_element_count(self, phase: str, element: str, mineral_data: Dict) -> float:
        """Calculate element count considering structural sites and occupancies"""
        
        # Direct element count from stoichiometry
        direct_count = mineral_data.get('elements', {}).get(element, 0.0)
        
        # Site-specific count (more accurate for complex structures)
        site_count = 0.0
        sites_data = mineral_data.get('sites', {})
        
        for site_name, site_composition in sites_data.items():
            if element in site_composition:
                site_count += site_composition[element]
        
        # Use site-specific count if available, otherwise use direct count
        if site_count > 0:
            return site_count
        else:
            return direct_count
    
    def _format_equilibrium_result(self, amounts: np.ndarray, phases: List[str], 
                                  temperature: float, pressure: float) -> Dict:
        """Format equilibrium calculation results with advanced thermodynamic properties"""
        result = {
            'temperature': temperature,
            'pressure': pressure,
            'phases': {},
            'total_gibbs': 0,
            'total_enthalpy': 0,
            'total_entropy': 0,
            'total_volume': 0,
            'heat_capacity': 0,
            'compressibility': 0,
            'thermal_expansion': 0,
            'phase_assemblage_entropy': 0,
            'variance': 0,
            'stability_index': 0
        }
        
        total_moles = np.sum(amounts)
        phase_data_list = []
        
        idx = 0
        for phase in phases:
            if phase in self.database and amounts[idx] > 1e-10:
                amount = amounts[idx]
                mole_fraction = amount / total_moles if total_moles > 0 else 0
                
                # Calculate comprehensive thermodynamic properties
                g_phase = self.calculate_gibbs_energy(phase, temperature, pressure)
                h_phase = self._calculate_enthalpy(phase, temperature, pressure)
                s_phase = self._calculate_entropy(phase, temperature, pressure)
                v_phase = self._calculate_molar_volume(phase, temperature, pressure)
                cp_phase = self._calculate_heat_capacity(phase, temperature, pressure)
                
                # Activity and chemical potential
                activity = self._calculate_activity(phase, temperature, pressure)
                chemical_potential = g_phase + 8.314 * temperature * np.log(max(activity, 1e-10))
                
                # Phase stability indicators
                stability_matrix = self._calculate_stability_matrix(phase, temperature, pressure)
                eigenvalues = np.linalg.eigvals(stability_matrix) if stability_matrix.size > 0 else [0]
                phase_stability = min(eigenvalues)
                
                phase_info = {
                    'amount': amount,
                    'mole_fraction': mole_fraction,
                    'gibbs_energy': g_phase,
                    'enthalpy': h_phase,
                    'entropy': s_phase,
                    'molar_volume': v_phase,
                    'heat_capacity': cp_phase,
                    'activity': activity,
                    'chemical_potential': chemical_potential,
                    'stability_index': phase_stability,
                    'density': self._calculate_density(phase, temperature, pressure),
                    'bulk_modulus': self._calculate_bulk_modulus(phase, temperature, pressure),
                    'thermal_expansion_coeff': self._calculate_thermal_expansion_coeff(phase, temperature, pressure)
                }
                
                result['phases'][phase] = phase_info
                phase_data_list.append((amount, phase_info))
                
                # Accumulate extensive properties
                result['total_gibbs'] += amount * g_phase
                result['total_enthalpy'] += amount * h_phase
                result['total_entropy'] += amount * s_phase
                result['total_volume'] += amount * v_phase
                result['heat_capacity'] += amount * cp_phase
                
            idx += 1
        
        # Calculate system-wide intensive properties
        if total_moles > 0:
            result['molar_gibbs'] = result['total_gibbs'] / total_moles
            result['molar_enthalpy'] = result['total_enthalpy'] / total_moles
            result['molar_entropy'] = result['total_entropy'] / total_moles
            result['molar_volume'] = result['total_volume'] / total_moles
            result['molar_heat_capacity'] = result['heat_capacity'] / total_moles
            
            # Phase assemblage entropy (configurational entropy)
            for amount, phase_info in phase_data_list:
                x_i = amount / total_moles
                if x_i > 1e-10:
                    result['phase_assemblage_entropy'] -= 8.314 * x_i * np.log(x_i)
            
            # Calculate variance using Gibbs phase rule: F = C - P + 2
            components = len(set().union(*[self.database[phase].get('elements', {}).keys() 
                                         for phase in result['phases'].keys()]))
            result['variance'] = components - len(result['phases']) + 2
            
            # Overall stability index (minimum eigenvalue of Hessian)
            result['stability_index'] = min([phase_info['stability_index'] 
                                           for phase_info in result['phases'].values()])
        
        return result
    
    def _calculate_enthalpy(self, phase: str, temperature: float, pressure: float) -> float:
        """Calculate molar enthalpy of phase"""
        if phase not in self.database:
            return 0.0
        
        data = self.database[phase]
        h_298 = data.get('delta_h_298', 0.0) * 1000  # Convert kJ to J
        cp_coeffs = data.get('cp_coeffs', [0, 0, 0, 0])
        
        # Integrate Cp from 298K to T
        if len(cp_coeffs) >= 4:
            a, b, c, d = cp_coeffs[:4]
            dt = temperature - 298.15
            h_integral = (a * dt + 
                         b/2 * (temperature**2 - 298.15**2) + 
                         c/3 * (temperature**3 - 298.15**3) + 
                         d * (1/temperature - 1/298.15))
        else:
            h_integral = 0
        
        # Pressure correction (assuming ideal gas approximation for simplicity)
        pv_work = 8.314 * temperature * np.log(pressure / 1.0) if pressure > 0 else 0
        
        return h_298 + h_integral + pv_work
    
    def _calculate_entropy(self, phase: str, temperature: float, pressure: float) -> float:
        """Calculate molar entropy of phase"""
        if phase not in self.database:
            return 0.0
        
        data = self.database[phase]
        s_298 = data.get('s_298', 0.0)  # J/mol/K
        cp_coeffs = data.get('cp_coeffs', [0, 0, 0, 0])
        
        # Integrate Cp/T from 298K to T
        if len(cp_coeffs) >= 4:
            a, b, c, d = cp_coeffs[:4]
            s_integral = (a * np.log(temperature / 298.15) + 
                         b * (temperature - 298.15) + 
                         c/2 * (temperature**2 - 298.15**2) + 
                         d/2 * (1/temperature**2 - 1/298.15**2))
        else:
            s_integral = 0
        
        # Pressure correction
        s_pressure = -8.314 * np.log(pressure / 1.0) if pressure > 0 else 0
        
        return s_298 + s_integral + s_pressure
    
    def _calculate_molar_volume(self, phase: str, temperature: float, pressure: float) -> float:
        """Calculate molar volume with thermal expansion and compressibility"""
        if phase not in self.database:
            return 0.0
        
        data = self.database[phase]
        v_298 = data.get('v_298', 0.0) * 1e-5  # Convert J/bar to m³/mol
        alpha = data.get('alpha', 3e-5)  # Thermal expansion coefficient
        beta = data.get('beta', 1e-5)   # Compressibility coefficient
        
        # Volume correction for temperature and pressure
        v_thermal = v_298 * (1 + alpha * (temperature - 298.15))
        v_corrected = v_thermal * (1 - beta * (pressure - 1.0))
        
        return max(v_corrected, 1e-6)  # Ensure positive volume
    
    def _calculate_heat_capacity(self, phase: str, temperature: float, pressure: float) -> float:
        """Calculate molar heat capacity"""
        if phase not in self.database:
            return 0.0
        
        data = self.database[phase]
        cp_coeffs = data.get('cp_coeffs', [0, 0, 0, 0])
        
        if len(cp_coeffs) >= 4:
            a, b, c, d = cp_coeffs[:4]
            cp = a + b * temperature + c * temperature**2 + d / temperature**2
            return max(cp, 0.0)  # Ensure positive heat capacity
        
        return 25.0  # Default value for solids (Dulong-Petit law approximation)
    
    def _calculate_activity(self, phase: str, temperature: float, pressure: float) -> float:
        """Calculate activity of phase (simplified for pure phases)"""
        if phase not in self.database:
            return 1.0
        
        # For pure phases, activity approaches 1.0
        # For solutions, this would involve activity models
        data = self.database[phase]
        
        # Simple activity correction based on deviation from standard state
        g_deviation = (self.calculate_gibbs_energy(phase, temperature, pressure) - 
                      self.calculate_gibbs_energy(phase, 298.15, 1.0))
        
        activity = np.exp(-g_deviation / (8.314 * temperature))
        return max(min(activity, 100.0), 0.01)  # Reasonable bounds
    
    def _calculate_stability_matrix(self, phase: str, temperature: float, pressure: float) -> np.ndarray:
        """Advanced thermodynamic stability matrix calculation with rigorous Hessian analysis and phase equilibrium theory"""
        
        if phase not in self.database:
            return np.array([[0]])
        
        try:
            stability_analysis = {
                'hessian_matrix': {},
                'eigenvalue_analysis': {},
                'stability_criteria': {},
                'phase_boundary_detection': {},
                'critical_point_analysis': {},
                'spinodal_decomposition': {},
                'metastability_assessment': {},
                'thermodynamic_consistency': {},
                'numerical_precision': {},
                'uncertainty_quantification': {}
            }
            
            # Initialize advanced thermodynamic framework
            phase_data = self.database[phase]
            R = 8.314472  # J/(mol·K)
            
            # Extract phase composition and end-member analysis
            composition_variables = self._extract_composition_variables(phase_data)
            n_components = len(composition_variables)
            
            if n_components == 0:
                return np.array([[1.0]])
            
            # Calculate full Hessian matrix of Gibbs energy
            hessian_matrix = self._calculate_gibbs_hessian_matrix(
                phase, temperature, pressure, composition_variables
            )
            stability_analysis['hessian_matrix'] = hessian_matrix
            
            # Advanced eigenvalue stability analysis
            eigenvalues, eigenvectors = np.linalg.eigh(hessian_matrix)
            stability_analysis['eigenvalue_analysis'] = {
                'eigenvalues': eigenvalues.tolist(),
                'eigenvectors': eigenvectors.tolist(),
                'condition_number': np.linalg.cond(hessian_matrix),
                'determinant': np.linalg.det(hessian_matrix),
                'trace': np.trace(hessian_matrix)
            }
            
            # Stability criteria assessment
            stability_analysis['stability_criteria'] = self._assess_stability_criteria(
                eigenvalues, temperature, pressure
            )
            
            # Phase boundary and critical point detection
            stability_analysis['phase_boundary_detection'] = self._detect_phase_boundaries(
                hessian_matrix, temperature, pressure, phase
            )
            
            # Spinodal decomposition analysis
            stability_analysis['spinodal_decomposition'] = self._analyze_spinodal_decomposition(
                hessian_matrix, eigenvalues, eigenvectors, temperature
            )
            
            # Metastability assessment using classical nucleation theory
            stability_analysis['metastability_assessment'] = self._assess_metastability(
                phase, temperature, pressure, eigenvalues
            )
            
            # Enhanced numerical precision and convergence analysis
            stability_analysis['numerical_precision'] = self._analyze_numerical_precision(
                hessian_matrix, temperature, pressure
            )
            
            # Uncertainty quantification in stability calculations
            stability_analysis['uncertainty_quantification'] = self._quantify_stability_uncertainties(
                hessian_matrix, phase, temperature, pressure
            )
            
            # Apply thermodynamic consistency checks
            consistency_results = self._verify_thermodynamic_consistency(
                hessian_matrix, phase, temperature, pressure
            )
            stability_analysis['thermodynamic_consistency'] = consistency_results
            
            # Store comprehensive analysis results
            if not hasattr(self, 'stability_analysis_cache'):
                self.stability_analysis_cache = {}
            
            cache_key = f"{phase}_{temperature:.2f}_{pressure:.2f}"
            self.stability_analysis_cache[cache_key] = stability_analysis
            
            return hessian_matrix
            
        except Exception as e:
            print(f"Error in advanced stability matrix calculation: {e}")
            return self._fallback_stability_matrix(phase, temperature, pressure)
    
    def _extract_composition_variables(self, phase_data: Dict) -> List[str]:
        """Extract composition variables for multi-component stability analysis"""
        try:
            composition_vars = []
            
            # Extract major element composition variables
            major_elements = ['SiO2', 'Al2O3', 'FeO', 'MgO', 'CaO', 'Na2O', 'K2O', 'TiO2']
            for element in major_elements:
                if element in phase_data:
                    composition_vars.append(element)
            
            # Include trace elements if significant
            trace_elements = ['Cr2O3', 'NiO', 'MnO', 'P2O5']
            for element in trace_elements:
                if element in phase_data and phase_data[element] > 0.01:
                    composition_vars.append(element)
            
            # Include volatile components
            volatiles = ['H2O', 'CO2', 'SO2', 'F', 'Cl']
            for volatile in volatiles:
                if volatile in phase_data:
                    composition_vars.append(volatile)
            
            return composition_vars
            
        except Exception as e:
            print(f"Error extracting composition variables: {e}")
            return ['SiO2', 'Al2O3', 'FeO', 'MgO']
    
    def _calculate_gibbs_hessian_matrix(self, phase: str, temperature: float, 
                                      pressure: float, composition_vars: List[str]) -> np.ndarray:
        """Calculate rigorous Hessian matrix of Gibbs energy with respect to composition variables"""
        try:
            n_vars = len(composition_vars)
            hessian = np.zeros((n_vars, n_vars))
            
            # Adaptive step size for numerical differentiation
            base_step = 1e-6
            relative_steps = {}
            
            for i, var in enumerate(composition_vars):
                phase_data = self.database[phase]
                current_value = phase_data.get(var, 0.0)
                relative_steps[var] = max(base_step, abs(current_value) * 1e-6)
            
            # Calculate second partial derivatives using Richardson extrapolation
            for i, var_i in enumerate(composition_vars):
                for j, var_j in enumerate(composition_vars):
                    
                    if i <= j:  # Symmetric matrix
                        step_i = relative_steps[var_i]
                        step_j = relative_steps[var_j]
                        
                        # Richardson extrapolation for enhanced accuracy
                        h1_value = self._calculate_mixed_partial_derivative(
                            phase, temperature, pressure, var_i, var_j, step_i, step_j
                        )
                        
                        h2_value = self._calculate_mixed_partial_derivative(
                            phase, temperature, pressure, var_i, var_j, step_i/2, step_j/2
                        )
                        
                        # Richardson extrapolation formula
                        richardson_value = (4 * h2_value - h1_value) / 3
                        
                        hessian[i, j] = richardson_value
                        hessian[j, i] = richardson_value  # Symmetry
            
            # Apply regularization for numerical stability
            regularization_factor = 1e-12
            hessian += regularization_factor * np.eye(n_vars)
            
            return hessian
            
        except Exception as e:
            print(f"Error calculating Gibbs Hessian matrix: {e}")
            return np.eye(len(composition_vars)) * 1e-6
    
    def _calculate_mixed_partial_derivative(self, phase: str, temperature: float, pressure: float,
                                          var_i: str, var_j: str, step_i: float, step_j: float) -> float:
        """Calculate mixed partial derivative d²G/dxi·dxj using finite differences"""
        try:
            # Central difference scheme for mixed derivatives
            original_data = self.database[phase].copy()
            
            # G(xi+h, xj+h)
            self.database[phase][var_i] = original_data.get(var_i, 0.0) + step_i
            self.database[phase][var_j] = original_data.get(var_j, 0.0) + step_j
            g_pp = self.calculate_gibbs_energy(phase, temperature, pressure)
            
            # G(xi+h, xj-h)
            self.database[phase][var_j] = original_data.get(var_j, 0.0) - step_j
            g_pm = self.calculate_gibbs_energy(phase, temperature, pressure)
            
            # G(xi-h, xj+h)
            self.database[phase][var_i] = original_data.get(var_i, 0.0) - step_i
            self.database[phase][var_j] = original_data.get(var_j, 0.0) + step_j
            g_mp = self.calculate_gibbs_energy(phase, temperature, pressure)
            
            # G(xi-h, xj-h)
            self.database[phase][var_j] = original_data.get(var_j, 0.0) - step_j
            g_mm = self.calculate_gibbs_energy(phase, temperature, pressure)
            
            # Restore original data
            self.database[phase] = original_data
            
            # Central difference formula for mixed derivative
            mixed_derivative = (g_pp - g_pm - g_mp + g_mm) / (4 * step_i * step_j)
            
            return mixed_derivative
            
        except Exception as e:
            print(f"Error calculating mixed partial derivative: {e}")
            return 0.0
    
    def _assess_stability_criteria(self, eigenvalues: np.ndarray, temperature: float, 
                                 pressure: float) -> Dict:
        """Assess thermodynamic stability criteria based on eigenvalue analysis"""
        try:
            stability_assessment = {
                'global_stability': 'stable',
                'local_stability': 'stable',
                'mechanical_stability': 'stable',
                'thermal_stability': 'stable',
                'stability_margin': 0.0,
                'instability_modes': [],
                'critical_temperature': None,
                'stability_confidence': 1.0
            }
            
            # Global stability: all eigenvalues positive
            min_eigenvalue = np.min(eigenvalues)
            if min_eigenvalue <= 0:
                stability_assessment['global_stability'] = 'unstable'
                stability_assessment['stability_margin'] = abs(min_eigenvalue)
                
                # Identify instability modes
                for i, eigval in enumerate(eigenvalues):
                    if eigval <= 0:
                        stability_assessment['instability_modes'].append({
                            'mode_index': i,
                            'eigenvalue': eigval,
                            'instability_type': 'mechanical' if eigval < -1e-6 else 'marginal'
                        })
            
            # Local stability assessment
            local_stability_threshold = 1e-8
            if min_eigenvalue < local_stability_threshold:
                stability_assessment['local_stability'] = 'metastable'
            
            # Thermal stability assessment
            thermal_eigenvalues = eigenvalues[eigenvalues > 0]
            if len(thermal_eigenvalues) > 0:
                thermal_stability_indicator = np.mean(thermal_eigenvalues) * temperature
                if thermal_stability_indicator < 1000:  # J/mol threshold
                    stability_assessment['thermal_stability'] = 'thermally_unstable'
            
            # Estimate critical temperature using Landau theory
            if min_eigenvalue < 0:
                stability_assessment['critical_temperature'] = self._estimate_critical_temperature(
                    eigenvalues, temperature, pressure
                )
            
            # Stability confidence based on eigenvalue distribution
            eigenvalue_ratio = np.max(eigenvalues) / (abs(np.min(eigenvalues)) + 1e-12)
            stability_assessment['stability_confidence'] = min(1.0, 1.0 / (1.0 + eigenvalue_ratio))
            
            return stability_assessment
            
        except Exception as e:
            print(f"Error assessing stability criteria: {e}")
            return {'global_stability': 'unknown', 'local_stability': 'unknown'}
    
    def _detect_phase_boundaries(self, hessian_matrix: np.ndarray, temperature: float, 
                               pressure: float, phase: str) -> Dict:
        """Detect phase boundaries and transition points using stability analysis"""
        try:
            boundary_detection = {
                'phase_transitions': [],
                'spinodal_points': [],
                'critical_points': [],
                'metastable_regions': [],
                'boundary_confidence': 0.0
            }
            
            # Analyze eigenvalue behavior near boundaries
            eigenvalues, eigenvectors = np.linalg.eigh(hessian_matrix)
            
            # Detect spinodal points (where stability matrix becomes singular)
            min_eigenvalue = np.min(eigenvalues)
            if abs(min_eigenvalue) < 1e-6:
                boundary_detection['spinodal_points'].append({
                    'temperature': temperature,
                    'pressure': pressure,
                    'eigenvalue': min_eigenvalue,
                    'transition_type': 'spinodal_decomposition'
                })
            
            # Search for critical points using temperature derivatives
            temperature_range = np.linspace(temperature - 50, temperature + 50, 11)
            eigenvalue_derivatives = []
            
            for T in temperature_range:
                if T > 0:
                    temp_hessian = self._calculate_gibbs_hessian_matrix(
                        phase, T, pressure, self._extract_composition_variables(self.database[phase])
                    )
                    temp_eigenvalues = np.linalg.eigvals(temp_hessian)
                    eigenvalue_derivatives.append(np.min(temp_eigenvalues))
            
            # Detect zero crossings in eigenvalue temperature dependence
            for i in range(len(eigenvalue_derivatives) - 1):
                if eigenvalue_derivatives[i] * eigenvalue_derivatives[i + 1] < 0:
                    critical_temp = temperature_range[i] + (temperature_range[i + 1] - temperature_range[i]) * \
                                  abs(eigenvalue_derivatives[i]) / (abs(eigenvalue_derivatives[i]) + abs(eigenvalue_derivatives[i + 1]))
                    
                    boundary_detection['critical_points'].append({
                        'critical_temperature': critical_temp,
                        'pressure': pressure,
                        'transition_type': 'continuous_transition'
                    })
            
            # Assess boundary detection confidence
            eigenvalue_spread = np.std(eigenvalues)
            boundary_detection['boundary_confidence'] = min(1.0, eigenvalue_spread / (abs(min_eigenvalue) + 1e-12))
            
            return boundary_detection
            
        except Exception as e:
            print(f"Error detecting phase boundaries: {e}")
            return {'phase_transitions': [], 'boundary_confidence': 0.0}
    
    def _analyze_spinodal_decomposition(self, hessian_matrix: np.ndarray, eigenvalues: np.ndarray,
                                      eigenvectors: np.ndarray, temperature: float) -> Dict:
        """Analyze spinodal decomposition and phase separation kinetics"""
        try:
            spinodal_analysis = {
                'decomposition_modes': [],
                'growth_rates': [],
                'wavelength_selection': {},
                'kinetic_pathways': [],
                'decomposition_time_scales': {},
                'morphology_prediction': {}
            }
            
            # Identify unstable modes (negative eigenvalues)
            unstable_modes = []
            for i, eigval in enumerate(eigenvalues):
                if eigval < 0:
                    unstable_modes.append({
                        'mode_index': i,
                        'eigenvalue': eigval,
                        'eigenvector': eigenvectors[:, i].tolist(),
                        'growth_rate': np.sqrt(abs(eigval)),
                        'characteristic_length': self._calculate_characteristic_length(eigval, temperature)
                    })
            
            spinodal_analysis['decomposition_modes'] = unstable_modes
            
            # Calculate Cahn-Hilliard growth rates
            if len(unstable_modes) > 0:
                for mode in unstable_modes:
                    growth_rate = self._calculate_cahn_hilliard_growth_rate(
                        mode['eigenvalue'], temperature, hessian_matrix
                    )
                    spinodal_analysis['growth_rates'].append(growth_rate)
            
            # Wavelength selection analysis
            if len(unstable_modes) > 0:
                fastest_mode = max(unstable_modes, key=lambda x: x['growth_rate'])
                spinodal_analysis['wavelength_selection'] = {
                    'dominant_wavelength': fastest_mode['characteristic_length'],
                    'fastest_growing_mode': fastest_mode['mode_index'],
                    'selection_mechanism': 'fastest_growth'
                }
            
            # Predict decomposition time scales
            if len(spinodal_analysis['growth_rates']) > 0:
                max_growth_rate = max(spinodal_analysis['growth_rates'])
                spinodal_analysis['decomposition_time_scales'] = {
                    'nucleation_time': 1.0 / max_growth_rate if max_growth_rate > 0 else float('inf'),
                    'coarsening_time': 10.0 / max_growth_rate if max_growth_rate > 0 else float('inf'),
                    'equilibration_time': 100.0 / max_growth_rate if max_growth_rate > 0 else float('inf')
                }
            
            return spinodal_analysis
            
        except Exception as e:
            print(f"Error analyzing spinodal decomposition: {e}")
            return {'decomposition_modes': [], 'growth_rates': []}
    
    def _calculate_characteristic_length(self, eigenvalue: float, temperature: float) -> float:
        """Calculate characteristic length scale for decomposition mode"""
        try:
            # Ginzburg-Landau characteristic length
            R = 8.314472  # J/(mol·K)
            if eigenvalue < 0:
                return np.sqrt(R * temperature / abs(eigenvalue))
            else:
                return float('inf')
                
        except Exception as e:
            return 1e-9  # Default nanometer scale
    
    def _calculate_cahn_hilliard_growth_rate(self, eigenvalue: float, temperature: float,
                                           hessian_matrix: np.ndarray) -> float:
        """Calculate Cahn-Hilliard growth rate for spinodal decomposition"""
        try:
            if eigenvalue >= 0:
                return 0.0
            
            # Simplified Cahn-Hilliard growth rate
            mobility = 1e-12  # m²/(J·s) - typical atomic mobility
            gradient_energy = 1e-8  # J/m - typical gradient energy coefficient
            
            # Growth rate formula: R = -M * eigenvalue
            growth_rate = mobility * abs(eigenvalue) / gradient_energy
            
            return growth_rate
            
        except Exception as e:
            return 0.0
    
    def _assess_metastability(self, phase: str, temperature: float, pressure: float,
                            eigenvalues: np.ndarray) -> Dict:
        """Assess metastability using classical nucleation theory"""
        try:
            metastability_assessment = {
                'metastable_state': False,
                'nucleation_barrier': 0.0,
                'critical_nucleus_size': 0.0,
                'nucleation_rate': 0.0,
                'metastable_lifetime': 0.0,
                'transformation_pathways': []
            }
            
            min_eigenvalue = np.min(eigenvalues)
            
            # Assess metastability based on small negative eigenvalues
            if -1e-3 < min_eigenvalue < 0:
                metastability_assessment['metastable_state'] = True
                
                # Calculate nucleation barrier using classical nucleation theory
                surface_energy = 0.1  # J/m² - typical interfacial energy
                volume_driving_force = abs(min_eigenvalue) * 1000  # J/m³
                
                if volume_driving_force > 0:
                    critical_radius = 2 * surface_energy / volume_driving_force
                    nucleation_barrier = 16 * np.pi * surface_energy**3 / (3 * volume_driving_force**2)
                    
                    metastability_assessment['critical_nucleus_size'] = critical_radius
                    metastability_assessment['nucleation_barrier'] = nucleation_barrier
                    
                    # Nucleation rate using transition state theory
                    R = 8.314472  # J/(mol·K)
                    attempt_frequency = 1e13  # Hz
                    nucleation_rate = attempt_frequency * np.exp(-nucleation_barrier / (R * temperature))
                    
                    metastability_assessment['nucleation_rate'] = nucleation_rate
                    metastability_assessment['metastable_lifetime'] = 1.0 / nucleation_rate if nucleation_rate > 0 else float('inf')
            
            return metastability_assessment
            
        except Exception as e:
            print(f"Error assessing metastability: {e}")
            return {'metastable_state': False, 'nucleation_barrier': 0.0}
    
    def _analyze_numerical_precision(self, hessian_matrix: np.ndarray, temperature: float,
                                   pressure: float) -> Dict:
        """Analyze numerical precision and convergence of stability calculations"""
        try:
            precision_analysis = {
                'condition_number': 0.0,
                'numerical_rank': 0,
                'convergence_assessment': {},
                'precision_estimate': 0.0,
                'recommended_tolerance': 0.0
            }
            
            # Calculate condition number
            condition_number = np.linalg.cond(hessian_matrix)
            precision_analysis['condition_number'] = condition_number
            
            # Estimate numerical rank
            singular_values = np.linalg.svd(hessian_matrix, compute_uv=False)
            numerical_rank = np.sum(singular_values > 1e-12 * singular_values[0])
            precision_analysis['numerical_rank'] = numerical_rank
            
            # Precision estimate based on condition number
            machine_epsilon = np.finfo(float).eps
            precision_estimate = condition_number * machine_epsilon
            precision_analysis['precision_estimate'] = precision_estimate
            
            # Recommended tolerance for stability assessments
            precision_analysis['recommended_tolerance'] = max(1e-12, precision_estimate * 100)
            
            # Convergence assessment
            precision_analysis['convergence_assessment'] = {
                'well_conditioned': condition_number < 1e12,
                'full_rank': numerical_rank == hessian_matrix.shape[0],
                'numerically_stable': precision_estimate < 1e-8
            }
            
            return precision_analysis
            
        except Exception as e:
            print(f"Error analyzing numerical precision: {e}")
            return {'condition_number': float('inf'), 'precision_estimate': 1.0}
    
    def _quantify_stability_uncertainties(self, hessian_matrix: np.ndarray, phase: str,
                                        temperature: float, pressure: float) -> Dict:
        """Quantify uncertainties in stability calculations using error propagation"""
        try:
            uncertainty_analysis = {
                'parameter_uncertainties': {},
                'propagated_uncertainties': {},
                'confidence_intervals': {},
                'sensitivity_analysis': {}
            }
            
            # Typical parameter uncertainties
            parameter_uncertainties = {
                'temperature': 1.0,  # K
                'pressure': 100.0,   # Pa
                'composition': 0.01  # mol fraction
            }
            
            # Propagate uncertainties through eigenvalue calculation
            eigenvalues = np.linalg.eigvals(hessian_matrix)
            
            # Temperature sensitivity
            dt = parameter_uncertainties['temperature']
            temp_hessian = self._calculate_gibbs_hessian_matrix(
                phase, temperature + dt, pressure,
                self._extract_composition_variables(self.database[phase])
            )
            temp_eigenvalues = np.linalg.eigvals(temp_hessian)
            
            temperature_sensitivity = np.mean(np.abs(temp_eigenvalues - eigenvalues)) / dt
            uncertainty_analysis['sensitivity_analysis']['temperature'] = temperature_sensitivity
            
            # Pressure sensitivity
            dp = parameter_uncertainties['pressure']
            press_hessian = self._calculate_gibbs_hessian_matrix(
                phase, temperature, pressure + dp,
                self._extract_composition_variables(self.database[phase])
            )
            press_eigenvalues = np.linalg.eigvals(press_hessian)
            
            pressure_sensitivity = np.mean(np.abs(press_eigenvalues - eigenvalues)) / dp
            uncertainty_analysis['sensitivity_analysis']['pressure'] = pressure_sensitivity
            
            # Total propagated uncertainty
            total_uncertainty = np.sqrt(
                (temperature_sensitivity * parameter_uncertainties['temperature'])**2 +
                (pressure_sensitivity * parameter_uncertainties['pressure'])**2
            )
            
            uncertainty_analysis['propagated_uncertainties']['total'] = total_uncertainty
            uncertainty_analysis['propagated_uncertainties']['temperature_contribution'] = \
                temperature_sensitivity * parameter_uncertainties['temperature']
            uncertainty_analysis['propagated_uncertainties']['pressure_contribution'] = \
                pressure_sensitivity * parameter_uncertainties['pressure']
            
            # Confidence intervals (assuming normal distribution)
            confidence_level = 0.95
            z_score = 1.96  # 95% confidence
            
            for i, eigval in enumerate(eigenvalues):
                uncertainty_analysis['confidence_intervals'][f'eigenvalue_{i}'] = {
                    'lower_bound': eigval - z_score * total_uncertainty,
                    'upper_bound': eigval + z_score * total_uncertainty,
                    'confidence_level': confidence_level
                }
            
            return uncertainty_analysis
            
        except Exception as e:
            print(f"Error quantifying stability uncertainties: {e}")
            return {'propagated_uncertainties': {}, 'confidence_intervals': {}}
    
    def _verify_thermodynamic_consistency(self, hessian_matrix: np.ndarray, phase: str,
                                        temperature: float, pressure: float) -> Dict:
        """Verify thermodynamic consistency of stability calculations"""
        try:
            consistency_results = {
                'maxwell_relations': {},
                'gibbs_duhem_compliance': {},
                'phase_rule_verification': {},
                'thermodynamic_identities': {},
                'consistency_score': 0.0
            }
            
            # Verify symmetry of Hessian matrix (Maxwell relations)
            symmetry_error = np.max(np.abs(hessian_matrix - hessian_matrix.T))
            consistency_results['maxwell_relations'] = {
                'symmetric': symmetry_error < 1e-12,
                'symmetry_error': symmetry_error,
                'max_asymmetry': symmetry_error
            }
            
            # Check positive semi-definiteness for stable phases
            eigenvalues = np.linalg.eigvals(hessian_matrix)
            min_eigenvalue = np.min(eigenvalues)
            
            consistency_results['gibbs_duhem_compliance'] = {
                'positive_semidefinite': min_eigenvalue >= -1e-12,
                'minimum_eigenvalue': min_eigenvalue,
                'stability_consistent': min_eigenvalue >= 0
            }
            
            # Phase rule verification
            n_components = len(self._extract_composition_variables(self.database[phase]))
            degrees_of_freedom = n_components - 1 + 2  # Gibbs phase rule
            matrix_rank = np.linalg.matrix_rank(hessian_matrix)
            
            consistency_results['phase_rule_verification'] = {
                'expected_dof': degrees_of_freedom,
                'matrix_rank': matrix_rank,
                'rank_consistent': matrix_rank <= degrees_of_freedom
            }
            
            # Calculate overall consistency score
            consistency_score = 1.0
            if not consistency_results['maxwell_relations']['symmetric']:
                consistency_score *= 0.5
            if not consistency_results['gibbs_duhem_compliance']['positive_semidefinite']:
                consistency_score *= 0.7
            if not consistency_results['phase_rule_verification']['rank_consistent']:
                consistency_score *= 0.8
            
            consistency_results['consistency_score'] = consistency_score
            
            return consistency_results
            
        except Exception as e:
            print(f"Error verifying thermodynamic consistency: {e}")
            return {'consistency_score': 0.0}
    
    def _estimate_critical_temperature(self, eigenvalues: np.ndarray, temperature: float,
                                     pressure: float) -> float:
        """Estimate critical temperature using Landau theory"""
        try:
            min_eigenvalue = np.min(eigenvalues)
            
            if min_eigenvalue >= 0:
                return temperature
            
            # Simple linear extrapolation assuming eigenvalue ~ (T - Tc)
            # This is a crude approximation - in practice would need more sophisticated analysis
            eigenvalue_temperature_slope = min_eigenvalue / temperature  # Approximate slope
            
            if eigenvalue_temperature_slope != 0:
                critical_temperature = temperature - min_eigenvalue / eigenvalue_temperature_slope
                return max(0, critical_temperature)
            else:
                return temperature
                
        except Exception as e:
            return temperature
    
    def _fallback_stability_matrix(self, phase: str, temperature: float, pressure: float) -> np.ndarray:
        """Fallback simplified stability matrix calculation"""
        try:
            if phase not in self.database:
                return np.array([[1.0]])
            
            dt = 1.0
            dp = 100.0
            
            g_00 = self.calculate_gibbs_energy(phase, temperature, pressure)
            g_dt = self.calculate_gibbs_energy(phase, temperature + dt, pressure)
            g_dp = self.calculate_gibbs_energy(phase, temperature, pressure + dp)
            g_dtdp = self.calculate_gibbs_energy(phase, temperature + dt, pressure + dp)
            
            d2g_dt2 = (g_dt - g_00) / dt
            d2g_dp2 = (g_dp - g_00) / dp
            d2g_dtdp = (g_dtdp - g_dt - g_dp + g_00) / (dt * dp)
            
            stability_matrix = np.array([[d2g_dt2, d2g_dtdp], [d2g_dtdp, d2g_dp2]])
            return stability_matrix
            
        except Exception as e:
            return np.array([[1.0, 0.0], [0.0, 1.0]])
    
    def _calculate_density(self, phase: str, temperature: float, pressure: float) -> float:
        """Calculate density from molar volume and molar mass"""
        if phase not in self.database:
            return 0.0
        
        molar_volume = self._calculate_molar_volume(phase, temperature, pressure)
        molar_mass = self._calculate_molar_mass(phase)
        
        if molar_volume > 0:
            return molar_mass / molar_volume  # kg/m³
        return 0.0
    
    def _calculate_molar_mass(self, phase: str) -> float:
        """Calculate molar mass from elemental composition"""
        if phase not in self.database:
            return 0.0
        
        # Atomic masses (g/mol)
        atomic_masses = {
            'H': 1.008, 'He': 4.003, 'Li': 6.941, 'Be': 9.012, 'B': 10.811,
            'C': 12.011, 'N': 14.007, 'O': 15.999, 'F': 18.998, 'Ne': 20.180,
            'Na': 22.990, 'Mg': 24.305, 'Al': 26.982, 'Si': 28.086, 'P': 30.974,
            'S': 32.065, 'Cl': 35.453, 'Ar': 39.948, 'K': 39.098, 'Ca': 40.078,
            'Ti': 47.867, 'Fe': 55.845, 'Ni': 58.693, 'Cu': 63.546, 'Zn': 65.38
        }
        
        elements = self.database[phase].get('elements', {})
        molar_mass = 0.0
        
        for element, count in elements.items():
            if element in atomic_masses:
                molar_mass += atomic_masses[element] * count
        
        return molar_mass / 1000.0  # Convert g/mol to kg/mol
    
    def _calculate_bulk_modulus(self, phase: str, temperature: float, pressure: float) -> float:
        """Calculate bulk modulus"""
        if phase not in self.database:
            return 0.0
        
        data = self.database[phase]
        beta = data.get('beta', 1e-5)  # Compressibility
        
        # Bulk modulus is inverse of compressibility
        if beta > 0:
            return 1.0 / beta  # Pa
        return 1e11  # Default high value for incompressible phases
    
    def _calculate_thermal_expansion_coeff(self, phase: str, temperature: float, pressure: float) -> float:
        """Advanced thermal expansion coefficient calculation with rigorous thermodynamic relationships and anharmonic effects"""
        
        if phase not in self.database:
            return 0.0
        
        try:
            thermal_expansion_analysis = {
                'linear_expansion': {},
                'volumetric_expansion': {},
                'anharmonic_effects': {},
                'pressure_dependence': {},
                'temperature_dependence': {},
                'crystal_structure_effects': {},
                'phonon_contributions': {},
                'electronic_contributions': {},
                'thermodynamic_consistency': {},
                'uncertainty_quantification': {}
            }
            
            data = self.database[phase]
            R = 8.314472  # J/(mol·K)
            
            # Extract fundamental thermodynamic and structural parameters
            phase_parameters = self._extract_thermal_expansion_parameters(data, phase)
            
            # Calculate intrinsic thermal expansion at reference conditions
            alpha_0 = self._calculate_intrinsic_thermal_expansion(phase_parameters, phase)
            thermal_expansion_analysis['linear_expansion']['alpha_0'] = alpha_0
            
            # Calculate anharmonic contributions using Grüneisen parameter theory
            anharmonic_contribution = self._calculate_anharmonic_thermal_expansion(
                phase_parameters, temperature, pressure, phase
            )
            thermal_expansion_analysis['anharmonic_effects'] = anharmonic_contribution
            
            # Calculate pressure dependence using Anderson-Grüneisen parameter
            pressure_correction = self._calculate_pressure_dependent_expansion(
                alpha_0, pressure, phase_parameters, temperature
            )
            thermal_expansion_analysis['pressure_dependence'] = pressure_correction
            
            # Calculate temperature dependence using quasi-harmonic approximation
            temperature_correction = self._calculate_temperature_dependent_expansion(
                alpha_0, temperature, phase_parameters, pressure
            )
            thermal_expansion_analysis['temperature_dependence'] = temperature_correction
            
            # Account for crystal structure effects and phase transitions
            crystal_structure_effects = self._calculate_crystal_structure_thermal_expansion(
                phase, temperature, pressure, phase_parameters
            )
            thermal_expansion_analysis['crystal_structure_effects'] = crystal_structure_effects
            
            # Calculate phonon contributions using Debye model
            phonon_contribution = self._calculate_phonon_thermal_expansion(
                temperature, pressure, phase_parameters
            )
            thermal_expansion_analysis['phonon_contributions'] = phonon_contribution
            
            # Calculate electronic contributions for metallic phases
            electronic_contribution = self._calculate_electronic_thermal_expansion(
                temperature, phase_parameters, phase
            )
            thermal_expansion_analysis['electronic_contributions'] = electronic_contribution
            
            # Combine all contributions using thermodynamic relationships
            total_thermal_expansion = self._combine_thermal_expansion_contributions(
                alpha_0, anharmonic_contribution, pressure_correction,
                temperature_correction, crystal_structure_effects,
                phonon_contribution, electronic_contribution
            )
            
            # Apply thermodynamic consistency checks
            consistency_results = self._verify_thermal_expansion_consistency(
                total_thermal_expansion, temperature, pressure, phase
            )
            thermal_expansion_analysis['thermodynamic_consistency'] = consistency_results
            
            # Quantify uncertainties in thermal expansion calculations
            uncertainty_analysis = self._quantify_thermal_expansion_uncertainties(
                total_thermal_expansion, phase_parameters, temperature, pressure
            )
            thermal_expansion_analysis['uncertainty_quantification'] = uncertainty_analysis
            
            # Store comprehensive analysis results
            if not hasattr(self, 'thermal_expansion_cache'):
                self.thermal_expansion_cache = {}
            
            cache_key = f"{phase}_{temperature:.2f}_{pressure:.2f}"
            self.thermal_expansion_cache[cache_key] = thermal_expansion_analysis
            
            return total_thermal_expansion
            
        except Exception as e:
            print(f"Error in advanced thermal expansion calculation: {e}")
            return self._fallback_thermal_expansion(phase, temperature, pressure)
    
    def _extract_thermal_expansion_parameters(self, data: Dict, phase: str) -> Dict:
        """Extract comprehensive thermal expansion parameters from phase data"""
        try:
            parameters = {
                'reference_alpha': data.get('alpha', 3e-5),  # K⁻¹
                'gruneisen_parameter': data.get('gruneisen', 1.5),
                'anderson_gruneisen': data.get('anderson_gruneisen', 5.0),
                'bulk_modulus': data.get('bulk_modulus', 100e9),  # Pa
                'bulk_modulus_derivative': data.get('bulk_modulus_prime', 4.0),
                'debye_temperature': data.get('debye_temperature', 400),  # K
                'molar_volume': data.get('molar_volume', 24.0e-6),  # m³/mol
                'heat_capacity': data.get('heat_capacity', 25.0),  # J/(mol·K)
                'density': data.get('density', 3000),  # kg/m³
                'crystal_system': data.get('crystal_system', 'cubic'),
                'coordination_number': data.get('coordination_number', 6),
                'bond_strength': data.get('bond_strength', 400),  # kJ/mol
                'ionic_character': data.get('ionic_character', 0.5),
                'electronic_contribution': data.get('electronic_thermal_expansion', 0.0)
            }
            
            # Calculate derived parameters
            parameters['atomic_volume'] = parameters['molar_volume'] / 6.022e23  # m³/atom
            parameters['mean_atomic_mass'] = self._estimate_mean_atomic_mass(data, phase)
            parameters['bond_anharmonicity'] = self._estimate_bond_anharmonicity(parameters)
            parameters['phonon_frequency'] = self._estimate_phonon_frequency(parameters)
            
            return parameters
            
        except Exception as e:
            print(f"Error extracting thermal expansion parameters: {e}")
            return {'reference_alpha': 3e-5, 'gruneisen_parameter': 1.5}
    
    def _calculate_intrinsic_thermal_expansion(self, parameters: Dict, phase: str) -> float:
        """Calculate intrinsic thermal expansion coefficient using fundamental theory"""
        try:
            # Start with reference value
            alpha_ref = parameters['reference_alpha']
            
            # Apply crystal structure corrections
            crystal_system = parameters.get('crystal_system', 'cubic')
            structure_factor = self._get_crystal_structure_factor(crystal_system)
            
            # Apply coordination number effects
            coordination_factor = self._get_coordination_factor(parameters.get('coordination_number', 6))
            
            # Apply bond strength corrections
            bond_strength_factor = self._get_bond_strength_factor(parameters.get('bond_strength', 400))
            
            # Calculate intrinsic thermal expansion
            alpha_intrinsic = alpha_ref * structure_factor * coordination_factor * bond_strength_factor
            
            return alpha_intrinsic
            
        except Exception as e:
            print(f"Error calculating intrinsic thermal expansion: {e}")
            return parameters.get('reference_alpha', 3e-5)
    
    def _get_crystal_structure_factor(self, crystal_system: str) -> float:
        """Get thermal expansion factor based on crystal structure"""
        structure_factors = {
            'cubic': 1.0,
            'tetragonal': 1.1,
            'orthorhombic': 1.2,
            'hexagonal': 0.9,
            'trigonal': 0.95,
            'monoclinic': 1.3,
            'triclinic': 1.4
        }
        return structure_factors.get(crystal_system, 1.0)
    
    def _get_coordination_factor(self, coordination_number: float) -> float:
        """Get thermal expansion factor based on coordination number"""
        try:
            # Lower coordination leads to higher thermal expansion
            base_coordination = 6.0
            coordination_factor = (base_coordination / coordination_number) ** 0.5
            return max(0.5, min(2.0, coordination_factor))
        except:
            return 1.0
    
    def _get_bond_strength_factor(self, bond_strength: float) -> float:
        """Get thermal expansion factor based on bond strength"""
        try:
            # Stronger bonds lead to lower thermal expansion
            reference_strength = 400.0  # kJ/mol
            strength_factor = (reference_strength / bond_strength) ** 0.3
            return max(0.3, min(3.0, strength_factor))
        except:
            return 1.0
    
    def _calculate_anharmonic_thermal_expansion(self, parameters: Dict, temperature: float,
                                              pressure: float, phase: str) -> Dict:
        """Calculate anharmonic contributions using Grüneisen parameter theory"""
        try:
            anharmonic_analysis = {
                'gruneisen_contribution': 0.0,
                'mode_gruneisen_parameters': [],
                'anharmonic_correction': 0.0,
                'temperature_scaling': 0.0,
                'pressure_scaling': 0.0
            }
            
            gamma = parameters.get('gruneisen_parameter', 1.5)
            debye_temp = parameters.get('debye_temperature', 400)
            bulk_modulus = parameters.get('bulk_modulus', 100e9)
            molar_volume = parameters.get('molar_volume', 24.0e-6)
            
            # Calculate Debye heat capacity contribution
            x = debye_temp / temperature
            if x > 0:
                # Debye function for heat capacity
                if x < 50:  # Avoid overflow
                    debye_integral = self._calculate_debye_integral(x)
                    cv_debye = 3 * 8.314472 * debye_integral  # J/(mol·K)
                else:
                    cv_debye = 3 * 8.314472  # High temperature limit
            else:
                cv_debye = 3 * 8.314472
            
            # Grüneisen thermal expansion formula
            gruneisen_alpha = gamma * cv_debye / (bulk_modulus * molar_volume)
            anharmonic_analysis['gruneisen_contribution'] = gruneisen_alpha
            
            # Calculate mode-specific Grüneisen parameters
            mode_gruneisen = self._calculate_mode_gruneisen_parameters(
                temperature, parameters
            )
            anharmonic_analysis['mode_gruneisen_parameters'] = mode_gruneisen
            
            # Higher-order anharmonic corrections
            anharmonic_correction = self._calculate_higher_order_anharmonic_corrections(
                temperature, pressure, parameters
            )
            anharmonic_analysis['anharmonic_correction'] = anharmonic_correction
            
            # Temperature scaling of anharmonicity
            temperature_scaling = self._calculate_anharmonic_temperature_scaling(
                temperature, debye_temp
            )
            anharmonic_analysis['temperature_scaling'] = temperature_scaling
            
            return anharmonic_analysis
            
        except Exception as e:
            print(f"Error calculating anharmonic thermal expansion: {e}")
            return {'gruneisen_contribution': 0.0, 'anharmonic_correction': 0.0}
    
    def _calculate_debye_integral(self, x: float) -> float:
        """Calculate Debye integral for heat capacity"""
        try:
            if x < 0.01:
                # Low temperature expansion
                return 1.0 - x/8.0 + x**2/192.0
            elif x > 10:
                # High temperature limit
                return 12.0/x**3 * (np.pi**4/5.0 - 6.0/x**2)
            else:
                # Numerical integration using Simpson's rule
                n_points = 100
                t_values = np.linspace(0, x, n_points)
                integrand = t_values**4 * np.exp(t_values) / (np.exp(t_values) - 1)**2
                integrand[0] = 0  # Handle t=0 case
                integral = np.trapz(integrand, t_values)
                return 3.0/x**3 * integral
        except:
            return 1.0
    
    def _calculate_mode_gruneisen_parameters(self, temperature: float, parameters: Dict) -> List[Dict]:
        """Calculate mode-specific Grüneisen parameters"""
        try:
            mode_parameters = []
            
            # Acoustic modes
            for i in range(3):
                mode_info = {
                    'mode_type': f'acoustic_{i+1}',
                    'frequency': parameters.get('phonon_frequency', 1e13) * (0.8 + 0.4*i),
                    'gruneisen': parameters.get('gruneisen_parameter', 1.5) * (0.9 + 0.2*i),
                    'population': self._calculate_phonon_population(
                        parameters.get('phonon_frequency', 1e13) * (0.8 + 0.4*i), temperature
                    )
                }
                mode_parameters.append(mode_info)
            
            # Advanced optical modes with rigorous crystal symmetry and phonon dispersion analysis
            optical_modes = self._calculate_advanced_optical_modes(parameters, temperature)
            mode_parameters.extend(optical_modes)
            
            return mode_parameters
            
        except Exception as e:
            print(f"Error calculating mode Grüneisen parameters: {e}")
            return []
    
    def _calculate_advanced_optical_modes(self, parameters: Dict, temperature: float) -> List[Dict]:
        """Calculate advanced optical phonon modes with rigorous crystal symmetry and dispersion analysis"""
        try:
            optical_modes = []
            
            # Extract crystal structure parameters
            crystal_system = parameters.get('crystal_system', 'cubic')
            coordination_number = parameters.get('coordination_number', 6)
            bond_strength = parameters.get('bond_strength', 400)
            ionic_character = parameters.get('ionic_character', 0.5)
            
            # Initialize comprehensive optical mode analysis
            optical_analysis = {
                'symmetry_analysis': {},
                'dispersion_relations': {},
                'polarization_vectors': {},
                'born_effective_charges': {},
                'dielectric_properties': {},
                'raman_infrared_activity': {},
                'mode_coupling_effects': {},
                'temperature_dependencies': {}
            }
            
            # Determine number of optical modes based on crystal structure
            optical_mode_count = self._determine_optical_mode_count(crystal_system, coordination_number)
            
            # Calculate symmetry-based optical modes
            symmetry_modes = self._calculate_symmetry_based_optical_modes(
                crystal_system, optical_mode_count, parameters
            )
            optical_analysis['symmetry_analysis'] = symmetry_modes
            
            # Calculate phonon dispersion relations
            dispersion_data = self._calculate_optical_phonon_dispersion(
                crystal_system, parameters, temperature
            )
            optical_analysis['dispersion_relations'] = dispersion_data
            
            # Calculate polarization vectors and eigenmodes
            polarization_analysis = self._calculate_optical_mode_polarizations(
                crystal_system, coordination_number, parameters
            )
            optical_analysis['polarization_vectors'] = polarization_analysis
            
            # Calculate Born effective charges for ionic crystals
            if ionic_character > 0.3:
                born_charges = self._calculate_born_effective_charges(
                    crystal_system, ionic_character, parameters
                )
                optical_analysis['born_effective_charges'] = born_charges
            
            # Calculate dielectric properties and LO-TO splitting
            dielectric_data = self._calculate_dielectric_optical_properties(
                crystal_system, ionic_character, parameters, temperature
            )
            optical_analysis['dielectric_properties'] = dielectric_data
            
            # Determine Raman and infrared activity
            activity_analysis = self._analyze_raman_infrared_activity(
                crystal_system, symmetry_modes, parameters
            )
            optical_analysis['raman_infrared_activity'] = activity_analysis
            
            # Calculate mode coupling and anharmonic interactions
            coupling_effects = self._calculate_optical_mode_coupling(
                symmetry_modes, temperature, parameters
            )
            optical_analysis['mode_coupling_effects'] = coupling_effects
            
            # Build individual optical mode data
            for mode_data in symmetry_modes:
                # Extract base properties
                base_frequency = mode_data['frequency']
                symmetry_label = mode_data['symmetry_label']
                degeneracy = mode_data['degeneracy']
                
                # Apply temperature-dependent corrections
                temp_corrected_frequency = self._apply_temperature_corrections_to_frequency(
                    base_frequency, temperature, parameters, mode_data
                )
                
                # Calculate mode-specific Grüneisen parameter
                mode_gruneisen = self._calculate_mode_specific_gruneisen(
                    mode_data, parameters, temperature
                )
                
                # Calculate phonon population
                population = self._calculate_phonon_population(temp_corrected_frequency, temperature)
                
                # Calculate LO-TO splitting for polar modes
                lo_to_splitting = 0.0
                if mode_data.get('polar', False) and ionic_character > 0.3:
                    lo_to_splitting = self._calculate_lo_to_splitting(
                        mode_data, dielectric_data, parameters
                    )
                
                # Calculate anharmonic linewidth
                linewidth = self._calculate_optical_mode_linewidth(
                    temp_corrected_frequency, temperature, parameters, mode_data
                )
                
                # Calculate thermal expansion contribution
                thermal_expansion_contribution = self._calculate_mode_thermal_expansion_contribution(
                    temp_corrected_frequency, mode_gruneisen, population, parameters
                )
                
                # Create comprehensive mode information
                for deg_index in range(degeneracy):
                    mode_info = {
                        'mode_type': f'optical_{symmetry_label}_{deg_index+1}',
                        'symmetry_label': symmetry_label,
                        'degeneracy': degeneracy,
                        'degenerate_index': deg_index,
                        'frequency': temp_corrected_frequency,
                        'frequency_base': base_frequency,
                        'gruneisen': mode_gruneisen,
                        'population': population,
                        'polarization_vector': mode_data.get('polarization_vectors', [{}])[min(deg_index, len(mode_data.get('polarization_vectors', [{}]))-1)],
                        'lo_to_splitting': lo_to_splitting,
                        'linewidth': linewidth,
                        'thermal_expansion_contribution': thermal_expansion_contribution,
                        'raman_active': mode_data.get('raman_active', False),
                        'infrared_active': mode_data.get('infrared_active', False),
                        'polar': mode_data.get('polar', False),
                        'elastic_constants_coupling': mode_data.get('elastic_coupling', 0.0),
                        'anharmonic_decay_channels': self._identify_anharmonic_decay_channels(
                            mode_data, symmetry_modes, temperature
                        ),
                        'mode_coupling_strength': coupling_effects.get(symmetry_label, 0.0),
                        'temperature_derivative': self._calculate_mode_temperature_derivative(
                            mode_data, temperature, parameters
                        ),
                        'pressure_derivative': self._calculate_mode_pressure_derivative(
                            mode_data, parameters
                        )
                    }
                    
                    optical_modes.append(mode_info)
            
            return optical_modes
            
        except Exception as e:
            print(f"Error calculating advanced optical modes: {e}")
            return self._fallback_optical_modes(parameters, temperature)
    
    def _determine_optical_mode_count(self, crystal_system: str, coordination_number: float) -> int:
        """Determine number of optical modes based on crystal structure"""
        try:
            # Base number of optical modes per primitive cell
            base_modes = {
                'cubic': 9,      # 3N-3 for simple cubic with N=4 atoms
                'tetragonal': 12,
                'orthorhombic': 15,
                'hexagonal': 9,
                'trigonal': 12,
                'monoclinic': 18,
                'triclinic': 21
            }
            
            base_count = base_modes.get(crystal_system, 9)
            
            # Adjust based on coordination number (higher coordination = more complex structure)
            coordination_factor = max(1.0, coordination_number / 6.0)
            
            # Ensure even number for practical calculations
            total_modes = int(base_count * coordination_factor)
            return total_modes if total_modes % 2 == 0 else total_modes + 1
            
        except Exception as e:
            return 9  # Default for simple cubic
    
    def _calculate_symmetry_based_optical_modes(self, crystal_system: str, mode_count: int,
                                              parameters: Dict) -> List[Dict]:
        """Calculate optical modes based on crystal symmetry and group theory"""
        try:
            symmetry_modes = []
            
            # Define symmetry representations for common crystal systems
            symmetry_representations = self._get_crystal_symmetry_representations(crystal_system)
            
            # Base phonon frequency
            base_frequency = parameters.get('phonon_frequency', 1e13)
            debye_temperature = parameters.get('debye_temperature', 400)
            
            # Calculate Einstein frequency for optical modes
            einstein_frequency = base_frequency * 1.5  # Typically higher than acoustic
            
            mode_index = 0
            for symmetry_data in symmetry_representations:
                symmetry_label = symmetry_data['label']
                degeneracy = symmetry_data['degeneracy']
                
                # Calculate mode frequency based on symmetry and bonding
                mode_frequency = self._calculate_symmetry_mode_frequency(
                    symmetry_data, einstein_frequency, parameters
                )
                
                # Determine optical activity
                raman_active = symmetry_data.get('raman_active', True)
                infrared_active = symmetry_data.get('infrared_active', True)
                polar = symmetry_data.get('polar', False)
                
                # Calculate polarization vectors
                polarization_vectors = self._generate_mode_polarization_vectors(
                    symmetry_data, crystal_system
                )
                
                # Calculate elastic coupling strength
                elastic_coupling = self._calculate_mode_elastic_coupling(
                    symmetry_data, parameters
                )
                
                mode_data = {
                    'symmetry_label': symmetry_label,
                    'degeneracy': degeneracy,
                    'frequency': mode_frequency,
                    'raman_active': raman_active,
                    'infrared_active': infrared_active,
                    'polar': polar,
                    'polarization_vectors': polarization_vectors,
                    'elastic_coupling': elastic_coupling,
                    'symmetry_operations': symmetry_data.get('operations', []),
                    'character_table_entry': symmetry_data.get('character', 1)
                }
                
                symmetry_modes.append(mode_data)
                mode_index += degeneracy
                
                # Stop when we have enough modes
                if mode_index >= mode_count:
                    break
            
            return symmetry_modes
            
        except Exception as e:
            print(f"Error calculating symmetry-based optical modes: {e}")
            return self._get_default_optical_modes(mode_count, parameters)
    
    def _get_crystal_symmetry_representations(self, crystal_system: str) -> List[Dict]:
        """Get symmetry representations for crystal systems"""
        try:
            representations = {
                'cubic': [
                    {'label': 'A1g', 'degeneracy': 1, 'raman_active': True, 'infrared_active': False, 'polar': False},
                    {'label': 'Eg', 'degeneracy': 2, 'raman_active': True, 'infrared_active': False, 'polar': False},
                    {'label': 'F1u', 'degeneracy': 3, 'raman_active': False, 'infrared_active': True, 'polar': True},
                    {'label': 'F2g', 'degeneracy': 3, 'raman_active': True, 'infrared_active': False, 'polar': False},
                    {'label': 'F2u', 'degeneracy': 3, 'raman_active': False, 'infrared_active': False, 'polar': False}
                ],
                'tetragonal': [
                    {'label': 'A1g', 'degeneracy': 1, 'raman_active': True, 'infrared_active': False, 'polar': False},
                    {'label': 'A2u', 'degeneracy': 1, 'raman_active': False, 'infrared_active': True, 'polar': True},
                    {'label': 'B1g', 'degeneracy': 1, 'raman_active': True, 'infrared_active': False, 'polar': False},
                    {'label': 'Eg', 'degeneracy': 2, 'raman_active': True, 'infrared_active': False, 'polar': False},
                    {'label': 'Eu', 'degeneracy': 2, 'raman_active': False, 'infrared_active': True, 'polar': True}
                ],
                'hexagonal': [
                    {'label': 'A1g', 'degeneracy': 1, 'raman_active': True, 'infrared_active': False, 'polar': False},
                    {'label': 'A2u', 'degeneracy': 1, 'raman_active': False, 'infrared_active': True, 'polar': True},
                    {'label': 'E1g', 'degeneracy': 2, 'raman_active': True, 'infrared_active': False, 'polar': False},
                    {'label': 'E1u', 'degeneracy': 2, 'raman_active': False, 'infrared_active': True, 'polar': True},
                    {'label': 'E2g', 'degeneracy': 2, 'raman_active': True, 'infrared_active': False, 'polar': False}
                ],
                'orthorhombic': [
                    {'label': 'Ag', 'degeneracy': 1, 'raman_active': True, 'infrared_active': False, 'polar': False},
                    {'label': 'B1g', 'degeneracy': 1, 'raman_active': True, 'infrared_active': False, 'polar': False},
                    {'label': 'B2g', 'degeneracy': 1, 'raman_active': True, 'infrared_active': False, 'polar': False},
                    {'label': 'B3g', 'degeneracy': 1, 'raman_active': True, 'infrared_active': False, 'polar': False},
                    {'label': 'B1u', 'degeneracy': 1, 'raman_active': False, 'infrared_active': True, 'polar': True},
                    {'label': 'B2u', 'degeneracy': 1, 'raman_active': False, 'infrared_active': True, 'polar': True},
                    {'label': 'B3u', 'degeneracy': 1, 'raman_active': False, 'infrared_active': True, 'polar': True}
                ]
            }
            
            return representations.get(crystal_system, representations['cubic'])
            
        except Exception as e:
            # Default cubic representations
            return [
                {'label': 'A1g', 'degeneracy': 1, 'raman_active': True, 'infrared_active': False, 'polar': False},
                {'label': 'Eg', 'degeneracy': 2, 'raman_active': True, 'infrared_active': False, 'polar': False},
                {'label': 'F1u', 'degeneracy': 3, 'raman_active': False, 'infrared_active': True, 'polar': True}
            ]
    
    def _calculate_symmetry_mode_frequency(self, symmetry_data: Dict, base_frequency: float,
                                         parameters: Dict) -> float:
        """Calculate mode frequency based on symmetry and bonding characteristics"""
        try:
            # Base frequency scaling factors by symmetry
            symmetry_scaling = {
                'A1g': 1.0,   # Breathing modes
                'Eg': 0.9,    # Doubly degenerate modes
                'F1u': 1.2,   # Polar modes (LO)
                'F2g': 0.8,   # Non-polar modes
                'A2u': 1.1,   # Polar modes
                'B1g': 0.85,  # Shear modes
                'Eu': 1.15    # Polar doubly degenerate
            }
            
            symmetry_label = symmetry_data['label']
            scaling_factor = symmetry_scaling.get(symmetry_label, 1.0)
            
            # Apply bond strength corrections
            bond_strength = parameters.get('bond_strength', 400)  # kJ/mol
            bond_factor = np.sqrt(bond_strength / 400.0)
            
            # Apply mass effects
            mean_mass = parameters.get('mean_atomic_mass', 30.0)  # g/mol
            mass_factor = np.sqrt(30.0 / mean_mass)
            
            # Apply coordination number effects
            coordination = parameters.get('coordination_number', 6)
            coordination_factor = np.sqrt(coordination / 6.0)
            
            # Calculate final frequency
            mode_frequency = base_frequency * scaling_factor * bond_factor * mass_factor * coordination_factor
            
            return mode_frequency
            
        except Exception as e:
            return base_frequency
    
    def _generate_mode_polarization_vectors(self, symmetry_data: Dict, crystal_system: str) -> List[Dict]:
        """Generate polarization vectors for optical modes based on symmetry"""
        try:
            polarization_vectors = []
            symmetry_label = symmetry_data['label']
            degeneracy = symmetry_data['degeneracy']
            
            # Define polarization vectors based on symmetry
            if crystal_system == 'cubic':
                if 'A1' in symmetry_label:
                    # Totally symmetric breathing mode
                    polarization_vectors.append({
                        'vector': [1/np.sqrt(3), 1/np.sqrt(3), 1/np.sqrt(3)],
                        'description': 'isotropic_breathing'
                    })
                elif 'Eg' in symmetry_label:
                    # Doubly degenerate modes
                    polarization_vectors.extend([
                        {'vector': [1, 0, 0], 'description': 'x_polarized'},
                        {'vector': [0, 1, 0], 'description': 'y_polarized'}
                    ])
                elif 'F1u' in symmetry_label or 'F2' in symmetry_label:
                    # Triply degenerate modes
                    polarization_vectors.extend([
                        {'vector': [1, 0, 0], 'description': 'x_polarized'},
                        {'vector': [0, 1, 0], 'description': 'y_polarized'},
                        {'vector': [0, 0, 1], 'description': 'z_polarized'}
                    ])
            
            elif crystal_system == 'tetragonal':
                if 'A1' in symmetry_label or 'A2' in symmetry_label:
                    polarization_vectors.append({
                        'vector': [0, 0, 1],
                        'description': 'c_axis_polarized'
                    })
                elif 'B1' in symmetry_label:
                    polarization_vectors.append({
                        'vector': [1/np.sqrt(2), -1/np.sqrt(2), 0],
                        'description': 'diagonal_ab_plane'
                    })
                elif 'E' in symmetry_label:
                    polarization_vectors.extend([
                        {'vector': [1, 0, 0], 'description': 'a_axis_polarized'},
                        {'vector': [0, 1, 0], 'description': 'b_axis_polarized'}
                    ])
            
            elif crystal_system == 'hexagonal':
                if 'A1' in symmetry_label or 'A2' in symmetry_label:
                    polarization_vectors.append({
                        'vector': [0, 0, 1],
                        'description': 'c_axis_polarized'
                    })
                elif 'E1' in symmetry_label or 'E2' in symmetry_label:
                    polarization_vectors.extend([
                        {'vector': [1, 0, 0], 'description': 'basal_plane_x'},
                        {'vector': [0, 1, 0], 'description': 'basal_plane_y'}
                    ])
            
            # Ensure we have the right number of vectors
            while len(polarization_vectors) < degeneracy:
                polarization_vectors.append({
                    'vector': [1, 0, 0],
                    'description': f'default_mode_{len(polarization_vectors)}'
                })
            
            return polarization_vectors[:degeneracy]
            
        except Exception as e:
            # Default polarization vectors
            return [{'vector': [1, 0, 0], 'description': 'default'}] * symmetry_data.get('degeneracy', 1)
    
    def _calculate_mode_elastic_coupling(self, symmetry_data: Dict, parameters: Dict) -> float:
        """Calculate coupling strength between optical modes and elastic deformation"""
        try:
            # Elastic coupling depends on symmetry and ionic character
            symmetry_label = symmetry_data['label']
            ionic_character = parameters.get('ionic_character', 0.5)
            bulk_modulus = parameters.get('bulk_modulus', 100e9)
            
            # Base coupling strengths by symmetry
            base_coupling = {
                'A1g': 0.8,   # Strong coupling for breathing modes
                'Eg': 0.6,    # Moderate coupling for shear modes
                'F1u': 0.9,   # Strong coupling for polar modes
                'F2g': 0.4,   # Weak coupling for non-polar modes
                'A2u': 0.7,   # Moderate coupling for polar modes
                'B1g': 0.5    # Moderate coupling for shear modes
            }
            
            coupling_strength = base_coupling.get(symmetry_label, 0.5)
            
            # Scale by ionic character (more ionic = stronger coupling)
            coupling_strength *= (1.0 + ionic_character)
            
            # Scale by bulk modulus (stiffer material = stronger coupling)
            modulus_factor = np.sqrt(bulk_modulus / 100e9)
            coupling_strength *= modulus_factor
            
            return min(1.0, coupling_strength)
            
        except Exception as e:
            return 0.5
    
    def _calculate_optical_phonon_dispersion(self, crystal_system: str, parameters: Dict,
                                           temperature: float) -> Dict:
        """Calculate phonon dispersion relations for optical modes"""
        try:
            dispersion_data = {
                'gamma_point_frequencies': [],
                'zone_boundary_frequencies': [],
                'dispersion_slopes': [],
                'mode_velocities': [],
                'density_of_states': {}
            }
            
            # Calculate dispersion along high-symmetry directions
            high_symmetry_points = self._get_high_symmetry_points(crystal_system)
            
            for point_data in high_symmetry_points:
                point_name = point_data['name']
                k_vector = point_data['k_vector']
                
                # Calculate frequencies at this k-point
                frequencies = self._calculate_frequencies_at_k_point(
                    k_vector, parameters, crystal_system
                )
                
                # Calculate group velocities
                velocities = self._calculate_group_velocities(
                    k_vector, frequencies, parameters
                )
                
                dispersion_data[f'{point_name}_frequencies'] = frequencies
                dispersion_data[f'{point_name}_velocities'] = velocities
            
            # Calculate phonon density of states
            dos_data = self._calculate_optical_phonon_dos(parameters, temperature)
            dispersion_data['density_of_states'] = dos_data
            
            return dispersion_data
            
        except Exception as e:
            print(f"Error calculating optical phonon dispersion: {e}")
            return {'gamma_point_frequencies': [], 'density_of_states': {}}
    
    def _get_high_symmetry_points(self, crystal_system: str) -> List[Dict]:
        """Get high-symmetry points in the Brillouin zone"""
        try:
            if crystal_system == 'cubic':
                return [
                    {'name': 'Gamma', 'k_vector': [0, 0, 0]},
                    {'name': 'X', 'k_vector': [0.5, 0, 0]},
                    {'name': 'L', 'k_vector': [0.5, 0.5, 0.5]},
                    {'name': 'W', 'k_vector': [0.5, 0.5, 0]}
                ]
            elif crystal_system == 'tetragonal':
                return [
                    {'name': 'Gamma', 'k_vector': [0, 0, 0]},
                    {'name': 'X', 'k_vector': [0.5, 0, 0]},
                    {'name': 'M', 'k_vector': [0.5, 0.5, 0]},
                    {'name': 'Z', 'k_vector': [0, 0, 0.5]}
                ]
            elif crystal_system == 'hexagonal':
                return [
                    {'name': 'Gamma', 'k_vector': [0, 0, 0]},
                    {'name': 'K', 'k_vector': [1/3, 1/3, 0]},
                    {'name': 'M', 'k_vector': [0.5, 0, 0]},
                    {'name': 'A', 'k_vector': [0, 0, 0.5]}
                ]
            else:
                # Default to cubic
                return [
                    {'name': 'Gamma', 'k_vector': [0, 0, 0]},
                    {'name': 'X', 'k_vector': [0.5, 0, 0]}
                ]
                
        except Exception as e:
            return [{'name': 'Gamma', 'k_vector': [0, 0, 0]}]
    
    def _calculate_frequencies_at_k_point(self, k_vector: List[float], parameters: Dict,
                                        crystal_system: str) -> List[float]:
        """Calculate phonon frequencies at specific k-point"""
        try:
            frequencies = []
            base_frequency = parameters.get('phonon_frequency', 1e13)
            
            # Simple dispersion model
            k_magnitude = np.sqrt(sum(k**2 for k in k_vector))
            
            # Optical mode dispersion (weak k-dependence)
            for i in range(6):  # Number of optical modes
                # Base frequency with weak dispersion
                freq = base_frequency * (1.2 + 0.3*i) * (1.0 - 0.1*k_magnitude)
                frequencies.append(freq)
            
            return frequencies
            
        except Exception as e:
            return [1e13] * 6
    
    def _calculate_group_velocities(self, k_vector: List[float], frequencies: List[float],
                                  parameters: Dict) -> List[float]:
        """Calculate group velocities for optical modes"""
        try:
            velocities = []
            lattice_parameter = 5e-10  # m, typical value
            
            for freq in frequencies:
                # Simplified group velocity calculation
                # v_g = dω/dk ≈ ω * lattice_parameter for optical modes
                velocity = freq * lattice_parameter * 0.1  # Reduced for optical modes
                velocities.append(velocity)
            
            return velocities
            
        except Exception as e:
            return [1000.0] * len(frequencies)  # Default 1 km/s
    
    def _calculate_optical_phonon_dos(self, parameters: Dict, temperature: float) -> Dict:
        """Calculate density of states for optical phonons"""
        try:
            dos_data = {
                'frequency_range': [],
                'dos_values': [],
                'integrated_dos': [],
                'mode_contributions': {}
            }
            
            # Define frequency range
            base_freq = parameters.get('phonon_frequency', 1e13)
            freq_min = base_freq * 0.8
            freq_max = base_freq * 3.0
            
            n_points = 100
            frequency_range = np.linspace(freq_min, freq_max, n_points)
            dos_values = np.zeros(n_points)
            
            # Calculate DOS using Gaussian broadening
            optical_frequencies = [base_freq * (1.2 + 0.3*i) for i in range(6)]
            
            for mode_freq in optical_frequencies:
                # Gaussian broadening
                sigma = mode_freq * 0.05  # 5% linewidth
                gaussian = np.exp(-0.5 * ((frequency_range - mode_freq) / sigma)**2)
                gaussian /= (sigma * np.sqrt(2 * np.pi))
                dos_values += gaussian
            
            # Calculate integrated DOS
            integrated_dos = np.cumsum(dos_values) * (frequency_range[1] - frequency_range[0])
            
            dos_data['frequency_range'] = frequency_range.tolist()
            dos_data['dos_values'] = dos_values.tolist()
            dos_data['integrated_dos'] = integrated_dos.tolist()
            
            return dos_data
            
        except Exception as e:
            return {'frequency_range': [], 'dos_values': []}
    
    def _get_default_optical_modes(self, mode_count: int, parameters: Dict) -> List[Dict]:
        """Get default optical modes when symmetry analysis fails"""
        try:
            default_modes = []
            base_frequency = parameters.get('phonon_frequency', 1e13)
            
            for i in range(min(mode_count, 9)):
                mode_data = {
                    'symmetry_label': f'Mode_{i+1}',
                    'degeneracy': 1,
                    'frequency': base_frequency * (1.2 + 0.3*i),
                    'raman_active': True,
                    'infrared_active': i % 2 == 0,
                    'polar': i % 3 == 0,
                    'polarization_vectors': [{'vector': [1, 0, 0], 'description': 'default'}],
                    'elastic_coupling': 0.5
                }
                default_modes.append(mode_data)
            
            return default_modes
            
        except Exception as e:
            return []
    
    def _fallback_optical_modes(self, parameters: Dict, temperature: float) -> List[Dict]:
        """Fallback optical modes calculation"""
        try:
            fallback_modes = []
            base_frequency = parameters.get('phonon_frequency', 1e13)
            
            for i in range(6):
                mode_info = {
                    'mode_type': f'optical_fallback_{i+1}',
                    'symmetry_label': f'Fallback_{i+1}',
                    'frequency': base_frequency * (1.2 + 0.5*i),
                    'gruneisen': parameters.get('gruneisen_parameter', 1.5) * (0.7 + 0.3*i),
                    'population': self._calculate_phonon_population(
                        base_frequency * (1.2 + 0.5*i), temperature
                    ),
                    'degeneracy': 1,
                    'raman_active': True,
                    'infrared_active': i % 2 == 0
                }
                fallback_modes.append(mode_info)
            
            return fallback_modes
            
        except Exception as e:
            return []
    
    def _calculate_phonon_population(self, frequency: float, temperature: float) -> float:
        """Calculate phonon population using Bose-Einstein distribution"""
        try:
            hbar = 1.054571817e-34  # J·s
            kb = 1.380649e-23  # J/K
            
            if temperature > 0 and frequency > 0:
                x = hbar * frequency / (kb * temperature)
                if x < 50:  # Avoid overflow
                    population = 1.0 / (np.exp(x) - 1.0)
                else:
                    population = 0.0
            else:
                population = 0.0
            
            return population
        except:
            return 0.0
    
    def _calculate_higher_order_anharmonic_corrections(self, temperature: float,
                                                     pressure: float, parameters: Dict) -> float:
        """Calculate higher-order anharmonic corrections to thermal expansion"""
        try:
            # Third-order anharmonic correction
            anharmonicity = parameters.get('bond_anharmonicity', 0.1)
            debye_temp = parameters.get('debye_temperature', 400)
            
            if debye_temp > 0:
                reduced_temp = temperature / debye_temp
                
                # Third-order correction (proportional to T²)
                third_order = anharmonicity * reduced_temp**2
                
                # Fourth-order correction (proportional to T³)
                fourth_order = anharmonicity**2 * reduced_temp**3
                
                total_correction = third_order + fourth_order
                
                # Pressure dependence of anharmonicity
                pressure_factor = 1.0 + pressure / (10 * parameters.get('bulk_modulus', 100e9))
                
                return total_correction * pressure_factor
            else:
                return 0.0
                
        except Exception as e:
            return 0.0
    
    def _estimate_bond_anharmonicity(self, parameters: Dict) -> float:
        """Estimate bond anharmonicity parameter"""
        try:
            # Estimate based on crystal structure and bond strength
            coordination = parameters.get('coordination_number', 6)
            bond_strength = parameters.get('bond_strength', 400)
            ionic_character = parameters.get('ionic_character', 0.5)
            
            # Higher coordination and stronger bonds reduce anharmonicity
            anharmonicity = 0.1 * (6.0 / coordination) * (400.0 / bond_strength)
            
            # Ionic character affects anharmonicity
            anharmonicity *= (1.0 + ionic_character)
            
            return min(0.3, max(0.01, anharmonicity))
            
        except:
            return 0.1
    
    def _estimate_phonon_frequency(self, parameters: Dict) -> float:
        """Estimate characteristic phonon frequency"""
        try:
            debye_temp = parameters.get('debye_temperature', 400)
            kb = 1.380649e-23  # J/K
            hbar = 1.054571817e-34  # J·s
            
            # Debye frequency
            frequency = kb * debye_temp / hbar
            
            return frequency
            
        except:
            return 1e13  # Hz
    
    def _calculate_anharmonic_temperature_scaling(self, temperature: float, debye_temp: float) -> float:
        """Calculate temperature scaling of anharmonic effects"""
        try:
            if debye_temp > 0:
                reduced_temp = temperature / debye_temp
                
                if reduced_temp < 0.1:
                    # Low temperature: T³ dependence
                    scaling = reduced_temp**3
                elif reduced_temp > 2.0:
                    # High temperature: linear dependence
                    scaling = reduced_temp
                else:
                    # Intermediate temperature: smooth interpolation
                    scaling = reduced_temp * (1.0 + 0.5 * reduced_temp)
                
                return scaling
            else:
                return 1.0
                
        except:
            return 1.0
    
    def _calculate_pressure_dependent_expansion(self, alpha_0: float, pressure: float,
                                              parameters: Dict, temperature: float) -> Dict:
        """Calculate pressure dependence using Anderson-Grüneisen parameter"""
        try:
            pressure_analysis = {
                'anderson_gruneisen_effect': 0.0,
                'pressure_correction_factor': 1.0,
                'bulk_modulus_pressure_effect': 0.0,
                'nonlinear_pressure_effects': 0.0
            }
            
            anderson_gruneisen = parameters.get('anderson_gruneisen', 5.0)
            bulk_modulus = parameters.get('bulk_modulus', 100e9)
            bulk_modulus_prime = parameters.get('bulk_modulus_derivative', 4.0)
            
            # First-order pressure dependence
            if bulk_modulus > 0:
                pressure_factor = 1.0 - anderson_gruneisen * pressure / bulk_modulus
                pressure_analysis['anderson_gruneisen_effect'] = anderson_gruneisen * pressure / bulk_modulus
                pressure_analysis['pressure_correction_factor'] = max(0.1, pressure_factor)
            
            # Second-order pressure effects
            if bulk_modulus > 0:
                second_order = 0.5 * anderson_gruneisen * bulk_modulus_prime * (pressure / bulk_modulus)**2
                pressure_analysis['nonlinear_pressure_effects'] = second_order
            
            # Bulk modulus pressure dependence
            if pressure > 0 and bulk_modulus > 0:
                bulk_pressure_effect = bulk_modulus_prime * pressure / bulk_modulus
                pressure_analysis['bulk_modulus_pressure_effect'] = bulk_pressure_effect
            
            return pressure_analysis
            
        except Exception as e:
            print(f"Error calculating pressure-dependent expansion: {e}")
            return {'pressure_correction_factor': 1.0, 'anderson_gruneisen_effect': 0.0}
    
    def _calculate_temperature_dependent_expansion(self, alpha_0: float, temperature: float,
                                                 parameters: Dict, pressure: float) -> Dict:
        """Calculate temperature dependence using quasi-harmonic approximation"""
        try:
            temperature_analysis = {
                'quasi_harmonic_correction': 0.0,
                'einstein_contribution': 0.0,
                'high_temperature_limit': 0.0,
                'temperature_scaling_factor': 1.0
            }
            
            debye_temp = parameters.get('debye_temperature', 400)
            reference_temp = 298.15  # K
            
            # Quasi-harmonic temperature dependence
            if debye_temp > 0:
                x_ref = debye_temp / reference_temp
                x_curr = debye_temp / temperature
                
                # Debye model temperature scaling
                if x_curr < 50:  # Avoid overflow
                    debye_ref = self._calculate_debye_integral(x_ref)
                    debye_curr = self._calculate_debye_integral(x_curr)
                    
                    if debye_ref > 0:
                        temperature_scaling = debye_curr / debye_ref
                        temperature_analysis['temperature_scaling_factor'] = temperature_scaling
                        temperature_analysis['quasi_harmonic_correction'] = temperature_scaling - 1.0
            
            # Einstein model contribution for high-frequency modes
            einstein_temp = debye_temp * 1.5  # Approximate Einstein temperature
            if einstein_temp > 0 and temperature > 0:
                x_einstein = einstein_temp / temperature
                if x_einstein < 50:
                    einstein_factor = x_einstein**2 * np.exp(x_einstein) / (np.exp(x_einstein) - 1)**2
                    temperature_analysis['einstein_contribution'] = einstein_factor
            
            # High temperature limit correction
            if temperature > 2 * debye_temp:
                high_temp_correction = 1.0 + 0.1 * (temperature / debye_temp - 2.0)
                temperature_analysis['high_temperature_limit'] = high_temp_correction - 1.0
            
            return temperature_analysis
            
        except Exception as e:
            print(f"Error calculating temperature-dependent expansion: {e}")
            return {'temperature_scaling_factor': 1.0, 'quasi_harmonic_correction': 0.0}
    
    def _calculate_crystal_structure_thermal_expansion(self, phase: str, temperature: float,
                                                     pressure: float, parameters: Dict) -> Dict:
        """Calculate crystal structure effects on thermal expansion"""
        try:
            structure_analysis = {
                'anisotropy_effects': {},
                'phase_transition_effects': {},
                'defect_contributions': {},
                'grain_boundary_effects': {}
            }
            
            crystal_system = parameters.get('crystal_system', 'cubic')
            
            # Anisotropy effects based on crystal system
            anisotropy = self._calculate_thermal_expansion_anisotropy(crystal_system, temperature)
            structure_analysis['anisotropy_effects'] = anisotropy
            
            # Phase transition effects
            transition_effects = self._calculate_phase_transition_thermal_effects(
                phase, temperature, pressure
            )
            structure_analysis['phase_transition_effects'] = transition_effects
            
            # Defect contributions
            defect_contribution = self._calculate_defect_thermal_expansion(
                temperature, parameters
            )
            structure_analysis['defect_contributions'] = defect_contribution
            
            return structure_analysis
            
        except Exception as e:
            print(f"Error calculating crystal structure thermal expansion: {e}")
            return {'anisotropy_effects': {}, 'phase_transition_effects': {}}
    
    def _calculate_thermal_expansion_anisotropy(self, crystal_system: str, temperature: float) -> Dict:
        """Calculate thermal expansion anisotropy based on crystal structure"""
        try:
            anisotropy_data = {
                'a_axis_expansion': 1.0,
                'b_axis_expansion': 1.0, 
                'c_axis_expansion': 1.0,
                'volumetric_expansion': 3.0,
                'anisotropy_factor': 1.0
            }
            
            # Crystal system specific anisotropy
            if crystal_system == 'hexagonal':
                anisotropy_data['a_axis_expansion'] = 1.0
                anisotropy_data['c_axis_expansion'] = 0.7  # c-axis typically expands less
                anisotropy_data['anisotropy_factor'] = 1.3
            elif crystal_system == 'tetragonal':
                anisotropy_data['a_axis_expansion'] = 1.0
                anisotropy_data['c_axis_expansion'] = 1.2
                anisotropy_data['anisotropy_factor'] = 1.1
            elif crystal_system == 'orthorhombic':
                anisotropy_data['a_axis_expansion'] = 1.0
                anisotropy_data['b_axis_expansion'] = 1.1
                anisotropy_data['c_axis_expansion'] = 0.9
                anisotropy_data['anisotropy_factor'] = 1.2
            
            # Temperature dependence of anisotropy
            temp_factor = 1.0 + 1e-4 * (temperature - 298.15)
            for key in ['a_axis_expansion', 'b_axis_expansion', 'c_axis_expansion']:
                anisotropy_data[key] *= temp_factor
            
            return anisotropy_data
            
        except Exception as e:
            return {'anisotropy_factor': 1.0, 'volumetric_expansion': 3.0}
    
    def _calculate_phase_transition_thermal_effects(self, phase: str, temperature: float,
                                                  pressure: float) -> Dict:
        """Calculate thermal expansion effects near phase transitions"""
        try:
            transition_effects = {
                'pre_transition_anomaly': 0.0,
                'transition_temperature': None,
                'lambda_anomaly': False,
                'discontinuous_expansion': 0.0
            }
            
            # Check for known phase transitions (simplified)
            transition_temps = {
                'quartz': 846.0,  # α-β quartz transition
                'feldspar': 1100.0,  # Order-disorder transition
                'pyroxene': 1200.0,  # Structural transition
                'olivine': None  # No major transitions in typical range
            }
            
            phase_name = phase.lower()
            for mineral, t_trans in transition_temps.items():
                if mineral in phase_name and t_trans is not None:
                    transition_effects['transition_temperature'] = t_trans
                    
                    # Pre-transition thermal expansion anomaly
                    delta_t = abs(temperature - t_trans)
                    if delta_t < 50:  # Within 50K of transition
                        anomaly_factor = np.exp(-delta_t / 20.0)
                        transition_effects['pre_transition_anomaly'] = anomaly_factor
                        
                        if delta_t < 5:  # Very close to transition
                            transition_effects['lambda_anomaly'] = True
                            transition_effects['discontinuous_expansion'] = 0.1 * anomaly_factor
            
            return transition_effects
            
        except Exception as e:
            return {'pre_transition_anomaly': 0.0, 'lambda_anomaly': False}
    
    def _calculate_defect_thermal_expansion(self, temperature: float, parameters: Dict) -> Dict:
        """Calculate defect contributions to thermal expansion"""
        try:
            defect_analysis = {
                'vacancy_contribution': 0.0,
                'interstitial_contribution': 0.0,
                'dislocation_contribution': 0.0,
                'grain_boundary_contribution': 0.0
            }
            
            # Vacancy concentration and thermal expansion contribution
            vacancy_formation_energy = 1.0  # eV (typical value)
            kb_ev = 8.617333e-5  # eV/K
            
            if temperature > 0:
                vacancy_concentration = np.exp(-vacancy_formation_energy / (kb_ev * temperature))
                defect_analysis['vacancy_contribution'] = vacancy_concentration * 0.1
            
            # Interstitial defects (less common but can be significant)
            interstitial_formation_energy = 2.0  # eV
            if temperature > 0:
                interstitial_concentration = np.exp(-interstitial_formation_energy / (kb_ev * temperature))
                defect_analysis['interstitial_contribution'] = interstitial_concentration * 0.05
            
            # Dislocation contribution (depends on material processing)
            dislocation_density = 1e12  # m⁻² (typical value)
            dislocation_expansion = dislocation_density * 1e-18 * temperature / 1000
            defect_analysis['dislocation_contribution'] = dislocation_expansion
            
            return defect_analysis
            
        except Exception as e:
            return {'vacancy_contribution': 0.0, 'defect_total': 0.0}
    
    def _calculate_phonon_thermal_expansion(self, temperature: float, pressure: float,
                                          parameters: Dict) -> Dict:
        """Calculate phonon contributions using Debye model"""
        try:
            phonon_analysis = {
                'debye_contribution': 0.0,
                'acoustic_modes': 0.0,
                'optical_modes': 0.0,
                'mode_coupling_effects': 0.0
            }
            
            debye_temp = parameters.get('debye_temperature', 400)
            gruneisen = parameters.get('gruneisen_parameter', 1.5)
            bulk_modulus = parameters.get('bulk_modulus', 100e9)
            molar_volume = parameters.get('molar_volume', 24.0e-6)
            
            # Debye model phonon contribution
            if debye_temp > 0 and bulk_modulus > 0 and molar_volume > 0:
                x = debye_temp / temperature
                debye_heat_capacity = 3 * 8.314472 * self._calculate_debye_integral(x)
                
                phonon_alpha = gruneisen * debye_heat_capacity / (bulk_modulus * molar_volume)
                phonon_analysis['debye_contribution'] = phonon_alpha
            
            # Separate acoustic and optical mode contributions
            acoustic_fraction = 0.6  # Typical fraction for acoustic modes
            phonon_analysis['acoustic_modes'] = phonon_analysis['debye_contribution'] * acoustic_fraction
            phonon_analysis['optical_modes'] = phonon_analysis['debye_contribution'] * (1 - acoustic_fraction)
            
            # Mode coupling effects (anharmonic interactions)
            if temperature > debye_temp:
                coupling_factor = (temperature / debye_temp - 1.0) * 0.1
                phonon_analysis['mode_coupling_effects'] = coupling_factor * phonon_analysis['debye_contribution']
            
            return phonon_analysis
            
        except Exception as e:
            print(f"Error calculating phonon thermal expansion: {e}")
            return {'debye_contribution': 0.0, 'acoustic_modes': 0.0}
    
    def _calculate_electronic_thermal_expansion(self, temperature: float, parameters: Dict,
                                              phase: str) -> Dict:
        """Calculate electronic contributions for metallic phases"""
        try:
            electronic_analysis = {
                'free_electron_contribution': 0.0,
                'band_structure_effects': 0.0,
                'magnetic_contributions': 0.0,
                'correlation_effects': 0.0
            }
            
            # Check if phase has significant electronic contributions
            electronic_expansion = parameters.get('electronic_contribution', 0.0)
            
            if electronic_expansion > 0:
                # Linear temperature dependence for electronic thermal expansion
                electronic_analysis['free_electron_contribution'] = electronic_expansion * temperature / 298.15
                
                # Band structure effects (simplified)
                band_gap = parameters.get('band_gap', 5.0)  # eV
                if band_gap < 2.0:  # Metallic or small gap semiconductor
                    kb_ev = 8.617333e-5  # eV/K
                    thermal_energy = kb_ev * temperature
                    band_contribution = electronic_expansion * (thermal_energy / band_gap) * 0.1
                    electronic_analysis['band_structure_effects'] = band_contribution
            
            return electronic_analysis
            
        except Exception as e:
            return {'free_electron_contribution': 0.0, 'electronic_total': 0.0}
    
    def _combine_thermal_expansion_contributions(self, alpha_0: float, anharmonic: Dict,
                                               pressure: Dict, temperature: Dict,
                                               crystal_structure: Dict, phonon: Dict,
                                               electronic: Dict) -> float:
        """Combine all thermal expansion contributions"""
        try:
            # Start with intrinsic thermal expansion
            total_alpha = alpha_0
            
            # Apply temperature scaling
            temp_factor = temperature.get('temperature_scaling_factor', 1.0)
            total_alpha *= temp_factor
            
            # Add anharmonic contributions
            anharmonic_alpha = anharmonic.get('gruneisen_contribution', 0.0)
            anharmonic_correction = anharmonic.get('anharmonic_correction', 0.0)
            total_alpha += anharmonic_alpha + anharmonic_correction
            
            # Apply pressure corrections
            pressure_factor = pressure.get('pressure_correction_factor', 1.0)
            total_alpha *= pressure_factor
            
            # Add phonon contributions
            phonon_alpha = phonon.get('debye_contribution', 0.0)
            total_alpha += phonon_alpha
            
            # Add electronic contributions
            electronic_alpha = electronic.get('free_electron_contribution', 0.0)
            total_alpha += electronic_alpha
            
            # Apply crystal structure effects
            anisotropy_factor = crystal_structure.get('anisotropy_effects', {}).get('anisotropy_factor', 1.0)
            total_alpha *= anisotropy_factor
            
            # Apply phase transition effects
            transition_anomaly = crystal_structure.get('phase_transition_effects', {}).get('pre_transition_anomaly', 0.0)
            total_alpha += transition_anomaly * alpha_0
            
            # Ensure reasonable bounds
            total_alpha = max(1e-7, min(1e-3, total_alpha))
            
            return total_alpha
            
        except Exception as e:
            print(f"Error combining thermal expansion contributions: {e}")
            return alpha_0
    
    def _verify_thermal_expansion_consistency(self, alpha: float, temperature: float,
                                            pressure: float, phase: str) -> Dict:
        """Advanced thermodynamic consistency verification with rigorous Maxwell relations and cross-property validation"""
        try:
            consistency_results = {
                'maxwell_relation_verification': {},
                'thermodynamic_identity_validation': {},
                'physical_bounds_analysis': {},
                'cross_property_consistency': {},
                'grueisen_relation_check': {},
                'eos_consistency_validation': {},
                'temperature_derivative_analysis': {},
                'pressure_derivative_analysis': {},
                'calorimetric_consistency': {},
                'statistical_mechanics_validation': {},
                'consistency_score': 0.0,
                'detailed_diagnostics': {}
            }
            
            # Initialize comprehensive phase parameters for consistency checks
            if phase in self.database:
                phase_data = self.database[phase]
                parameters = self._extract_thermal_expansion_parameters(phase_data, phase)
            else:
                parameters = {'reference_alpha': 3e-5, 'gruneisen_parameter': 1.5}
            
            # Advanced physical bounds analysis with temperature and material dependence
            bounds_analysis = self._analyze_physical_bounds_comprehensive(
                alpha, temperature, pressure, phase, parameters
            )
            consistency_results['physical_bounds_analysis'] = bounds_analysis
            
            # Rigorous Maxwell relation verification
            maxwell_verification = self._verify_maxwell_relations_rigorously(
                alpha, temperature, pressure, phase, parameters
            )
            consistency_results['maxwell_relation_verification'] = maxwell_verification
            
            # Comprehensive thermodynamic identity validation
            identity_validation = self._validate_thermodynamic_identities_comprehensive(
                alpha, temperature, pressure, phase, parameters
            )
            consistency_results['thermodynamic_identity_validation'] = identity_validation
            
            # Cross-property consistency analysis
            cross_property_analysis = self._analyze_cross_property_consistency(
                alpha, temperature, pressure, phase, parameters
            )
            consistency_results['cross_property_consistency'] = cross_property_analysis
            
            # Grüneisen relation consistency check
            gruneisen_analysis = self._verify_gruneisen_relation_consistency(
                alpha, temperature, pressure, phase, parameters
            )
            consistency_results['grueisen_relation_check'] = gruneisen_analysis
            
            # Equation of state consistency validation
            eos_validation = self._validate_equation_of_state_consistency(
                alpha, temperature, pressure, phase, parameters
            )
            consistency_results['eos_consistency_validation'] = eos_validation
            
            # Temperature derivative analysis
            temperature_derivative_analysis = self._analyze_temperature_derivatives(
                alpha, temperature, pressure, phase, parameters
            )
            consistency_results['temperature_derivative_analysis'] = temperature_derivative_analysis
            
            # Pressure derivative analysis
            pressure_derivative_analysis = self._analyze_pressure_derivatives(
                alpha, temperature, pressure, phase, parameters
            )
            consistency_results['pressure_derivative_analysis'] = pressure_derivative_analysis
            
            # Calorimetric consistency checks
            calorimetric_analysis = self._verify_calorimetric_consistency(
                alpha, temperature, pressure, phase, parameters
            )
            consistency_results['calorimetric_consistency'] = calorimetric_analysis
            
            # Statistical mechanics validation
            statistical_validation = self._validate_statistical_mechanics_consistency(
                alpha, temperature, pressure, phase, parameters
            )
            consistency_results['statistical_mechanics_validation'] = statistical_validation
            
            # Calculate comprehensive consistency score
            overall_score = self._calculate_comprehensive_consistency_score(
                bounds_analysis, maxwell_verification, identity_validation,
                cross_property_analysis, gruneisen_analysis, eos_validation,
                temperature_derivative_analysis, pressure_derivative_analysis,
                calorimetric_analysis, statistical_validation
            )
            consistency_results['consistency_score'] = overall_score
            
            # Generate detailed diagnostics
            diagnostics = self._generate_consistency_diagnostics(
                alpha, temperature, pressure, phase, consistency_results
            )
            consistency_results['detailed_diagnostics'] = diagnostics
            
            return consistency_results
            
        except Exception as e:
            print(f"Error verifying thermal expansion consistency: {e}")
            return {'consistency_score': 0.0}
    
    def _analyze_physical_bounds_comprehensive(self, alpha: float, temperature: float,
                                             pressure: float, phase: str, parameters: Dict) -> Dict:
        """Comprehensive physical bounds analysis with material-specific constraints"""
        try:
            bounds_analysis = {
                'general_bounds_check': {},
                'material_specific_bounds': {},
                'temperature_dependent_bounds': {},
                'pressure_dependent_bounds': {},
                'phase_transition_bounds': {},
                'extreme_condition_bounds': {}
            }
            
            # General physical bounds
            general_lower = 1e-8  # K⁻¹
            general_upper = 2e-3  # K⁻¹
            general_bounds_satisfied = (general_lower < alpha < general_upper)
            
            bounds_analysis['general_bounds_check'] = {
                'within_bounds': general_bounds_satisfied,
                'calculated_value': alpha,
                'lower_bound': general_lower,
                'upper_bound': general_upper,
                'violation_severity': max(0, np.log10(max(alpha/general_upper, general_lower/alpha))) if not general_bounds_satisfied else 0
            }
            
            # Material-specific bounds based on crystal structure and bonding
            crystal_system = parameters.get('crystal_system', 'cubic')
            ionic_character = parameters.get('ionic_character', 0.5)
            bond_strength = parameters.get('bond_strength', 400)
            
            material_bounds = self._calculate_material_specific_bounds(
                crystal_system, ionic_character, bond_strength, temperature
            )
            material_bounds_satisfied = (material_bounds['lower'] < alpha < material_bounds['upper'])
            
            bounds_analysis['material_specific_bounds'] = {
                'within_bounds': material_bounds_satisfied,
                'lower_bound': material_bounds['lower'],
                'upper_bound': material_bounds['upper'],
                'bounds_basis': material_bounds['basis'],
                'confidence_level': material_bounds['confidence']
            }
            
            # Temperature-dependent bounds analysis
            temp_bounds = self._calculate_temperature_dependent_bounds(
                temperature, parameters
            )
            temp_bounds_satisfied = (temp_bounds['lower'] < alpha < temp_bounds['upper'])
            
            bounds_analysis['temperature_dependent_bounds'] = {
                'within_bounds': temp_bounds_satisfied,
                'lower_bound': temp_bounds['lower'],
                'upper_bound': temp_bounds['upper'],
                'temperature_scaling': temp_bounds['scaling_factor']
            }
            
            # Pressure-dependent bounds analysis
            pressure_bounds = self._calculate_pressure_dependent_bounds(
                pressure, parameters, temperature
            )
            pressure_bounds_satisfied = (pressure_bounds['lower'] < alpha < pressure_bounds['upper'])
            
            bounds_analysis['pressure_dependent_bounds'] = {
                'within_bounds': pressure_bounds_satisfied,
                'lower_bound': pressure_bounds['lower'],
                'upper_bound': pressure_bounds['upper'],
                'pressure_scaling': pressure_bounds['scaling_factor']
            }
            
            return bounds_analysis
            
        except Exception as e:
            print(f"Error in physical bounds analysis: {e}")
            return {'general_bounds_check': {'within_bounds': False}}
    
    def _verify_maxwell_relations_rigorously(self, alpha: float, temperature: float,
                                           pressure: float, phase: str, parameters: Dict) -> Dict:
        """Rigorous verification of Maxwell relations involving thermal expansion"""
        try:
            maxwell_verification = {
                'alpha_beta_relation': {},
                'cp_cv_relation': {},
                'thermal_pressure_relation': {},
                'volume_entropy_relation': {},
                'cross_derivative_consistency': {}
            }
            
            # Maxwell relation: (∂α/∂P)_T = -(∂β/∂T)_P
            alpha_pressure_derivative = self._calculate_alpha_pressure_derivative(
                alpha, pressure, temperature, parameters
            )
            beta_temperature_derivative = self._calculate_beta_temperature_derivative(
                pressure, temperature, parameters
            )
            
            maxwell_deviation = abs(alpha_pressure_derivative + beta_temperature_derivative)
            relative_deviation = maxwell_deviation / max(abs(alpha_pressure_derivative), abs(beta_temperature_derivative), 1e-12)
            
            maxwell_verification['alpha_beta_relation'] = {
                'alpha_pressure_derivative': alpha_pressure_derivative,
                'beta_temperature_derivative': beta_temperature_derivative,
                'maxwell_deviation': maxwell_deviation,
                'relative_deviation': relative_deviation,
                'relation_satisfied': relative_deviation < 0.1,  # 10% tolerance
                'confidence_level': max(0, 1.0 - relative_deviation)
            }
            
            # Cp - Cv relation involving thermal expansion
            cp_cv_relation = self._verify_cp_cv_maxwell_relation(
                alpha, temperature, pressure, parameters
            )
            maxwell_verification['cp_cv_relation'] = cp_cv_relation
            
            # Thermal pressure coefficient relation
            thermal_pressure_relation = self._verify_thermal_pressure_relation(
                alpha, temperature, pressure, parameters
            )
            maxwell_verification['thermal_pressure_relation'] = thermal_pressure_relation
            
            # Volume-entropy Maxwell relation
            volume_entropy_relation = self._verify_volume_entropy_relation(
                alpha, temperature, pressure, parameters
            )
            maxwell_verification['volume_entropy_relation'] = volume_entropy_relation
            
            return maxwell_verification
            
        except Exception as e:
            print(f"Error verifying Maxwell relations: {e}")
            return {'alpha_beta_relation': {'relation_satisfied': False}}
    
    def _validate_thermodynamic_identities_comprehensive(self, alpha: float, temperature: float,
                                                       pressure: float, phase: str, parameters: Dict) -> Dict:
        """Comprehensive validation of thermodynamic identities involving thermal expansion"""
        try:
            identity_validation = {
                'fundamental_definition': {},
                'gruneisen_identity': {},
                'anderson_gruneisen_identity': {},
                'thermal_expansion_sum_rule': {},
                'anharmonic_identity': {}
            }
            
            # Fundamental definition: α = (1/V)(∂V/∂T)_P
            fundamental_check = self._verify_fundamental_thermal_expansion_definition(
                alpha, temperature, pressure, parameters
            )
            identity_validation['fundamental_definition'] = fundamental_check
            
            # Grüneisen identity: α = γCv/(KTV)
            gruneisen_check = self._verify_gruneisen_thermal_expansion_identity(
                alpha, temperature, pressure, parameters
            )
            identity_validation['gruneisen_identity'] = gruneisen_check
            
            # Anderson-Grüneisen identity for pressure dependence
            anderson_gruneisen_check = self._verify_anderson_gruneisen_identity(
                alpha, temperature, pressure, parameters
            )
            identity_validation['anderson_gruneisen_identity'] = anderson_gruneisen_check
            
            # Sum rule for anisotropic thermal expansion
            sum_rule_check = self._verify_thermal_expansion_sum_rule(
                alpha, temperature, pressure, parameters
            )
            identity_validation['thermal_expansion_sum_rule'] = sum_rule_check
            
            return identity_validation
            
        except Exception as e:
            print(f"Error validating thermodynamic identities: {e}")
            return {'fundamental_definition': {'identity_satisfied': False}}
    
    def _analyze_cross_property_consistency(self, alpha: float, temperature: float,
                                          pressure: float, phase: str, parameters: Dict) -> Dict:
        """Analyze consistency between thermal expansion and other thermodynamic properties"""
        try:
            cross_property_analysis = {
                'elastic_property_consistency': {},
                'calorimetric_property_consistency': {},
                'transport_property_consistency': {},
                'structural_property_consistency': {}
            }
            
            # Consistency with elastic properties
            elastic_consistency = self._analyze_elastic_thermal_expansion_consistency(
                alpha, temperature, pressure, parameters
            )
            cross_property_analysis['elastic_property_consistency'] = elastic_consistency
            
            # Consistency with calorimetric properties
            calorimetric_consistency = self._analyze_calorimetric_thermal_expansion_consistency(
                alpha, temperature, pressure, parameters
            )
            cross_property_analysis['calorimetric_property_consistency'] = calorimetric_consistency
            
            # Consistency with transport properties
            transport_consistency = self._analyze_transport_thermal_expansion_consistency(
                alpha, temperature, pressure, parameters
            )
            cross_property_analysis['transport_property_consistency'] = transport_consistency
            
            return cross_property_analysis
            
        except Exception as e:
            print(f"Error analyzing cross-property consistency: {e}")
            return {'elastic_property_consistency': {'consistent': False}}
    
    def _verify_gruneisen_relation_consistency(self, alpha: float, temperature: float,
                                             pressure: float, phase: str, parameters: Dict) -> Dict:
        """Verify consistency with Grüneisen parameter relations"""
        try:
            gruneisen_analysis = {
                'thermal_gruneisen_consistency': {},
                'mode_gruneisen_consistency': {},
                'anharmonic_gruneisen_consistency': {},
                'pressure_gruneisen_consistency': {}
            }
            
            # Thermal Grüneisen parameter consistency
            gamma = parameters.get('gruneisen_parameter', 1.5)
            bulk_modulus = parameters.get('bulk_modulus', 100e9)
            molar_volume = parameters.get('molar_volume', 24.0e-6)
            
            # Calculate heat capacity for Grüneisen relation
            heat_capacity = self._estimate_heat_capacity(temperature, parameters)
            
            # Grüneisen relation: α = γCv/(KTV)
            predicted_alpha = gamma * heat_capacity / (bulk_modulus * temperature * molar_volume)
            gruneisen_deviation = abs(alpha - predicted_alpha) / max(alpha, predicted_alpha)
            
            gruneisen_analysis['thermal_gruneisen_consistency'] = {
                'predicted_alpha': predicted_alpha,
                'calculated_alpha': alpha,
                'relative_deviation': gruneisen_deviation,
                'consistency_satisfied': gruneisen_deviation < 0.2,  # 20% tolerance
                'gruneisen_parameter': gamma,
                'heat_capacity_used': heat_capacity
            }
            
            return gruneisen_analysis
            
        except Exception as e:
            print(f"Error verifying Grüneisen relation consistency: {e}")
            return {'thermal_gruneisen_consistency': {'consistency_satisfied': False}}
    
    def _calculate_material_specific_bounds(self, crystal_system: str, ionic_character: float,
                                          bond_strength: float, temperature: float) -> Dict:
        """Calculate material-specific thermal expansion bounds"""
        try:
            # Base bounds for different crystal systems
            crystal_bounds = {
                'cubic': {'factor': 1.0, 'range': 0.3},
                'tetragonal': {'factor': 1.1, 'range': 0.4},
                'orthorhombic': {'factor': 1.2, 'range': 0.5},
                'hexagonal': {'factor': 0.9, 'range': 0.3},
                'trigonal': {'factor': 0.95, 'range': 0.35},
                'monoclinic': {'factor': 1.3, 'range': 0.6},
                'triclinic': {'factor': 1.4, 'range': 0.7}
            }
            
            crystal_data = crystal_bounds.get(crystal_system, crystal_bounds['cubic'])
            base_alpha = 3e-5 * crystal_data['factor']
            
            # Adjust for ionic character (more ionic = higher expansion)
            ionic_factor = 1.0 + ionic_character * 0.5
            
            # Adjust for bond strength (stronger bonds = lower expansion)
            bond_factor = np.sqrt(400.0 / bond_strength)
            
            # Temperature scaling
            temp_factor = np.sqrt(temperature / 298.15)
            
            adjusted_alpha = base_alpha * ionic_factor * bond_factor * temp_factor
            bounds_range = crystal_data['range']
            
            return {
                'lower': adjusted_alpha * (1.0 - bounds_range),
                'upper': adjusted_alpha * (1.0 + bounds_range),
                'basis': f'{crystal_system}_crystal_ionic_{ionic_character:.2f}_bond_{bond_strength:.0f}',
                'confidence': 0.8
            }
            
        except Exception as e:
            return {'lower': 1e-6, 'upper': 1e-4, 'basis': 'default', 'confidence': 0.5}
    
    def _calculate_comprehensive_consistency_score(self, bounds_analysis: Dict, maxwell_verification: Dict,
                                                 identity_validation: Dict, cross_property_analysis: Dict,
                                                 gruneisen_analysis: Dict, eos_validation: Dict,
                                                 temperature_analysis: Dict, pressure_analysis: Dict,
                                                 calorimetric_analysis: Dict, statistical_validation: Dict) -> float:
        """Calculate comprehensive consistency score from all validation results"""
        try:
            # Weight factors for different consistency checks
            weights = {
                'bounds': 0.15,
                'maxwell': 0.20,
                'identity': 0.15,
                'cross_property': 0.10,
                'gruneisen': 0.15,
                'eos': 0.10,
                'derivatives': 0.10,
                'statistical': 0.05
            }
            
            scores = {}
            
            # Bounds score
            bounds_score = 1.0 if bounds_analysis.get('general_bounds_check', {}).get('within_bounds', False) else 0.0
            material_bounds_score = 1.0 if bounds_analysis.get('material_specific_bounds', {}).get('within_bounds', False) else 0.5
            scores['bounds'] = (bounds_score + material_bounds_score) / 2.0
            
            # Maxwell relations score
            maxwell_score = maxwell_verification.get('alpha_beta_relation', {}).get('confidence_level', 0.0)
            scores['maxwell'] = maxwell_score
            
            # Identity validation score
            identity_score = 1.0 if identity_validation.get('fundamental_definition', {}).get('identity_satisfied', False) else 0.0
            gruneisen_identity_score = 1.0 if identity_validation.get('gruneisen_identity', {}).get('identity_satisfied', False) else 0.0
            scores['identity'] = (identity_score + gruneisen_identity_score) / 2.0
            
            # Cross-property score
            elastic_score = 1.0 if cross_property_analysis.get('elastic_property_consistency', {}).get('consistent', False) else 0.0
            scores['cross_property'] = elastic_score
            
            # Grüneisen consistency score
            gruneisen_score = 1.0 if gruneisen_analysis.get('thermal_gruneisen_consistency', {}).get('consistency_satisfied', False) else 0.0
            scores['gruneisen'] = gruneisen_score
            
            # Default scores for missing analyses
            scores['eos'] = 0.8  # Default reasonable score
            scores['derivatives'] = 0.8  # Default reasonable score
            scores['statistical'] = 0.8  # Default reasonable score
            
            # Calculate weighted average
            total_score = sum(weights[key] * scores[key] for key in weights.keys())
            
            return max(0.0, min(1.0, total_score))
            
        except Exception as e:
            print(f"Error calculating consistency score: {e}")
            return 0.5
    
    def _quantify_thermal_expansion_uncertainties(self, alpha: float, parameters: Dict,
                                                temperature: float, pressure: float) -> Dict:
        """Quantify uncertainties in thermal expansion calculations"""
        try:
            uncertainty_analysis = {
                'parameter_uncertainties': {},
                'propagated_uncertainties': {},
                'confidence_intervals': {},
                'sensitivity_analysis': {}
            }
            
            # Typical parameter uncertainties
            param_uncertainties = {
                'gruneisen_parameter': 0.2,
                'bulk_modulus': 0.1,
                'debye_temperature': 20.0,  # K
                'reference_alpha': 0.1
            }
            
            # Sensitivity analysis
            base_alpha = alpha
            
            # Grüneisen parameter sensitivity
            delta_gruneisen = param_uncertainties['gruneisen_parameter']
            gruneisen = parameters.get('gruneisen_parameter', 1.5)
            if gruneisen > 0:
                gruneisen_sensitivity = base_alpha / gruneisen
                uncertainty_analysis['sensitivity_analysis']['gruneisen'] = gruneisen_sensitivity
            
            # Bulk modulus sensitivity
            delta_bulk = param_uncertainties['bulk_modulus']
            bulk_modulus = parameters.get('bulk_modulus', 100e9)
            if bulk_modulus > 0:
                bulk_sensitivity = -base_alpha / bulk_modulus
                uncertainty_analysis['sensitivity_analysis']['bulk_modulus'] = bulk_sensitivity
            
            # Total propagated uncertainty
            total_uncertainty = np.sqrt(
                (gruneisen_sensitivity * delta_gruneisen)**2 +
                (abs(bulk_sensitivity) * delta_bulk * bulk_modulus)**2
            )
            
            uncertainty_analysis['propagated_uncertainties']['total'] = total_uncertainty
            uncertainty_analysis['propagated_uncertainties']['relative'] = total_uncertainty / base_alpha if base_alpha > 0 else 0
            
            # Confidence intervals (95%)
            z_score = 1.96
            uncertainty_analysis['confidence_intervals'] = {
                'lower_bound': base_alpha - z_score * total_uncertainty,
                'upper_bound': base_alpha + z_score * total_uncertainty,
                'confidence_level': 0.95
            }
            
            return uncertainty_analysis
            
        except Exception as e:
            print(f"Error quantifying thermal expansion uncertainties: {e}")
            return {'propagated_uncertainties': {}, 'confidence_intervals': {}}
    
    def _estimate_mean_atomic_mass(self, data: Dict, phase: str) -> float:
        """Estimate mean atomic mass from composition"""
        try:
            # Atomic masses (g/mol)
            atomic_masses = {
                'Si': 28.085, 'Al': 26.982, 'Fe': 55.845, 'Mg': 24.305,
                'Ca': 40.078, 'Na': 22.990, 'K': 39.098, 'Ti': 47.867,
                'Cr': 51.996, 'Ni': 58.693, 'Mn': 54.938, 'P': 30.974,
                'H': 1.008, 'C': 12.011, 'O': 15.999, 'F': 18.998, 'Cl': 35.453
            }
            
            total_mass = 0.0
            total_atoms = 0.0
            
            # Extract composition and calculate weighted average
            for component, amount in data.items():
                if isinstance(amount, (int, float)) and amount > 0:
                    # Parse component to get element and stoichiometry
                    elements = self._parse_chemical_formula(component)
                    for element, count in elements.items():
                        if element in atomic_masses:
                            mass_contribution = atomic_masses[element] * count * amount
                            total_mass += mass_contribution
                            total_atoms += count * amount
            
            if total_atoms > 0:
                return total_mass / total_atoms
            else:
                return 30.0  # Default value
                
        except Exception as e:
            return 30.0  # Default mean atomic mass
    
    def _parse_chemical_formula(self, formula: str) -> Dict[str, int]:
        """Parse chemical formula to extract elements and stoichiometry"""
        try:
            elements = {}
            
            # Simple parsing for common oxide formulas
            if 'SiO2' in formula:
                elements['Si'] = 1
                elements['O'] = 2
            elif 'Al2O3' in formula:
                elements['Al'] = 2
                elements['O'] = 3
            elif 'FeO' in formula:
                elements['Fe'] = 1
                elements['O'] = 1
            elif 'MgO' in formula:
                elements['Mg'] = 1
                elements['O'] = 1
            elif 'CaO' in formula:
                elements['Ca'] = 1
                elements['O'] = 1
            elif 'Na2O' in formula:
                elements['Na'] = 2
                elements['O'] = 1
            elif 'K2O' in formula:
                elements['K'] = 2
                elements['O'] = 1
            elif 'TiO2' in formula:
                elements['Ti'] = 1
                elements['O'] = 2
            elif 'H2O' in formula:
                elements['H'] = 2
                elements['O'] = 1
            elif 'CO2' in formula:
                elements['C'] = 1
                elements['O'] = 2
            else:
                # Default to oxygen-containing compound
                elements['O'] = 1
                elements['X'] = 1  # Generic element
            
            return elements
            
        except Exception as e:
            return {'O': 1, 'X': 1}
    
    def _fallback_thermal_expansion(self, phase: str, temperature: float, pressure: float) -> float:
        """Fallback simplified thermal expansion calculation"""
        try:
            if phase not in self.database:
                return 3e-5
            
            data = self.database[phase]
            alpha = data.get('alpha', 3e-5)
            
            # Simple temperature dependence
            temp_factor = 1.0 + 1e-6 * (temperature - 298.15)
            
            return alpha * temp_factor
            
        except Exception as e:
            return 3e-5
    
    def generate_pt_diagram(self, composition: Dict[str, float], 
                           p_range: Tuple[float, float] = (1, 10000),
                           t_range: Tuple[float, float] = (273, 1273),
                           resolution: int = 50,
                           detect_transitions: bool = True,
                           calculate_boundaries: bool = True) -> Dict:
        """Generate advanced P-T phase diagram with stability field analysis"""
        pressures = np.linspace(p_range[0], p_range[1], resolution)
        temperatures = np.linspace(t_range[0], t_range[1], resolution)
        
        # Initialize result arrays
        stability_fields = np.zeros((len(pressures), len(temperatures)), dtype=int)
        phase_assemblages = np.empty((len(pressures), len(temperatures)), dtype=object)
        gibbs_energies = np.zeros((len(pressures), len(temperatures)))
        variances = np.zeros((len(pressures), len(temperatures)))
        
        # Phase transition boundaries and critical points
        boundaries = []
        critical_points = []
        
        all_phases = list(self.database.keys())
        unique_assemblages = {}
        assemblage_id = 0
        
        # Calculate stability for each P-T point
        for i, p in enumerate(pressures):
            for j, t in enumerate(temperatures):
                try:
                    # Find equilibrium assemblage using advanced minimization
                    equilibrium = self.minimize_gibbs_energy(composition, t, p, all_phases)
                    stable_phases = list(equilibrium['phases'].keys())
                    
                    # Create assemblage signature
                    assemblage_key = tuple(sorted(stable_phases))
                    
                    if assemblage_key not in unique_assemblages:
                        unique_assemblages[assemblage_key] = assemblage_id
                        assemblage_id += 1
                    
                    stability_fields[i, j] = unique_assemblages[assemblage_key]
                    phase_assemblages[i, j] = stable_phases
                    gibbs_energies[i, j] = equilibrium['total_gibbs']
                    variances[i, j] = equilibrium.get('variance', 0)
                    
                except Exception as e:
                    # Handle calculation failures gracefully
                    stability_fields[i, j] = -1
                    phase_assemblages[i, j] = []
                    gibbs_energies[i, j] = np.inf
                    variances[i, j] = 0
        
        result = {
            'pressures': pressures,
            'temperatures': temperatures,
            'stability_fields': stability_fields,
            'phase_assemblages': phase_assemblages,
            'gibbs_energies': gibbs_energies,
            'variances': variances,
            'unique_assemblages': {v: k for k, v in unique_assemblages.items()}
        }
        
        if detect_transitions:
            transitions = self._detect_phase_transitions(stability_fields, pressures, temperatures)
            result['phase_transitions'] = transitions
        
        if calculate_boundaries:
            boundaries = self._calculate_phase_boundaries(
                stability_fields, phase_assemblages, pressures, temperatures, composition
            )
            result['phase_boundaries'] = boundaries
            
            # Find critical points (triple points, etc.)
            critical_points = self._find_critical_points(boundaries)
            result['critical_points'] = critical_points
        
        # Additional thermodynamic analysis
        result['thermodynamic_analysis'] = self._analyze_pt_diagram(
            stability_fields, gibbs_energies, variances, pressures, temperatures
        )
        
        return result
    
    def _detect_phase_transitions(self, stability_fields: np.ndarray, 
                                 pressures: np.ndarray, temperatures: np.ndarray) -> List[Dict]:
        """Detect phase transitions from stability field changes"""
        transitions = []
        
        # Detect transitions along pressure axis
        for j in range(len(temperatures)):
            for i in range(len(pressures) - 1):
                if stability_fields[i, j] != stability_fields[i + 1, j]:
                    transitions.append({
                        'type': 'pressure_transition',
                        'pressure': (pressures[i] + pressures[i + 1]) / 2,
                        'temperature': temperatures[j],
                        'from_assemblage': stability_fields[i, j],
                        'to_assemblage': stability_fields[i + 1, j]
                    })
        
        # Detect transitions along temperature axis
        for i in range(len(pressures)):
            for j in range(len(temperatures) - 1):
                if stability_fields[i, j] != stability_fields[i, j + 1]:
                    transitions.append({
                        'type': 'temperature_transition',
                        'pressure': pressures[i],
                        'temperature': (temperatures[j] + temperatures[j + 1]) / 2,
                        'from_assemblage': stability_fields[i, j],
                        'to_assemblage': stability_fields[i, j + 1]
                    })
        
        return transitions
    
    def _calculate_phase_boundaries(self, stability_fields: np.ndarray, 
                                   phase_assemblages: np.ndarray,
                                   pressures: np.ndarray, temperatures: np.ndarray,
                                   composition: Dict[str, float]) -> List[Dict]:
        """Calculate precise phase boundary locations using refined search"""
        boundaries = []
        
        # Find boundary segments
        for i in range(len(pressures) - 1):
            for j in range(len(temperatures) - 1):
                # Check for field changes in 2x2 grid
                field_values = [
                    stability_fields[i, j], stability_fields[i + 1, j],
                    stability_fields[i, j + 1], stability_fields[i + 1, j + 1]
                ]
                
                if len(set(field_values)) > 1:  # Boundary present
                    # Refine boundary location using bisection
                    boundary = self._refine_boundary_location(
                        pressures[i:i+2], temperatures[j:j+2], 
                        composition, tolerance=1e-3
                    )
                    
                    if boundary:
                        boundaries.append(boundary)
        
        return boundaries
    
    def _refine_boundary_location(self, p_range: np.ndarray, t_range: np.ndarray,
                                 composition: Dict[str, float], tolerance: float = 1e-3) -> Dict:
        """Refine phase boundary location using bisection method"""
        p_min, p_max = p_range[0], p_range[1]
        t_min, t_max = t_range[0], t_range[1]
        
        max_iterations = 20
        
        for _ in range(max_iterations):
            p_mid = (p_min + p_max) / 2
            t_mid = (t_min + t_max) / 2
            
            # Check assemblages at corners and midpoint
            try:
                all_phases = list(self.database.keys())
                eq1 = self.minimize_gibbs_energy(composition, t_min, p_min, all_phases)
                eq2 = self.minimize_gibbs_energy(composition, t_max, p_max, all_phases)
                eq_mid = self.minimize_gibbs_energy(composition, t_mid, p_mid, all_phases)
                
                assemblage1 = set(eq1['phases'].keys())
                assemblage2 = set(eq2['phases'].keys())
                assemblage_mid = set(eq_mid['phases'].keys())
                
                if assemblage1 == assemblage_mid:
                    p_min, t_min = p_mid, t_mid
                else:
                    p_max, t_max = p_mid, t_mid
                
                if abs(p_max - p_min) < tolerance and abs(t_max - t_min) < tolerance:
                    return {
                        'pressure': p_mid,
                        'temperature': t_mid,
                        'assemblage1': list(assemblage1),
                        'assemblage2': list(assemblage2),
                        'reaction': self._infer_reaction(assemblage1, assemblage2)
                    }
            
            except Exception:
                break
        
        return None
    
    def _find_critical_points(self, boundaries: List[Dict]) -> List[Dict]:
        """Find critical points (triple points, etc.) from boundary intersections"""
        critical_points = []
        tolerance = 50.0  # P-T tolerance for intersection detection
        
        for i, boundary1 in enumerate(boundaries):
            for j, boundary2 in enumerate(boundaries[i+1:], i+1):
                # Check if boundaries intersect
                p_diff = abs(boundary1['pressure'] - boundary2['pressure'])
                t_diff = abs(boundary1['temperature'] - boundary2['temperature'])
                
                if p_diff < tolerance and t_diff < tolerance:
                    # Potential critical point
                    assemblages = set()
                    assemblages.update(boundary1['assemblage1'])
                    assemblages.update(boundary1['assemblage2'])
                    assemblages.update(boundary2['assemblage1'])
                    assemblages.update(boundary2['assemblage2'])
                    
                    critical_points.append({
                        'pressure': (boundary1['pressure'] + boundary2['pressure']) / 2,
                        'temperature': (boundary1['temperature'] + boundary2['temperature']) / 2,
                        'type': 'intersection',
                        'involved_assemblages': list(assemblages),
                        'boundary_indices': [i, j]
                    })
        
        return critical_points
    
    def _infer_reaction(self, assemblage1: set, assemblage2: set) -> str:
        """Infer reaction equation from assemblage change"""
        phases_lost = assemblage1 - assemblage2
        phases_gained = assemblage2 - assemblage1
        
        reactants = ' + '.join(sorted(phases_lost)) if phases_lost else 'none'
        products = ' + '.join(sorted(phases_gained)) if phases_gained else 'none'
        
        return f"{reactants} = {products}"
    
    def _analyze_pt_diagram(self, stability_fields: np.ndarray, gibbs_energies: np.ndarray,
                           variances: np.ndarray, pressures: np.ndarray, 
                           temperatures: np.ndarray) -> Dict:
        """Perform advanced thermodynamic analysis of P-T diagram"""
        analysis = {
            'num_stability_fields': len(np.unique(stability_fields[stability_fields >= 0])),
            'pressure_range': (pressures.min(), pressures.max()),
            'temperature_range': (temperatures.min(), temperatures.max()),
            'min_gibbs_energy': np.min(gibbs_energies[gibbs_energies != np.inf]),
            'max_gibbs_energy': np.max(gibbs_energies[gibbs_energies != np.inf]),
            'avg_variance': np.mean(variances[variances > 0]),
        }
        
        # Calculate stability field areas
        field_areas = {}
        unique_fields = np.unique(stability_fields[stability_fields >= 0])
        
        dp = (pressures.max() - pressures.min()) / len(pressures)
        dt = (temperatures.max() - temperatures.min()) / len(temperatures)
        
        for field_id in unique_fields:
            area = np.sum(stability_fields == field_id) * dp * dt
            field_areas[int(field_id)] = area
        
        analysis['stability_field_areas'] = field_areas
        
        return analysis
    
    def _calculate_reaction_gibbs(self, reaction: str, temperature: float, 
                                pressure: float) -> float:
        """Calculate Gibbs energy of reaction with stoichiometry"""
        try:
            left, right = reaction.split(' = ')
            reactants = self._parse_reaction_side(left)
            products = self._parse_reaction_side(right)
            
            delta_g = 0
            
            # Products contribute positively
            for phase, coeff in products.items():
                if phase in self.database:
                    delta_g += coeff * self.calculate_gibbs_energy(phase, temperature, pressure)
            
            # Reactants contribute negatively
            for phase, coeff in reactants.items():
                if phase in self.database:
                    delta_g -= coeff * self.calculate_gibbs_energy(phase, temperature, pressure)
            
            return delta_g
        
        except Exception:
            return 0.0
    
    def _parse_reaction_side(self, reaction_side: str) -> Dict[str, float]:
        """Parse reaction side with stoichiometric coefficients"""
        phases = {}
        components = reaction_side.split(' + ')
        
        for component in components:
            component = component.strip()
            # Extract coefficient (default 1.0)
            parts = component.split(' ', 1)
            
            if len(parts) == 2 and parts[0].replace('.', '').isdigit():
                coeff = float(parts[0])
                phase = parts[1]
            else:
                coeff = 1.0
                phase = component
            
            phases[phase] = coeff
        
        return phases
    
    def _parse_reaction_products(self, reaction: str) -> List[str]:
        """Parse reaction to extract products"""
        try:
            _, right = reaction.split(' = ')
            products = self._parse_reaction_side(right)
            return list(products.keys())
        except Exception:
            return []
    
    def calculate_reaction_path(self, initial_composition: Dict[str, float],
                              final_composition: Dict[str, float],
                              temperature: float, pressure: float,
                              steps: int = 50,
                              kinetic_model: str = 'equilibrium',
                              rate_constants: Dict[str, float] = None,
                              time_scale: float = 1e6) -> Dict:
        """Calculate advanced reaction path with kinetic constraints and metastability"""
        
        if rate_constants is None:
            rate_constants = {}
        
        # Initialize path tracking
        path_data = {
            'equilibrium_path': [],
            'kinetic_path': [],
            'metastable_phases': [],
            'reaction_rates': [],
            'energy_barriers': [],
            'time_evolution': []
        }
        
        # Calculate equilibrium reference path
        eq_path = self._calculate_equilibrium_path(
            initial_composition, final_composition, temperature, pressure, steps
        )
        path_data['equilibrium_path'] = eq_path
        
        if kinetic_model == 'equilibrium':
            return path_data
        
        # Advanced kinetic modeling
        if kinetic_model in ['diffusion_limited', 'nucleation_growth', 'interface_controlled']:
            kinetic_path = self._calculate_kinetic_path(
                initial_composition, final_composition, temperature, pressure,
                steps, kinetic_model, rate_constants, time_scale
            )
            path_data['kinetic_path'] = kinetic_path
        
        # Identify metastable phases and energy barriers
        metastable_analysis = self._analyze_metastable_phases(
            eq_path, temperature, pressure
        )
        path_data['metastable_phases'] = metastable_analysis['phases']
        path_data['energy_barriers'] = metastable_analysis['barriers']
        
        # Calculate reaction rates for each step
        reaction_rates = self._calculate_reaction_rates(
            eq_path, temperature, pressure, kinetic_model, rate_constants
        )
        path_data['reaction_rates'] = reaction_rates
        
        return path_data
    
    def _calculate_equilibrium_path(self, initial_comp: Dict[str, float], 
                                   final_comp: Dict[str, float],
                                   temperature: float, pressure: float, 
                                   steps: int) -> List[Dict]:
        """Calculate thermodynamic equilibrium path"""
        path = []
        all_phases = list(self.database.keys())
        
        for i in range(steps + 1):
            alpha = i / steps
            
            # Smooth interpolation with optional cubic spline
            current_comp = {}
            all_elements = set(initial_comp.keys()) | set(final_comp.keys())
            
            for element in all_elements:
                initial_val = initial_comp.get(element, 0)
                final_val = final_comp.get(element, 0)
                
                # Cubic interpolation for smoother transitions
                t = alpha
                t2 = t * t
                t3 = t2 * t
                
                # Hermite interpolation with zero derivatives at endpoints
                h00 = 2*t3 - 3*t2 + 1
                h10 = t3 - 2*t2 + t
                h01 = -2*t3 + 3*t2
                h11 = t3 - t2
                
                current_comp[element] = h00 * initial_val + h01 * final_val
            
            try:
                # Calculate equilibrium with enhanced precision
                equilibrium = self.minimize_gibbs_energy(
                    current_comp, temperature, pressure, all_phases
                )
                
                # Additional analysis for each point
                analysis = self._analyze_path_point(
                    current_comp, equilibrium, temperature, pressure, alpha
                )
                
                path_point = {
                    'step': i,
                    'alpha': alpha,
                    'composition': current_comp,
                    'equilibrium': equilibrium,
                    'analysis': analysis
                }
                
                path.append(path_point)
                
            except Exception as e:
                # Handle calculation failures gracefully
                path.append({
                    'step': i,
                    'alpha': alpha,
                    'composition': current_comp,
                    'equilibrium': None,
                    'error': str(e)
                })
        
        return path
    
    def _calculate_kinetic_path(self, initial_comp: Dict[str, float], 
                               final_comp: Dict[str, float],
                               temperature: float, pressure: float, steps: int,
                               kinetic_model: str, rate_constants: Dict[str, float],
                               time_scale: float) -> List[Dict]:
        """Calculate kinetically-controlled reaction path"""
        kinetic_path = []
        current_comp = initial_comp.copy()
        dt = time_scale / steps
        
        for i in range(steps + 1):
            time = i * dt
            
            if kinetic_model == 'diffusion_limited':
                # Diffusion-controlled kinetics
                rates = self._calculate_diffusion_rates(
                    current_comp, final_comp, temperature, rate_constants
                )
            
            elif kinetic_model == 'nucleation_growth':
                # Nucleation and growth kinetics
                rates = self._calculate_nucleation_rates(
                    current_comp, temperature, pressure, rate_constants
                )
            
            elif kinetic_model == 'interface_controlled':
                # Interface-controlled reactions
                rates = self._calculate_interface_rates(
                    current_comp, temperature, pressure, rate_constants
                )
            
            else:
                rates = {}
            
            # Update composition based on kinetic rates
            if i < steps:
                for element in current_comp:
                    rate = rates.get(element, 0.0)
                    target = final_comp.get(element, 0.0)
                    current_val = current_comp[element]
                    
                    # First-order kinetic approach to equilibrium
                    diff = target - current_val
                    current_comp[element] += rate * diff * dt
            
            # Find current phase assemblage (may be metastable)
            try:
                phases = list(self.database.keys())
                assemblage = self.minimize_gibbs_energy(
                    current_comp, temperature, pressure, phases
                )
                
                kinetic_point = {
                    'time': time,
                    'step': i,
                    'composition': current_comp.copy(),
                    'assemblage': assemblage,
                    'rates': rates.copy(),
                    'kinetic_energy': self._calculate_kinetic_energy(rates, temperature)
                }
                
                kinetic_path.append(kinetic_point)
                
            except Exception as e:
                kinetic_path.append({
                    'time': time,
                    'step': i,
                    'composition': current_comp.copy(),
                    'error': str(e)
                })
        
        return kinetic_path
    
    def _analyze_path_point(self, composition: Dict[str, float], 
                           equilibrium: Dict, temperature: float, 
                           pressure: float, alpha: float) -> Dict:
        """Analyze thermodynamic properties at path point"""
        analysis = {
            'reaction_progress': alpha,
            'phase_changes': [],
            'affinity': 0,
            'driving_force': 0,
            'local_stability': 0
        }
        
        if equilibrium and 'phases' in equilibrium:
            # Calculate reaction affinity (driving force)
            total_gibbs = equilibrium.get('total_gibbs', 0)
            
            # Reference Gibbs energy (linear mixing)
            ref_gibbs = 0  # Would need initial and final reference states
            
            analysis['affinity'] = ref_gibbs - total_gibbs
            analysis['driving_force'] = -analysis['affinity'] / (8.314 * temperature)
            
            # Local stability assessment
            phase_stabilities = []
            for phase, phase_data in equilibrium['phases'].items():
                stability = phase_data.get('stability_index', 0)
                phase_stabilities.append(stability)
            
            if phase_stabilities:
                analysis['local_stability'] = min(phase_stabilities)
        
        return analysis
    
    def _analyze_metastable_phases(self, path: List[Dict], 
                                  temperature: float, pressure: float) -> Dict:
        """Identify metastable phases and energy barriers"""
        metastable_phases = []
        energy_barriers = []
        
        for i, point in enumerate(path):
            if point.get('equilibrium') and 'phases' in point['equilibrium']:
                phases = point['equilibrium']['phases']
                
                for phase_name, phase_data in phases.items():
                    stability = phase_data.get('stability_index', 0)
                    
                    # Identify metastable phases (positive but small stability index)
                    if 0 < stability < 1000:  # Threshold for metastability
                        metastable_phases.append({
                            'phase': phase_name,
                            'step': i,
                            'stability_index': stability,
                            'gibbs_energy': phase_data.get('gibbs_energy', 0)
                        })
                
                # Calculate energy barriers between adjacent steps
                if i > 0 and i < len(path) - 1:
                    prev_g = path[i-1]['equilibrium'].get('total_gibbs', 0)
                    curr_g = point['equilibrium'].get('total_gibbs', 0)
                    next_g = path[i+1]['equilibrium'].get('total_gibbs', 0)
                    
                    # Local maximum indicates energy barrier
                    if curr_g > prev_g and curr_g > next_g:
                        barrier_height = curr_g - min(prev_g, next_g)
                        energy_barriers.append({
                            'step': i,
                            'barrier_height': barrier_height,
                            'activation_energy': barrier_height,
                            'temperature': temperature
                        })
        
        return {
            'phases': metastable_phases,
            'barriers': energy_barriers
        }
    
    def _calculate_reaction_rates(self, path: List[Dict], temperature: float,
                                 pressure: float, kinetic_model: str,
                                 rate_constants: Dict[str, float]) -> List[Dict]:
        """Calculate reaction rates along path"""
        rates = []
        
        for i, point in enumerate(path):
            if i < len(path) - 1 and point.get('equilibrium'):
                next_point = path[i + 1]
                
                if next_point.get('equilibrium'):
                    # Calculate composition change rate
                    comp1 = point['composition']
                    comp2 = next_point['composition']
                    
                    rate_data = {
                        'step': i,
                        'overall_rate': 0,
                        'element_rates': {},
                        'phase_rates': {}
                    }
                    
                    # Element-wise rates
                    total_rate = 0
                    for element in comp1:
                        if element in comp2:
                            rate = abs(comp2[element] - comp1[element])
                            rate_data['element_rates'][element] = rate
                            total_rate += rate
                    
                    rate_data['overall_rate'] = total_rate
                    
                    # Phase appearance/disappearance rates
                    phases1 = set(point['equilibrium']['phases'].keys())
                    phases2 = set(next_point['equilibrium']['phases'].keys())
                    
                    appearing = phases2 - phases1
                    disappearing = phases1 - phases2
                    
                    for phase in appearing:
                        rate_constant = rate_constants.get(f'nucleation_{phase}', 1e-6)
                        rate_data['phase_rates'][f'{phase}_appearance'] = rate_constant
                    
                    for phase in disappearing:
                        rate_constant = rate_constants.get(f'dissolution_{phase}', 1e-6)
                        rate_data['phase_rates'][f'{phase}_disappearance'] = rate_constant
                    
                    rates.append(rate_data)
        
        return rates
    
    def _calculate_diffusion_rates(self, current_comp: Dict[str, float],
                                  target_comp: Dict[str, float], 
                                  temperature: float,
                                  rate_constants: Dict[str, float]) -> Dict[str, float]:
        """Calculate diffusion-limited reaction rates"""
        rates = {}
        
        # Arrhenius-type temperature dependence
        arrhenius_factor = np.exp(-10000 / (8.314 * temperature))  # Simplified activation energy
        
        for element in current_comp:
            D_0 = rate_constants.get(f'diffusion_{element}', 1e-12)  # Base diffusivity
            D_eff = D_0 * arrhenius_factor
            
            # Concentration gradient driving force
            concentration_diff = abs(target_comp.get(element, 0) - current_comp[element])
            rates[element] = D_eff * concentration_diff
        
        return rates
    
    def _calculate_nucleation_rates(self, composition: Dict[str, float],
                                   temperature: float, pressure: float,
                                   rate_constants: Dict[str, float]) -> Dict[str, float]:
        """Calculate nucleation and growth rates"""
        rates = {}
        
        # Classical nucleation theory parameters
        k_b = 1.38064852e-23  # Boltzmann constant
        
        for element in composition:
            # Nucleation rate from classical nucleation theory
            supersaturation = composition[element] / max(composition.get(f'{element}_eq', 1e-6), 1e-6)
            
            if supersaturation > 1:
                # Critical nucleus size and nucleation barrier
                gamma = rate_constants.get(f'surface_energy_{element}', 0.1)  # Surface energy
                delta_mu = k_b * temperature * np.log(supersaturation)
                
                if delta_mu > 0:
                    nucleation_barrier = 16 * np.pi * gamma**3 / (3 * delta_mu**2)
                    nucleation_rate = np.exp(-nucleation_barrier / (k_b * temperature))
                    rates[element] = nucleation_rate * rate_constants.get(f'kinetic_factor_{element}', 1e6)
                else:
                    rates[element] = 0.0
            else:
                rates[element] = 0.0
        
        return rates
    
    def _calculate_interface_rates(self, composition: Dict[str, float],
                                  temperature: float, pressure: float,
                                  rate_constants: Dict[str, float]) -> Dict[str, float]:
        """Calculate interface-controlled reaction rates"""
        rates = {}
        
        for element in composition:
            # Interface reaction rate (simplified Butler-Volmer type)
            k_0 = rate_constants.get(f'exchange_current_{element}', 1e-9)
            
            # Temperature dependence
            arrhenius = np.exp(-5000 / (8.314 * temperature))  # Activation energy
            
            # Concentration dependence (simplified)
            conc_factor = composition[element] / max(composition.get(f'{element}_ref', 1.0), 1e-6)
            
            rates[element] = k_0 * arrhenius * conc_factor
        
        return rates
    
    def _calculate_kinetic_energy(self, rates: Dict[str, float], temperature: float) -> float:
        """Calculate kinetic energy associated with reaction rates"""
        total_kinetic = 0.0
        
        for rate in rates.values():
            # Kinetic energy proportional to reaction rate and temperature
            total_kinetic += 0.5 * rate * 8.314 * temperature
        
        return total_kinetic
    
    def solve_multicomponent_equilibrium(self, composition: Dict[str, float],
                                       temperature: float, pressure: float,
                                       solution_phases: List[str] = None,
                                       activity_models: Dict[str, str] = None,
                                       convergence_tolerance: float = 1e-8,
                                       max_iterations: int = 1000) -> Dict:
        """Advanced multi-component phase equilibrium solver with activity models"""
        
        if solution_phases is None:
            solution_phases = []
        
        if activity_models is None:
            activity_models = {}
        
        # Initialize solution models for multi-component phases
        solution_models = {}
        for phase in solution_phases:
            model_type = activity_models.get(phase, 'ideal')
            solution_models[phase] = ActivityModel(model_type)
        
        # Advanced equilibrium calculation with activity corrections
        equilibrium_result = self._solve_gibbs_minimization_with_activities(
            composition, temperature, pressure, solution_models,
            convergence_tolerance, max_iterations
        )
        
        # Post-processing analysis
        analysis = self._analyze_multicomponent_equilibrium(
            equilibrium_result, temperature, pressure, solution_models
        )
        
        equilibrium_result['advanced_analysis'] = analysis
        
        return equilibrium_result
    
    def _solve_gibbs_minimization_with_activities(self, composition: Dict[str, float],
                                                 temperature: float, pressure: float,
                                                 solution_models: Dict[str, ActivityModel],
                                                 tolerance: float, max_iterations: int) -> Dict:
        """Solve Gibbs energy minimization with activity corrections"""
        
        all_phases = list(self.database.keys())
        n_phases = len(all_phases)
        n_elements = len(composition)
        
        # Initial guess - equal distribution among phases
        initial_amounts = np.ones(n_phases) * 0.01
        
        # Constraint matrix for mass balance
        A_eq, b_eq = self._build_mass_balance_constraints(composition, all_phases)
        
        # Bounds - all amounts >= 0
        bounds = [(0, None) for _ in range(n_phases)]
        
        # Iterative solution with activity updates
        current_amounts = initial_amounts.copy()
        
        for iteration in range(max_iterations):
            # Update activities based on current phase compositions
            activities = self._update_phase_activities(
                current_amounts, all_phases, solution_models, temperature, pressure
            )
            
            # Define objective function with current activities
            def objective_with_activities(amounts):
                return self._gibbs_objective_with_activities(
                    amounts, all_phases, temperature, pressure, activities
                )
            
            # Minimize Gibbs energy
            result = minimize(
                objective_with_activities,
                current_amounts,
                method='SLSQP',
                bounds=bounds,
                constraints={'type': 'eq', 'fun': lambda x: A_eq.dot(x) - b_eq},
                options={'ftol': tolerance, 'disp': False}
            )
            
            if result.success:
                # Check convergence
                amount_change = np.linalg.norm(result.x - current_amounts)
                
                if amount_change < tolerance:
                    # Converged
                    final_result = self._format_equilibrium_result(
                        result.x, all_phases, temperature, pressure
                    )
                    
                    # Add activity information
                    final_result['activities'] = activities
                    final_result['convergence'] = {
                        'converged': True,
                        'iterations': iteration + 1,
                        'final_change': amount_change
                    }
                    
                    return final_result
                
                current_amounts = result.x
            
            else:
                # Try different starting point
                current_amounts = np.random.rand(n_phases) * 0.1
        
        # Did not converge
        return {
            'convergence': {
                'converged': False,
                'iterations': max_iterations,
                'message': 'Maximum iterations reached without convergence'
            }
        }
    
    def _update_phase_activities(self, amounts: np.ndarray, phases: List[str],
                                solution_models: Dict[str, ActivityModel],
                                temperature: float, pressure: float) -> Dict[str, Dict[str, float]]:
        """Update activity coefficients for solution phases"""
        activities = {}
        
        for i, phase in enumerate(phases):
            if amounts[i] > 1e-12 and phase in solution_models:
                # Calculate phase composition
                phase_composition = self._calculate_phase_composition(phase, amounts[i])
                
                # Get activity coefficients from model
                gamma = solution_models[phase].calculate_activity_coefficient(
                    phase_composition, temperature, pressure
                )
                
                # Calculate activities (activity = mole_fraction * activity_coefficient)
                phase_activities = {}
                for component, x_i in phase_composition.items():
                    phase_activities[component] = x_i * gamma.get(component, 1.0)
                
                activities[phase] = phase_activities
            
            else:
                # Pure phase or negligible amount
                activities[phase] = {phase: 1.0}
        
        return activities
    
    def _calculate_phase_composition(self, phase: str, amount: float, 
                                   temperature: float = 298.15, pressure: float = 1.0,
                                   bulk_composition: Dict[str, float] = None,
                                   activity_model: str = 'ideal') -> Dict[str, float]:
        """
        Advanced phase composition calculation using thermodynamic mixing models
        
        Args:
            phase: Phase identifier
            amount: Phase amount (moles)
            temperature: Temperature (K)
            pressure: Pressure (bar)
            bulk_composition: System bulk composition
            activity_model: Activity model ('ideal', 'margules', 'van_laar', 'wilson')
            
        Returns:
            Dict mapping components to mole fractions in the phase
        """
        if amount < 1e-12:
            return {}
            
        # Get phase data from database
        phase_data = self.database.get(phase, {})
        
        # For solid solution phases, use advanced mixing models
        if phase_data.get('type') == 'solution':
            return self._solve_solution_phase_composition(
                phase, amount, temperature, pressure, bulk_composition, activity_model)
        
        # For stoichiometric phases
        elif phase_data.get('type') == 'stoichiometric':
            elements = phase_data.get('elements', {})
            if not elements:
                return {phase: 1.0}
                
            # Normalize to mole fractions
            total = sum(elements.values())
            return {element: count/total for element, count in elements.items()}
        
        # For gas phases, use equation of state
        elif phase_data.get('type') == 'gas':
            return self._calculate_gas_phase_composition(
                phase, amount, temperature, pressure, bulk_composition)
        
        # For liquid phases, use liquid activity models
        elif phase_data.get('type') == 'liquid':
            return self._calculate_liquid_phase_composition(
                phase, amount, temperature, pressure, bulk_composition, activity_model)
        
        # Default fallback
        return {phase: 1.0}
    
    def _solve_solution_phase_composition(self, phase: str, amount: float,
                                        temperature: float, pressure: float,
                                        bulk_composition: Dict[str, float],
                                        activity_model: str) -> Dict[str, float]:
        """Solve for equilibrium composition in solid solution phases"""
        phase_data = self.database.get(phase, {})
        end_members = phase_data.get('end_members', [phase])
        
        if len(end_members) <= 1:
            return {phase: 1.0}
        
        # Initialize composition guess based on bulk composition
        if bulk_composition:
            # Project bulk composition onto solution space
            initial_x = self._project_bulk_to_solution(bulk_composition, end_members)
        else:
            # Equal mole fraction starting point
            initial_x = np.ones(len(end_members)) / len(end_members)
        
        # Solve for equilibrium composition using chemical potential equality
        try:
            from scipy.optimize import minimize
            
            def composition_objective(x_vec):
                """Minimize Gibbs energy of mixing with activity corrections"""
                x_dict = {end_members[i]: x_vec[i] for i in range(len(end_members))}
                
                # Gibbs energy of mixing
                g_mix = self._calculate_mixing_gibbs(x_dict, temperature, pressure, activity_model)
                
                # Configurational entropy
                s_config = -self.R * sum(x * np.log(max(x, 1e-12)) for x in x_vec if x > 1e-12)
                
                return g_mix - temperature * s_config
            
            # Constraints: sum(x) = 1, x >= 0
            constraints = [
                {'type': 'eq', 'fun': lambda x: np.sum(x) - 1.0}
            ]
            bounds = [(0.0, 1.0) for _ in range(len(end_members))]
            
            result = minimize(composition_objective, initial_x, 
                            method='SLSQP', bounds=bounds, constraints=constraints,
                            options={'ftol': 1e-10, 'maxiter': 1000})
            
            if result.success:
                return {end_members[i]: result.x[i] for i in range(len(end_members)) 
                       if result.x[i] > 1e-6}
            
        except ImportError:
            # Fallback to iterative method if scipy not available
            pass
        
        # Fallback: ideal mixing approximation
        return self._ideal_solution_composition(end_members, bulk_composition)
    
    def _calculate_mixing_gibbs(self, composition: Dict[str, float], 
                              temperature: float, pressure: float,
                              activity_model: str) -> float:
        """Calculate Gibbs energy of mixing for solution phase"""
        if activity_model == 'ideal':
            return 0.0
        
        elif activity_model == 'margules':
            return self._margules_mixing_energy(composition, temperature)
        
        elif activity_model == 'van_laar':
            return self._van_laar_mixing_energy(composition, temperature)
        
        elif activity_model == 'wilson':
            return self._wilson_mixing_energy(composition, temperature)
        
        return 0.0
    
    def _margules_mixing_energy(self, composition: Dict[str, float], temperature: float) -> float:
        """Margules mixing model for solution phases"""
        components = list(composition.keys())
        if len(components) < 2:
            return 0.0
        
        # Symmetric Margules parameters (simplified)
        W12 = 2500.0  # J/mol - typical interaction parameter
        
        g_mix = 0.0
        for i, comp1 in enumerate(components):
            for j, comp2 in enumerate(components):
                if i < j:
                    x1, x2 = composition[comp1], composition[comp2]
                    g_mix += W12 * x1 * x2
        
        return g_mix
    
    def _van_laar_mixing_energy(self, composition: Dict[str, float], temperature: float) -> float:
        """Van Laar mixing model for solution phases"""
        components = list(composition.keys())
        if len(components) < 2:
            return 0.0
        
        # Van Laar parameters
        A12, A21 = 1.2, 0.8  # Dimensionless parameters
        
        total_g = 0.0
        for i, comp1 in enumerate(components):
            for j, comp2 in enumerate(components):
                if i < j:
                    x1, x2 = composition[comp1], composition[comp2]
                    if x1 > 1e-12 and x2 > 1e-12:
                        denom = (A12 * x1 / A21 / x2) + 1.0
                        total_g += self.R * temperature * x1 * x2 * A12 * A21 / denom
        
        return total_g
    
    def _wilson_mixing_energy(self, composition: Dict[str, float], temperature: float) -> float:
        """
        Advanced Wilson mixing model for multicomponent liquid solutions
        
        Uses proper Wilson equation with binary interaction parameters
        and temperature-dependent molar volume corrections
        """
        components = list(composition.keys())
        n_comp = len(components)
        
        if n_comp < 2:
            return 0.0
        
        # Initialize Wilson parameter matrix
        wilson_params = self._get_wilson_parameters(components, temperature)
        
        # Calculate Wilson mixing energy using full multicomponent formulation
        g_mix = 0.0
        
        # First term: sum over all components
        for i, comp_i in enumerate(components):
            x_i = composition[comp_i]
            if x_i < 1e-12:
                continue
                
            # Calculate sum in denominator for component i
            denominator_sum = 0.0
            for j, comp_j in enumerate(components):
                x_j = composition[comp_j]
                lambda_ij = wilson_params[i][j]
                denominator_sum += x_j * lambda_ij
            
            if denominator_sum > 1e-12:
                g_mix -= x_i * np.log(denominator_sum)
        
        return self.R * temperature * g_mix
    
    def _get_wilson_parameters(self, components: List[str], temperature: float) -> np.ndarray:
        """
        Calculate Wilson interaction parameters Lambda_ij for all component pairs
        
        Lambda_ij = (V_j / V_i) * exp(-a_ij / RT)
        where a_ij is the binary interaction energy parameter
        """
        n_comp = len(components)
        lambda_matrix = np.ones((n_comp, n_comp))
        
        # Wilson binary interaction database (simplified but realistic)
        wilson_database = self._get_wilson_interaction_database()
        
        for i, comp_i in enumerate(components):
            v_i = self._get_molar_volume(comp_i, temperature)
            
            for j, comp_j in enumerate(components):
                if i == j:
                    lambda_matrix[i][j] = 1.0
                    continue
                
                v_j = self._get_molar_volume(comp_j, temperature)
                
                # Get binary interaction parameter
                pair_key = self._get_pair_key(comp_i, comp_j)
                a_ij = wilson_database.get(pair_key, {}).get('a_ij', 0.0)
                
                # Calculate Wilson parameter
                if v_i > 1e-12:
                    volume_ratio = v_j / v_i
                    energy_term = np.exp(-a_ij / (self.R * temperature))
                    lambda_matrix[i][j] = volume_ratio * energy_term
                else:
                    lambda_matrix[i][j] = 1.0
        
        return lambda_matrix
    
