    def _get_uniquac_interaction_parameters(self, components: List[str], 
                                          temperature: float) -> np.ndarray:
        """
        Calculate UNIQUAC binary interaction parameters τ_ij
        
        τ_ij = exp(-u_ij / RT) where u_ij is the interaction energy parameter
        """
        n_comp = len(components)
        tau_matrix = np.ones((n_comp, n_comp))  # Initialize with unity (ideal)
        
        # UNIQUAC interaction energy database
        uniquac_database = self._get_uniquac_interaction_database()
        
        for i, comp_i in enumerate(components):
            for j, comp_j in enumerate(components):
                if i == j:
                    tau_matrix[i][j] = 1.0  # Self-interaction
                    continue
                
                # Get binary interaction energy
                pair_key = self._get_pair_key(comp_i, comp_j)
                interaction_data = uniquac_database.get(pair_key, {})
                
                # Temperature-dependent interaction parameter
                u_ij = interaction_data.get('u_ij', 0.0)  # J/mol
                
                if abs(u_ij) > 1e-6:
                    tau_matrix[i][j] = np.exp(-u_ij / (self.R * temperature))
                else:
                    tau_matrix[i][j] = 1.0
        
        return tau_matrix
    
