    def _calculate_debye_huckel_activity_coefficient(self, component: str, composition: Dict[str, float],
                                                   temperature: float) -> float:
        """Debye-Hückel activity coefficient for electrolyte solutions"""
        # Check if component is an ion
        if not self._is_ionic_species(component):
            return 1.0
        
        # Calculate ionic strength
        ionic_strength = self._calculate_ionic_strength(composition)
        
        # Debye-Hückel parameters
        A_dh = self._get_debye_huckel_A_parameter(temperature)
        z_i = self._get_ion_charge(component)
        
        # Debye-Hückel limiting law
        if ionic_strength <= 0.1:
            ln_gamma = -A_dh * z_i**2 * np.sqrt(ionic_strength)
        else:
            # Extended Debye-Hückel
            B_dh = self._get_debye_huckel_B_parameter(temperature)
            a_i = self._get_ion_size_parameter(component)
            
            sqrt_I = np.sqrt(ionic_strength)
            ln_gamma = (-A_dh * z_i**2 * sqrt_I) / (1.0 + B_dh * a_i * sqrt_I)
        
        return np.exp(ln_gamma)
    
    def _calculate_extended_debye_huckel_activity_coefficient(self, component: str, 
                                                            composition: Dict[str, float],
                                                            temperature: float) -> float:
        """Extended Debye-Hückel with ion interaction parameters"""
        if not self._is_ionic_species(component):
            return 1.0
        
        ionic_strength = self._calculate_ionic_strength(composition)
        A_dh = self._get_debye_huckel_A_parameter(temperature)
        B_dh = self._get_debye_huckel_B_parameter(temperature)
        z_i = self._get_ion_charge(component)
        a_i = self._get_ion_size_parameter(component)
        b_gamma = 0.1244  # Ion interaction parameter (kg/mol)
        
        sqrt_I = np.sqrt(ionic_strength)
        
        ln_gamma = ((-A_dh * z_i**2 * sqrt_I) / (1.0 + B_dh * a_i * sqrt_I) + 
                   b_gamma * ionic_strength)
        
        return np.exp(ln_gamma)
    
    def _calculate_pitzer_activity_coefficient(self, component: str, composition: Dict[str, float],
                                             temperature: float) -> float:
        """
        Rigorous Pitzer ion interaction model for electrolyte solutions
        
        ln(γ_MX) = f^γ + B^γ_MX*m + C^γ_MX*m² + Σ_c Ψ_McX*m_c + Σ_a Ψ_MaX*m_a + ...
        
        Includes: Debye-Hückel term, binary interactions, ternary interactions,
        temperature dependencies, and mixed electrolyte effects
        """
        if not self._is_ionic_species(component):
            return 1.0
        
        ionic_strength = self._calculate_ionic_strength(composition)
        if ionic_strength < 1e-12:
            return 1.0
        
        z_i = self._get_ion_charge(component)
        
        # Calculate Pitzer activity coefficient components
        ln_gamma = 0.0
        
        # 1. Debye-Hückel contribution (f^γ term)
        f_gamma = self._pitzer_debye_huckel_term(z_i, ionic_strength, temperature)
        ln_gamma += f_gamma
        
        # 2. Binary interaction contributions (B^γ terms)
        binary_contrib = self._pitzer_binary_interactions(component, composition, temperature)
        ln_gamma += binary_contrib
        
        # 3. Ternary interaction contributions (C^γ and Ψ terms)
        ternary_contrib = self._pitzer_ternary_interactions(component, composition, temperature)
        ln_gamma += ternary_contrib
        
        # 4. Higher-order interactions for concentrated solutions
        if ionic_strength > 1.0:
            higher_order = self._pitzer_higher_order_terms(component, composition, temperature)
            ln_gamma += higher_order
        
        return np.exp(ln_gamma)
    
    def _pitzer_debye_huckel_term(self, z_i: int, ionic_strength: float, temperature: float) -> float:
        """
        Pitzer Debye-Hückel term f^γ
        
        f^γ = -A_φ * |z_+ z_-| * [I^0.5 / (1 + b*I^0.5) + (2/b) * ln(1 + b*I^0.5)]
        """
        if abs(z_i) < 1e-6:
            return 0.0
        
        # Pitzer Debye-Hückel parameters
        A_phi = self._get_pitzer_debye_huckel_parameter(temperature)
        b = 1.2  # kg^0.5/mol^0.5 (universal Pitzer parameter)
        
        sqrt_I = np.sqrt(ionic_strength)
        b_sqrt_I = b * sqrt_I
        
        if b_sqrt_I > 1e-12:
            f_gamma = (-A_phi * abs(z_i)**2 * 
                      (sqrt_I / (1.0 + b_sqrt_I) + 
                       (2.0/b) * np.log(1.0 + b_sqrt_I)))
        else:
            # Small ionic strength limit
            f_gamma = -A_phi * abs(z_i)**2 * sqrt_I
        
        return f_gamma
    
    def _pitzer_binary_interactions(self, component: str, composition: Dict[str, float],
                                  temperature: float) -> float:
        """
        Pitzer binary interaction terms B^γ_MX
        
        B^γ_MX = β^(0)_MX + β^(1)_MX * g(α₁√I) + β^(2)_MX * g(α₂√I)
        where g(x) = 2[1-(1+x)exp(-x)]/x²
        """
        ionic_strength = self._calculate_ionic_strength(composition)
        sqrt_I = np.sqrt(ionic_strength)
        
        # Get all counterions for this component
        counterions = self._get_counterions(component, composition)
        
        binary_sum = 0.0
        
        for counterion in counterions:
            m_counterion = composition.get(counterion, 0.0)
            if m_counterion < 1e-12:
                continue
            
            # Get Pitzer binary parameters
            pitzer_params = self._get_pitzer_binary_parameters(component, counterion, temperature)
            
            beta_0 = pitzer_params.get('beta_0', 0.0)
            beta_1 = pitzer_params.get('beta_1', 0.0)
            beta_2 = pitzer_params.get('beta_2', 0.0)
            alpha_1 = pitzer_params.get('alpha_1', 2.0)  # Default α₁
            alpha_2 = pitzer_params.get('alpha_2', 50.0)  # Default α₂ for 2-2 electrolytes
            
            # Calculate g functions
            g_1 = self._pitzer_g_function(alpha_1 * sqrt_I)
            g_2 = self._pitzer_g_function(alpha_2 * sqrt_I)
            
            # Binary interaction contribution
            B_gamma = beta_0 + beta_1 * g_1 + beta_2 * g_2
            
            binary_sum += 2.0 * B_gamma * m_counterion
        
        return binary_sum
    
    def _pitzer_ternary_interactions(self, component: str, composition: Dict[str, float],
                                   temperature: float) -> float:
        """
        Pitzer ternary interaction terms C^γ and Ψ
        
        Includes C^γ_MX (cation-anion-cation/anion interactions) and
        Ψ_MN,X (cation-cation-anion) and Ψ_M,XY (cation-anion-anion) terms
        """
        ternary_sum = 0.0
        
        # C^γ terms (three-body interactions)
        counterions = self._get_counterions(component, composition)
        
        for counterion in counterions:
            m_counterion = composition.get(counterion, 0.0)
            if m_counterion < 1e-12:
                continue
            
            # Get ternary parameter C^γ
            pitzer_params = self._get_pitzer_binary_parameters(component, counterion, temperature)
            C_gamma = pitzer_params.get('C_gamma', 0.0)
            
            ternary_sum += C_gamma * m_counterion**2
        
        # Ψ terms (mixed electrolyte interactions)
        psi_sum = self._pitzer_mixed_electrolyte_terms(component, composition, temperature)
        ternary_sum += psi_sum
        
        return ternary_sum
    
    def _pitzer_mixed_electrolyte_terms(self, component: str, composition: Dict[str, float],
                                      temperature: float) -> float:
        """
        Mixed electrolyte Ψ interaction terms
        
        Ψ_MN,X (cation-cation-anion) and Ψ_M,XY (cation-anion-anion)
        """
        psi_sum = 0.0
        
        is_cation = self._get_ion_charge(component) > 0
        
        if is_cation:
            # Ψ_MN,X terms (cation-cation-anion)
            other_cations = [comp for comp in composition.keys() 
                           if self._is_ionic_species(comp) and self._get_ion_charge(comp) > 0 and comp != component]
            anions = [comp for comp in composition.keys() 
                     if self._is_ionic_species(comp) and self._get_ion_charge(comp) < 0]
            
            for other_cation in other_cations:
                m_cation = composition.get(other_cation, 0.0)
                if m_cation < 1e-12:
                    continue
                
                for anion in anions:
                    m_anion = composition.get(anion, 0.0)
                    if m_anion < 1e-12:
                        continue
                    
                    # Get Ψ_MN,X parameter
                    psi_param = self._get_pitzer_psi_parameter(component, other_cation, anion, temperature)
                    psi_sum += psi_param * m_cation * m_anion
        
        else:
            # Ψ_M,XY terms (cation-anion-anion)
            cations = [comp for comp in composition.keys() 
                      if self._is_ionic_species(comp) and self._get_ion_charge(comp) > 0]
            other_anions = [comp for comp in composition.keys() 
                          if self._is_ionic_species(comp) and self._get_ion_charge(comp) < 0 and comp != component]
            
            for cation in cations:
                m_cation = composition.get(cation, 0.0)
                if m_cation < 1e-12:
                    continue
                
                for other_anion in other_anions:
                    m_anion = composition.get(other_anion, 0.0)
                    if m_anion < 1e-12:
                        continue
                    
                    # Get Ψ_M,XY parameter
                    psi_param = self._get_pitzer_psi_parameter(cation, component, other_anion, temperature)
                    psi_sum += psi_param * m_cation * m_anion
        
        return psi_sum
    
    def _pitzer_higher_order_terms(self, component: str, composition: Dict[str, float],
                                 temperature: float) -> float:
        """
        Higher-order Pitzer terms for very concentrated solutions (I > 1 M)
        
        Includes λ and μ parameters for neutral species interactions
        """
        ionic_strength = self._calculate_ionic_strength(composition)
        
        # Higher-order correction for high ionic strength
        higher_order = 0.0
        
        if ionic_strength > 5.0:
            # Very concentrated solution corrections
            correction_factor = 0.01 * (ionic_strength - 5.0)**1.5
            higher_order = -correction_factor * abs(self._get_ion_charge(component))
        
        return higher_order
    
    def _pitzer_g_function(self, x: float) -> float:
        """
        Pitzer g(x) function: g(x) = 2[1-(1+x)exp(-x)]/x²
        
        With proper limits for small x
        """
        if x < 1e-6:
            # Taylor expansion for small x: g(x) ≈ x/3 - x²/12 + x³/60
            return x/3.0 - x**2/12.0 + x**3/60.0
        
        elif x > 50.0:
            # Large x limit: g(x) ≈ 2/x²
            return 2.0 / (x**2)
        
        else:
            # Standard calculation
            exp_neg_x = np.exp(-x)
            return 2.0 * (1.0 - (1.0 + x) * exp_neg_x) / (x**2)
    
    def _get_counterions(self, component: str, composition: Dict[str, float]) -> List[str]:
        """Get all counterions for a given ion"""
        z_component = self._get_ion_charge(component)
        
        counterions = []
        for comp in composition.keys():
            if self._is_ionic_species(comp) and comp != component:
                z_comp = self._get_ion_charge(comp)
                # Counterions have opposite charge sign
                if (z_component > 0 and z_comp < 0) or (z_component < 0 and z_comp > 0):
                    counterions.append(comp)
        
        return counterions
    
    def _get_pitzer_debye_huckel_parameter(self, temperature: float) -> float:
        """
        Temperature-dependent Pitzer Debye-Hückel parameter A_φ
        
        A_φ = (1/3) * (2πN_A ρ_w)^0.5 * (e²/4πε₀εᵣkT)^1.5
        """
        # For water as solvent (kg^0.5/mol^0.5)
        # Empirical correlation for A_φ in water
        T_r = temperature / 298.15
        A_phi = 0.3915 * (T_r)**(-1.5) * (1.0 + 0.0005 * (temperature - 298.15))
        
        return A_phi
    
