    def _run_advanced_consistency_tests(self) -> Dict:
        """Advanced thermodynamic consistency validation with rigorous mathematical checks"""
        results = {
            'gibbs_duhem_tests': self._test_gibbs_duhem_relation(),
            'maxwell_relations': self._test_maxwell_relations(),
            'integration_path_independence': self._test_path_independence(),
            'reciprocity_relations': self._test_reciprocity_relations(),
            'temperature_derivatives': self._test_temperature_derivatives(),
            'pressure_derivatives': self._test_pressure_derivatives(),
            'chemical_potential_consistency': self._test_chemical_potential_consistency(),
            'phase_equilibrium_criteria': self._test_equilibrium_criteria()
        }
        
        # Statistical summary
        total_tests = sum(len(test['test_points']) for test in results.values() if 'test_points' in test)
        passed_tests = sum(test.get('passed', 0) for test in results.values())
        
        results['summary'] = {
            'total_tests': total_tests,
            'passed_tests': passed_tests,
            'success_rate': passed_tests / total_tests if total_tests > 0 else 0,
            'statistical_significance': self._calculate_statistical_significance(results)
        }
        
        return results
    
    def _test_gibbs_duhem_relation(self) -> Dict:
        """Test Gibbs-Duhem relation with statistical rigor"""
        test_systems = [
            {'phases': ['quartz', 'albite'], 'compositions': [{'SiO2': 0.7, 'Al2O3': 0.3}]},
            {'phases': ['forsterite', 'fayalite'], 'compositions': [{'MgO': 0.6, 'FeO': 0.4}]},
            {'phases': ['anorthite', 'orthoclase'], 'compositions': [{'CaO': 0.3, 'K2O': 0.7}]}
        ]
        
        test_results = []
        temperature_range = np.linspace(800, 1200, 20)
        pressure_range = np.linspace(1, 10, 10)
        
        for system in test_systems:
            for composition in system['compositions']:
                for T in temperature_range:
                    for P in pressure_range:
                        try:
                            # Test Gibbs-Duhem: Σ n_i dμ_i = -S dT + V dP
                            dT = 1.0
                            dP = 0.01
                            
                            # Calculate chemical potentials
                            mu_initial = self.engine.calculate_chemical_potential_derivatives(
                                composition, T, P
                            )
                            mu_final_T = self.engine.calculate_chemical_potential_derivatives(
                                composition, T + dT, P
                            )
                            mu_final_P = self.engine.calculate_chemical_potential_derivatives(
                                composition, T, P + dP
                            )
                            
                            # Calculate entropy and volume
                            entropy = self._calculate_molar_entropy(composition, T, P)
                            volume = self._calculate_molar_volume(composition, T, P)
                            
                            # Gibbs-Duhem test
                            lhs_T = sum(composition.get(comp, 0) * (mu_final_T.get(comp, 0) - mu_initial.get(comp, 0)) / dT 
                                       for comp in composition)
                            rhs_T = -entropy
                            
                            lhs_P = sum(composition.get(comp, 0) * (mu_final_P.get(comp, 0) - mu_initial.get(comp, 0)) / dP 
                                       for comp in composition)
                            rhs_P = volume
                            
                            error_T = abs(lhs_T - rhs_T) / abs(rhs_T) if abs(rhs_T) > 1e-10 else abs(lhs_T)
                            error_P = abs(lhs_P - rhs_P) / abs(rhs_P) if abs(rhs_P) > 1e-10 else abs(lhs_P)
                            
                            test_results.append({
                                'temperature': T,
                                'pressure': P,
                                'composition': composition,
                                'error_temperature': error_T,
                                'error_pressure': error_P,
                                'passed': error_T < 0.05 and error_P < 0.05
                            })
                            
                        except Exception as e:
                            test_results.append({
                                'temperature': T,
                                'pressure': P,
                                'error': str(e),
                                'passed': False
                            })
        
        passed_tests = sum(1 for test in test_results if test.get('passed', False))
        return {
            'test_points': test_results,
            'passed': passed_tests,
            'total': len(test_results),
            'success_rate': passed_tests / len(test_results) if test_results else 0,
            'mean_temperature_error': np.mean([t.get('error_temperature', 1) for t in test_results if 'error_temperature' in t]),
            'mean_pressure_error': np.mean([t.get('error_pressure', 1) for t in test_results if 'error_pressure' in t])
        }
    
    def _run_mass_balance_with_uncertainty(self) -> Dict:
        """Advanced mass balance validation with uncertainty quantification and error propagation"""
        
        # Define comprehensive test systems with varying complexity
        test_systems = [
            # Simple binary systems
            {'name': 'Quartz-Albite', 'composition': {'SiO2': 2.0, 'Al2O3': 0.5, 'Na2O': 0.5}, 
             'phases': ['quartz', 'albite'], 'expected_elements': ['Si', 'Al', 'Na', 'O']},
            
            # Ternary systems
            {'name': 'Olivine-Pyroxene-Plagioclase', 
             'composition': {'MgO': 1.0, 'FeO': 0.5, 'SiO2': 2.0, 'CaO': 0.3, 'Al2O3': 0.4, 'Na2O': 0.1},
             'phases': ['forsterite', 'enstatite', 'albite'], 
             'expected_elements': ['Mg', 'Fe', 'Si', 'Ca', 'Al', 'Na', 'O']},
            
            # Complex multi-component systems
            {'name': 'Granitic-System', 
             'composition': {'SiO2': 4.0, 'Al2O3': 1.0, 'K2O': 0.8, 'Na2O': 0.6, 'CaO': 0.3, 'FeO': 0.2, 'MgO': 0.1},
             'phases': ['quartz', 'orthoclase', 'albite', 'anorthite', 'biotite'],
             'expected_elements': ['Si', 'Al', 'K', 'Na', 'Ca', 'Fe', 'Mg', 'O']}
        ]
        
        # Temperature and pressure ranges for robustness testing
        test_conditions = [
            (800, 1.0), (1000, 1.0), (1200, 1.0),  # Isobaric
            (1000, 0.5), (1000, 2.0), (1000, 5.0)  # Isothermal
        ]
        
        results = {
            'systems_tested': [],
            'statistical_summary': {},
            'uncertainty_analysis': {},
            'error_distribution': []
        }
        
        all_errors = []
        
        for system in test_systems:
            system_results = {
                'name': system['name'],
                'test_points': [],
                'element_errors': {element: [] for element in system['expected_elements']}
            }
            
            for temperature, pressure in test_conditions:
                # Monte Carlo sampling for uncertainty estimation
                n_samples = 50
                sample_errors = []
                
                for sample in range(n_samples):
                    try:
                        # Add small perturbations to test numerical stability
                        perturbed_comp = {k: v * (1 + np.random.normal(0, 0.01)) 
                                        for k, v in system['composition'].items()}
                        perturbed_T = temperature * (1 + np.random.normal(0, 0.001))
                        perturbed_P = pressure * (1 + np.random.normal(0, 0.001))
                        
                        # Solve equilibrium
                        equilibrium = self.engine.minimize_gibbs_energy(
                            perturbed_comp, perturbed_T, perturbed_P, system['phases']
                        )
                        
                        # Calculate mass balance errors for each element
                        element_errors = {}
                        for element in system['expected_elements']:
                            input_amount = perturbed_comp.get(element, 0)
                            output_amount = 0
                            
                            # Sum across all phases
                            for phase_name, phase_data in equilibrium.get('phases', {}).items():
                                if 'amount' in phase_data:
                                    phase_amount = phase_data['amount']
                                    element_stoich = self._get_element_stoichiometry(phase_name, element)
                                    output_amount += phase_amount * element_stoich
                            
                            # Calculate relative error with proper handling of zero values
                            if input_amount > 1e-12:
                                relative_error = abs(output_amount - input_amount) / input_amount
                            else:
                                relative_error = abs(output_amount)
                            
                            element_errors[element] = relative_error
                            system_results['element_errors'][element].append(relative_error)
                        
                        # Overall system error (RMS of element errors)
                        system_error = np.sqrt(np.mean([e**2 for e in element_errors.values()]))
                        sample_errors.append(system_error)
                        all_errors.append(system_error)
                        
                        system_results['test_points'].append({
                            'temperature': perturbed_T,
                            'pressure': perturbed_P,
                            'composition': perturbed_comp,
                            'element_errors': element_errors,
                            'system_error': system_error,
                            'passed': system_error < 0.01  # 1% tolerance
                        })
                        
                    except Exception as e:
                        system_results['test_points'].append({
                            'temperature': temperature,
                            'pressure': pressure,
                            'error': str(e),
                            'passed': False
                        })
                
                # Statistical analysis of sample errors
                if sample_errors:
                    system_results['statistical_metrics'] = {
                        'mean_error': np.mean(sample_errors),
                        'std_error': np.std(sample_errors),
                        'max_error': np.max(sample_errors),
                        'percentile_95': np.percentile(sample_errors, 95),
                        'confidence_interval': self._calculate_confidence_interval(sample_errors)
                    }
            
            results['systems_tested'].append(system_results)
        
        # Global statistical summary
        if all_errors:
            results['statistical_summary'] = {
                'total_tests': len(all_errors),
                'passed_tests': sum(1 for e in all_errors if e < 0.01),
                'success_rate': sum(1 for e in all_errors if e < 0.01) / len(all_errors),
                'mean_error': np.mean(all_errors),
                'median_error': np.median(all_errors),
                'std_error': np.std(all_errors),
                'error_distribution': {
                    'percentile_90': np.percentile(all_errors, 90),
                    'percentile_95': np.percentile(all_errors, 95),
                    'percentile_99': np.percentile(all_errors, 99)
                }
            }
        
        # Uncertainty propagation analysis
        results['uncertainty_analysis'] = self.uncertainty_propagator.analyze_mass_balance_uncertainty(
            test_systems, all_errors
        )
        
        return results
    
    def _run_statistical_phase_rule_tests(self) -> Dict:
        """Comprehensive Gibbs phase rule validation with statistical analysis and topology verification"""
        
        # Define comprehensive test systems with known phase rule constraints
        test_systems = [
            # Unary systems
            {'name': 'Pure-Quartz', 'composition': {'SiO2': 1.0}, 'phases': ['quartz'], 
             'components': 1, 'intensive_variables': ['temperature', 'pressure']},
            
            # Binary systems
            {'name': 'Forsterite-Fayalite', 'composition': {'Mg2SiO4': 0.6, 'Fe2SiO4': 0.4}, 
             'phases': ['forsterite', 'fayalite'], 'components': 2},
            
            # Ternary systems  
            {'name': 'Albite-Anorthite-Orthoclase', 
             'composition': {'NaAlSi3O8': 0.4, 'CaAl2Si2O8': 0.3, 'KAlSi3O8': 0.3},
             'phases': ['albite', 'anorthite', 'orthoclase'], 'components': 3},
            
            # Quaternary systems
            {'name': 'Complex-Silicate', 
             'composition': {'SiO2': 0.4, 'Al2O3': 0.2, 'MgO': 0.2, 'FeO': 0.2},
             'phases': ['quartz', 'spinel', 'forsterite', 'fayalite'], 'components': 4}
        ]
        
        results = {
            'phase_rule_analysis': [],
            'topological_consistency': {},
            'variance_statistics': {},
            'critical_point_analysis': {}
        }
        
        # Temperature and pressure ranges for systematic exploration
        temperature_range = np.linspace(600, 1500, 30)
        pressure_range = np.logspace(-1, 2, 20)  # 0.1 to 100 bar
        
        variance_data = []
        
        for system in test_systems:
            system_analysis = {
                'name': system['name'],
                'theoretical_components': system['components'],
                'phase_assemblages': [],
                'variance_map': [],
                'critical_points': [],
                'topological_features': {}
            }
            
            # Systematic exploration of P-T space
            for T in temperature_range:
                for P in pressure_range:
                    try:
                        # Calculate equilibrium phase assemblage
                        equilibrium = self.engine.minimize_gibbs_energy(
                            system['composition'], T, P, system['phases']
                        )
                        
                        # Identify stable phases (above threshold abundance)
                        stable_phases = []
                        phase_fractions = {}
                        
                        for phase_name, phase_data in equilibrium.get('phases', {}).items():
                            fraction = phase_data.get('amount', 0)
                            if fraction > 1e-6:  # Threshold for phase stability
                                stable_phases.append(phase_name)
                                phase_fractions[phase_name] = fraction
                        
                        n_phases = len(stable_phases)
                        n_components = system['components']
                        
                        # Calculate variance (degrees of freedom)
                        # F = C - P + 2 (Gibbs phase rule)
                        variance = n_components - n_phases + 2
                        
                        # Additional intensive variables beyond T and P
                        if 'intensive_variables' in system:
                            variance += len(system['intensive_variables']) - 2
                        
                        variance_data.append(variance)
                        
                        assemblage_data = {
                            'temperature': T,
                            'pressure': P,
                            'stable_phases': stable_phases,
                            'phase_fractions': phase_fractions,
                            'n_phases': n_phases,
                            'n_components': n_components,
                            'variance': variance,
                            'phase_rule_satisfied': variance >= 0,
                            'stability_index': self._calculate_phase_stability_index(equilibrium)
                        }
                        
                        system_analysis['phase_assemblages'].append(assemblage_data)
                        system_analysis['variance_map'].append({
                            'T': T, 'P': P, 'variance': variance, 
                            'n_phases': n_phases, 'assemblage': '_'.join(sorted(stable_phases))
                        })
                        
                        # Detect critical points (variance changes)
                        if len(system_analysis['variance_map']) > 1:
                            prev_variance = system_analysis['variance_map'][-2]['variance']
                            if abs(variance - prev_variance) > 0.5:
                                system_analysis['critical_points'].append({
                                    'temperature': T,
                                    'pressure': P,
                                    'variance_change': variance - prev_variance,
                                    'transition_type': self._classify_phase_transition(assemblage_data)
                                })
                        
                    except Exception as e:
                        # Record failed calculations
                        system_analysis['phase_assemblages'].append({
                            'temperature': T,
                            'pressure': P,
                            'error': str(e),
                            'phase_rule_satisfied': False
                        })
            
            # Topological analysis of phase diagram
            system_analysis['topological_features'] = self._analyze_phase_diagram_topology(
                system_analysis['variance_map']
            )
            
            # Statistical analysis of variance distribution
            variances = [point['variance'] for point in system_analysis['variance_map'] 
                        if 'variance' in point]
            
            if variances:
                system_analysis['variance_statistics'] = {
                    'mean_variance': np.mean(variances),
                    'std_variance': np.std(variances),
                    'min_variance': np.min(variances),
                    'max_variance': np.max(variances),
                    'phase_rule_compliance_rate': sum(1 for v in variances if v >= 0) / len(variances)
                }
            
            results['phase_rule_analysis'].append(system_analysis)
        
        # Global variance statistics
        if variance_data:
            results['variance_statistics'] = {
                'total_calculations': len(variance_data),
                'phase_rule_violations': sum(1 for v in variance_data if v < 0),
                'compliance_rate': sum(1 for v in variance_data if v >= 0) / len(variance_data),
                'variance_distribution': {
                    'mean': np.mean(variance_data),
                    'median': np.median(variance_data),
                    'std': np.std(variance_data),
                    'percentiles': {
                        '25': np.percentile(variance_data, 25),
                        '75': np.percentile(variance_data, 75),
                        '95': np.percentile(variance_data, 95)
                    }
                }
            }
        
        # Topological consistency analysis
        results['topological_consistency'] = self._analyze_global_topological_consistency(
            results['phase_rule_analysis']
        )
        
        return results
    
    def _run_comprehensive_activity_validation(self) -> Dict:
        """Comprehensive activity model validation with thermodynamic rigor and experimental comparison"""
        
        # Define comprehensive test compositions covering the entire composition space
        test_compositions = self._generate_comprehensive_composition_grid()
        
        # Temperature and pressure conditions for validation
        test_conditions = [
            (298.15, 1.0),    # Standard conditions
            (373.15, 1.0),    # Boiling point of water
            (673.15, 1.0),    # Moderate temperature
            (1073.15, 1.0),   # High temperature
            (298.15, 10.0),   # High pressure
            (1073.15, 10.0)   # High T, high P
        ]
        
        results = {
            'model_validation': {},
            'thermodynamic_consistency': {},
            'experimental_comparison': {},
            'statistical_analysis': {},
            'model_ranking': {}
        }
        
        all_model_errors = {}
        
        for model_name, model in self.engine.activity_models.items():
            model_results = {
                'model_name': model_name,
                'test_results': [],
                'consistency_tests': {},
                'boundary_behavior': {},
                'error_statistics': {}
            }
            
            model_errors = []
            
            # Test across all compositions and conditions
            for composition in test_compositions:
                for temperature, pressure in test_conditions:
                    try:
                        # Calculate activity coefficients
                        gamma = model.calculate_activity_coefficient(composition, temperature, pressure)
                        
                        # Validation tests
                        test_result = {
                            'composition': composition,
                            'temperature': temperature,
                            'pressure': pressure,
                            'activity_coefficients': gamma,
                            'validation_results': {}
                        }
                        
                        # Test 1: Reasonable magnitude (0.001 < γ < 1000)
                        magnitude_test = all(0.001 < g < 1000 for g in gamma.values())
                        test_result['validation_results']['magnitude_reasonable'] = magnitude_test
                        
                        # Test 2: Gibbs-Duhem consistency for activity coefficients
                        gibbs_duhem_error = self._test_activity_gibbs_duhem(gamma, composition, temperature)
                        test_result['validation_results']['gibbs_duhem_error'] = gibbs_duhem_error
                        test_result['validation_results']['gibbs_duhem_passed'] = gibbs_duhem_error < 0.01
                        
                        # Test 3: Limiting behavior (Henry's and Raoult's laws)
                        limiting_behavior = self._test_activity_limiting_behavior(gamma, composition)
                        test_result['validation_results']['limiting_behavior'] = limiting_behavior
                        
                        # Test 4: Temperature dependence consistency
                        temp_consistency = self._test_activity_temperature_dependence(
                            model, composition, temperature, pressure
                        )
                        test_result['validation_results']['temperature_consistency'] = temp_consistency
                        
                        # Test 5: Pressure dependence (should be minimal for liquids/solids)
                        pressure_consistency = self._test_activity_pressure_dependence(
                            model, composition, temperature, pressure
                        )
                        test_result['validation_results']['pressure_consistency'] = pressure_consistency
                        
                        # Calculate overall error metric
                        error_metric = self._calculate_activity_error_metric(test_result['validation_results'])
                        test_result['error_metric'] = error_metric
                        model_errors.append(error_metric)
                        
                        model_results['test_results'].append(test_result)
                        
                    except Exception as e:
                        model_results['test_results'].append({
                            'composition': composition,
                            'temperature': temperature,
                            'pressure': pressure,
                            'error': str(e),
                            'error_metric': 1.0  # Maximum error for failed calculations
                        })
                        model_errors.append(1.0)
            
            # Statistical analysis of model performance
            if model_errors:
                model_results['error_statistics'] = {
                    'mean_error': np.mean(model_errors),
                    'median_error': np.median(model_errors),
                    'std_error': np.std(model_errors),
                    'max_error': np.max(model_errors),
                    'percentile_95': np.percentile(model_errors, 95),
                    'success_rate': sum(1 for e in model_errors if e < 0.1) / len(model_errors)
                }
                
                all_model_errors[model_name] = model_errors
            
            # Boundary behavior analysis
            model_results['boundary_behavior'] = self._analyze_activity_boundary_behavior(
                model, test_conditions
            )
            
            # Thermodynamic consistency tests
            model_results['consistency_tests'] = self._comprehensive_activity_consistency_tests(
                model, test_conditions
            )
            
            results['model_validation'][model_name] = model_results
        
        # Cross-model comparison and ranking
        if all_model_errors:
            results['model_ranking'] = self._rank_activity_models(all_model_errors)
            
            # Statistical comparison
            results['statistical_analysis'] = {
                'model_comparison': self._statistical_model_comparison(all_model_errors),
                'best_performing_model': min(all_model_errors.keys(), 
                                           key=lambda m: np.mean(all_model_errors[m])),
                'most_consistent_model': min(all_model_errors.keys(),
                                            key=lambda m: np.std(all_model_errors[m]))
            }
        
        # Experimental data comparison (if available)
        results['experimental_comparison'] = self._compare_with_experimental_activity_data(
            results['model_validation']
        )
        
        return results
    
    def _run_advanced_eos_validation(self) -> Dict:
        """Advanced equation of state validation with rigorous thermodynamic testing and experimental benchmarks"""
        
        # Define comprehensive test systems for EOS validation
        test_systems = [
            # Pure components
            {'name': 'Pure-CO2', 'composition': {'CO2': 1.0}, 'critical_data': {'Tc': 304.13, 'Pc': 73.77}},
            {'name': 'Pure-H2O', 'composition': {'H2O': 1.0}, 'critical_data': {'Tc': 647.10, 'Pc': 220.64}},
            {'name': 'Pure-CH4', 'composition': {'CH4': 1.0}, 'critical_data': {'Tc': 190.56, 'Pc': 45.99}},
            
            # Binary mixtures
            {'name': 'CO2-H2O', 'composition': {'CO2': 0.7, 'H2O': 0.3}},
            {'name': 'CH4-CO2', 'composition': {'CH4': 0.5, 'CO2': 0.5}},
            {'name': 'H2O-CH4', 'composition': {'H2O': 0.8, 'CH4': 0.2}},
            
            # Ternary mixtures
            {'name': 'CO2-H2O-CH4', 'composition': {'CO2': 0.5, 'H2O': 0.3, 'CH4': 0.2}}
        ]
        
        # Comprehensive P-T conditions
        test_conditions = [
            # Subcritical conditions
            (273.15, 1.0), (298.15, 1.0), (373.15, 1.0),
            # Moderate pressure
            (298.15, 10.0), (373.15, 10.0), (473.15, 10.0),
            # High pressure
            (298.15, 100.0), (373.15, 100.0), (473.15, 100.0),
            # Supercritical conditions
            (673.15, 200.0), (773.15, 300.0), (873.15, 500.0)
        ]
        
        results = {
            'eos_models_tested': {},
            'thermodynamic_consistency': {},
            'critical_point_analysis': {},
            'phase_behavior_validation': {},
            'experimental_benchmarks': {},
            'model_performance_ranking': {}
        }
        
        all_eos_errors = {}
        
        for eos_name, eos_model in self.engine.eos_models.items():
            eos_results = {
                'model_name': eos_name,
                'test_results': [],
                'consistency_tests': {},
                'critical_point_predictions': {},
                'phase_envelope_calculations': {},
                'error_statistics': {}
            }
            
            eos_errors = []
            
            # Test across all systems and conditions
            for system in test_systems:
                for temperature, pressure in test_conditions:
                    try:
                        # Calculate EOS properties
                        test_result = {
                            'system': system['name'],
                            'composition': system['composition'],
                            'temperature': temperature,
                            'pressure': pressure,
                            'eos_properties': {},
                            'validation_tests': {}
                        }
                        
                        # Calculate fugacity coefficients
                        phi = eos_model.calculate_fugacity_coefficient(
                            system['composition'], temperature, pressure
                        )
                        test_result['eos_properties']['fugacity_coefficients'] = phi
                        
                        # Calculate compressibility factor
                        Z = eos_model.calculate_compressibility_factor(
                            system['composition'], temperature, pressure
                        )
                        test_result['eos_properties']['compressibility_factor'] = Z
                        
                        # Calculate molar volume
                        V_molar = eos_model.calculate_molar_volume(
                            system['composition'], temperature, pressure
                        )
                        test_result['eos_properties']['molar_volume'] = V_molar
                        
                        # Validation Test 1: Fugacity coefficient bounds (0.01 < φ < 100)
                        phi_bounds_test = all(0.01 < p < 100 for p in phi.values())
                        test_result['validation_tests']['fugacity_bounds'] = phi_bounds_test
                        
                        # Validation Test 2: Compressibility factor bounds (0.1 < Z < 10)
                        Z_bounds_test = 0.1 < Z < 10
                        test_result['validation_tests']['compressibility_bounds'] = Z_bounds_test
                        
                        # Validation Test 3: Molar volume positivity
                        volume_positive_test = V_molar > 0
                        test_result['validation_tests']['volume_positive'] = volume_positive_test
                        
                        # Validation Test 4: Thermodynamic consistency (Maxwell relations)
                        maxwell_consistency = self._test_eos_maxwell_relations(
                            eos_model, system['composition'], temperature, pressure
                        )
                        test_result['validation_tests']['maxwell_consistency'] = maxwell_consistency
                        
                        # Validation Test 5: Ideal gas limit (high T, low P)
                        if temperature > 1000 and pressure < 0.1:
                            ideal_gas_test = abs(Z - 1.0) < 0.01
                            test_result['validation_tests']['ideal_gas_limit'] = ideal_gas_test
                        
                        # Validation Test 6: Incompressible liquid limit (low T, high P)
                        if temperature < 300 and pressure > 100:
                            liquid_limit_test = Z < 0.1
                            test_result['validation_tests']['liquid_limit'] = liquid_limit_test
                        
                        # Calculate overall error metric
                        error_metric = self._calculate_eos_error_metric(test_result['validation_tests'])
                        test_result['error_metric'] = error_metric
                        eos_errors.append(error_metric)
                        
                        eos_results['test_results'].append(test_result)
                        
                    except Exception as e:
                        eos_results['test_results'].append({
                            'system': system['name'],
                            'temperature': temperature,
                            'pressure': pressure,
                            'error': str(e),
                            'error_metric': 1.0
                        })
                        eos_errors.append(1.0)
            
            # Critical point predictions for pure components
            for system in test_systems:
                if 'critical_data' in system:
                    try:
                        predicted_critical = eos_model.predict_critical_point(system['composition'])
                        experimental_critical = system['critical_data']
                        
                        eos_results['critical_point_predictions'][system['name']] = {
                            'predicted': predicted_critical,
                            'experimental': experimental_critical,
                            'relative_error_Tc': abs(predicted_critical['Tc'] - experimental_critical['Tc']) / experimental_critical['Tc'],
                            'relative_error_Pc': abs(predicted_critical['Pc'] - experimental_critical['Pc']) / experimental_critical['Pc']
                        }
                    except Exception as e:
                        eos_results['critical_point_predictions'][system['name']] = {'error': str(e)}
            
            # Statistical analysis
            if eos_errors:
                eos_results['error_statistics'] = {
                    'mean_error': np.mean(eos_errors),
                    'median_error': np.median(eos_errors),
                    'std_error': np.std(eos_errors),
                    'max_error': np.max(eos_errors),
                    'success_rate': sum(1 for e in eos_errors if e < 0.1) / len(eos_errors)
                }
                
                all_eos_errors[eos_name] = eos_errors
            
            # Thermodynamic consistency tests
            eos_results['consistency_tests'] = self._comprehensive_eos_consistency_tests(
                eos_model, test_systems, test_conditions
            )
            
            results['eos_models_tested'][eos_name] = eos_results
        
        # Cross-model comparison and ranking
        if all_eos_errors:
            results['model_performance_ranking'] = self._rank_eos_models(all_eos_errors)
        
        # Experimental benchmarks
        results['experimental_benchmarks'] = self._compare_eos_with_experimental_data(
            results['eos_models_tested']
        )
        
        return results
    
